// ============================================================

//  模块名 : top_m1（集成顶层，测试件，不进交付仓库）

//  作用   : 今晚的目标 —— 把 A 的装载机和 B 的显示链接在一起，

//           上板看到"一张 800x600 的图"

// ------------------------------------------------------------

//  数据通路：

//    SD 卡 ──A 的装载机(top_a)──写口──┐

//                                     ├── sdr_arb ── 片内 SDRAM

//    B 的显示链 ──读口────────────────┘        （SDRAM 例化在 sdr_arb 里）

//    描述符：top_a ──a_desc/commit/ack── desc_rx ──> 合成器的源图参数（可选）

//

//  ★★ 今晚分两遍上板（就差一个 `define）：

//

//    第一遍：**把下面那行 `define USE_DESC 保持注释掉**

//            → 显示参数写死"大槽 0、800x600、valid=1"，变量最少。

//              出图 = 显示链 + A 的写入都对。这一步就是"看到图"。

//

//    第二遍：**把 `define USE_DESC 打开**，重新综合下载

//            → 显示参数改由 desc_rx 给（A 提交的描述符说了算）。

//              出图 = 描述符这条路也通了 = **完整版 M1**。

//

//    两遍都用同一份代码、同一个工程，只是这一行不同 —— 出问题的时候

//    一眼就知道该怀疑哪一段。

//

//  ★ 调试出口（黑屏时全靠它们）：

//      串口 115200：每 0.5 秒一行  W=xxxxxx S=xx F=xx

//        W = A 写了多少个字（**正常 800x600 应当打到 03A980 = 240000**）

//        S = 状态字节（见 dbg_report.v 文件头）

//        F = 帧号低 8 位（一直在变 = 显示链在跑）

//      LED：led0 两个 PLL 都锁 / led1 SD 就绪 / led2 装载完成过 / led3 A 报错

//      数码管：显示 A 的 dbg_wr_cnt（和串口的 W 一样）—— M0 时数码管不亮，

//              所以**以串口为准**，数码管只当参考

//

//  ★★★ 2026-10-17【资源分配优化】串口字段现状（33 格，帧格式/字段数未变）：

//      保留：19/20 = 字幕指纹（C003 / 0951）、27 = sel_aud、28 = 音频+字幕状态位图、

//            29 = rd_defer_max、30 = 读通路 sticky 位图、31/32 = 音频字数/和的低 16、

//            12 bit1 = 块级读被掐断/饿穿过（**饿穿的真判据**）

//      恒 0：21/22/25（原"字幕 RAM 逐字倒出"探针，已连产生逻辑一起删）

//            26（原音频 FIFO 饿穿探针，show-ahead 协议下永不成立，已删）

//            30 的 bit10 同上（位序未变，这一位不再置起）

// ============================================================



// ★ 打开 = 显示参数来自 A 的描述符（完整版 M1）；注释掉 = 写死大槽 0 + 下面那两个尺寸

//   ★★ 2026-10-02 改成【打开】：窗口铺满 800x600，源图尺寸必须跟着图走，

//      写死的话换成 800x600 的图行距就对不上了（花屏）。

`define USE_DESC



// ★★★ 2026-10-17【修 bug ⑤】删掉死宏 `define B_SELFTEST`

// ------------------------------------------------------------

//  它曾经控制"上电先显示 B 自己的自测图"。**现在整个工程里没有任何

//  `ifdef B_SELFTEST`**（grep 过全树：只有这一行的定义）⇒ 它开/关都不产生

//  任何逻辑，但文件头却写着"打开 = 先显示自测图" ⇒ 属于会误导人的死开关。

//  自测图的真正替代品是 `rtl\stub_a_writer.v` + `RENDER_SELFTEST`，

//  要查"是 A 的数据错还是 B 的读取错"请用那一条路（见 交接文档）。

//  ★ 同理，本文件头 12~32 行那段"今晚上板两遍 / 0.5 秒一行 W= S= F= / 数码管"

//    全是 M0/M1 时代的话，与现在的 33 字段 200 ms 帧格式不符；

//    串口字段的**权威说明**在 33~41 行那张表 + `rtl\dbg_report.v` 文件头。

`timescale 1ns / 1ps



module top_m2 #(

    // PLL 报锁定之后，还要【连续稳定】这么久才放开复位（微秒）

    //   ★ 官方例程用的是 20ms（见下面复位那一段）。仿真里可以调小，

    //     不然一次仿真只有几毫秒，等不到。

    parameter integer PLL_WAIT_US = 20000

)(

    input  wire       clk,           // 50 MHz 晶振（R7）

    input  wire       rst_n,         // 硬复位（A2，低有效）

    // ★ 板子丝印与引脚（照《HX4S20 开发板手册》）：KEY1=A2  KEY2=B2  KEY3=B1  KEY4=C1

    //   本工程里 A2 当硬复位，所以只剩三个可用：

    input  wire       key1,          // 丝印 KEY2 / B2：读地址补偿旋钮（调试用，见 0b 节）

    input  wire       key2,          // 丝印 KEY4 / C1：软复位重来

    input  wire       key3,          // 丝印 KEY3 / B1：★ 装载 / 换下一张（skip+1）

    // ★★★ 2026-10-15【参数菜单·第1步】两个**新接**的拨码开关（SW1 / SW2）

    // ------------------------------------------------------------

    //  板上丝印 ↔ FPGA 引脚（三处来源，互为印证）：

    //    · 《HX4S20 开发板手册》p.18 图 2-19：**SW1 = C8** / **SW2 = C7** / SW3 = C6 / SW4 = C5；

    //    · 原理图网名 `NLSWKEY01` = C8、`NLSWKEY02` = C7（SW3 是 `NLSWKEY03` = C6，同一族）；

    //    · 官方 DEMO 约束里 `key[0]`、`key[1]`（`SW[0]`、`SW[1]`）= C8、C7，且都写 `PULLTYPE = PULLUP`。

    //  ★ 约束里**必须** `PULLTYPE = PULLUP`（见 prj\m2_pin.adc）：开关"1"那一侧是**开路**的，

    //    内部不上拉就会悬空乱读 —— 和三个按键、SW3/SW4 同理。

    //  ★ 语义（**用户 2026-10-15 定稿 + 同日"操作方式修订"**，不要再自行发挥）：

    //     · **sw2**（SW2/C7）：每拨动一次 ⇒ 菜单开关 `menu_on` **翻转**（不做方向判断）；

    //     · **sw1**（SW1/C8）：**两档拨动开关 ⇒ 只能当"方向状态位（电平）"用，不能当"上/下按键"**

    //       ⇒ 同步后 `menu_dir = sw1`（1 = 上 / 0 = 下），**它自己不再产生任何脉冲**；

    //     · **KEY3**（B1）：菜单**打开时 = 步进按钮**（每按一次光标按 `menu_dir` ±1，4 项回绕）；

    //       菜单**关闭时照旧换图**（见下面菜单那一段的 ★，那是本步唯一动到的既有连线）。

    //     · SW3 / SW4 / KEY2 / KEY4 本步**一字不改**。

    input  wire       sw1,           // 丝印 SW1 / C8：★ 菜单光标**方向状态位**（电平：1 = 上）

    input  wire       sw2,           // 丝印 SW2 / C7：★ 菜单开/关（每拨一次翻转）

    input  wire       sw3,           // 丝印 SW3 / C6：音频切换（每拨一次 → 下一条 .WAV）

    // ★★★ 2026-10-15【功能 · 开关4 → 字幕水平滚动】

    //   需求（用户原话）："按下开关4后，字幕水平滚动"。

    //   "开关4" = 板上丝印 **SW4** = FPGA 引脚 **C5**。三处来源（和 SW3 那一组同一份，互印证）：

    //     · 《HX4S20 开发板手册》p.18 图 2-19：SW1=C8 / SW2=C7 / SW3=C6 / **SW4=C5**；

    //     · 原理图网名 `NLSWKEY04` = **C5**（和 SW3 的 `NLSWKEY03`=C6 同一族）；

    //     · 官方 DEMO 约束里 `key[3]`（`SW[3]`）= **C5**，且写 `PULLTYPE = PULLUP`。

    //   ★ 约束里**必须** `PULLTYPE = PULLUP`（见 prj\m2_pin.adc）：开关"1"那一侧是**开路**的，

    //     内部不上拉就会悬空乱跳 —— 和三个按键、SW3 同理。

    //   ★ 极性：两份官方文档互相矛盾 ⇒ **本工程不依赖方向**，按【电平】用（不是边沿/脉冲）：

    //       拨到**上拉那一侧（开路侧，丝印 1）= 读 1 = 滚动开**；

    //       拨到**接地那一侧（丝印 0）= 读 0 = 滚动关**（字幕立刻回到静止原位）。

    //     ⇒ 万一手里的板子方向相反（手册那句写反了），只需把下面 `sw4_p2` 取反一处。

    //   ★ 为什么**不用** sw_edge_debounce（sw3 用的那个）：那个是"**变化**给一拍脉冲"的语义

    //     （每拨一次 = 一个事件，用于 +1 选音频）；本需求是"**拨到某一侧就滚动**"的**门控/电平**

    //     语义，而且抖动天然被滤掉（见下面同步那一段的 ★）：`scroll_x` 只在**帧首**看它一眼。

    input  wire       sw4,           // 丝印 SW4 / C5：★ 字幕水平滚动使能（电平）



    // ---- SD 卡（SPI）----

    output wire       sd_ncs,

    output wire       sd_dclk,

    output wire       sd_mosi,

    input  wire       sd_miso,



    // ---- 调试 ----

    output wire [3:0] led,

    output wire [5:0] seg_sel,

    output wire [7:0] seg_data,

    output wire       uart_tx,
    output wire       spk,            // 2026-10-21 on-board buzzer (H11); beeps during alarm



    // ---- HDMI ----

    output wire       HDMI_CLK_P,

    output wire       HDMI_D0_P,

    output wire       HDMI_D1_P,

    output wire       HDMI_D2_P,

    output wire       HDMI_DDC_SCL,

    inout  wire       HDMI_DDC_SDA

);



    // ============================================================

    //  ★ 跨小节用到的连线统一在最前面声明

    //    （Verilog 里"先用后声明"会生成隐式网线，再声明就报

    //      "already declared" —— 踩过一次，别再动顺序）

    // ============================================================

    // A 的写口

    wire        a_wr_req;

    wire [20:0] a_wr_base;

    wire [20:0] a_wr_len;

    wire [31:0] a_wr_data;

    wire        a_wr_we;

    wire        a_wr_full, a_wr_ack, a_wr_done;   // ★ 2026-09-28 原厂协议

    wire        sdr_ready;                     // SDRAM 初始化完成（A 和自测图都要用，先声明）



    // ★★★ 2026-10-15【逐步减重 · 第①步】B 自测图写入器 `stub_a_writer` 已删除。

    //   旧版里它的 busy 【本来就是恒 0】：复位就把 stwr_fired 置 1 ⇒ start 永不发 ⇒

    //   它从不开机自测。所以这里改成常量 0，下游四处（写口二选一 / 读闸门 /

    //   disp_rst_hold / 串口 flags bit3）的行为和删之前【逐拍一致】。

    wire        stwr_busy = 1'b0;



    // 显示链送给 HDMI 的像素（自检模块也要用同一份）

    wire [15:0] rgb565_w;

    wire        de_w, vs_w;

    wire [11:0] dbg_x, dbg_y;



    // ★★★ 2026-10-16【清理冗余 viz + 修 top_a 多重驱动】：

    //   这里原来声明了 8 根**只服务队友那套 viz_top 的悬空网线**：

    //     viz_hist_mask/band/color、viz_freq_mask/band/color、viz_dbg_freq_win/dump。

    //   ★ 它们**从来没有驱动源**（只是一个占位声明 + 往 disp_top 的输入端口上送），

    //     而队友那套 viz 已从 disp_top 里摘除（装不下：mslice 5564 > 硬墙 4900）

    //     ⇒ 这 8 根连声明一起删。

    // ★★★ 2026-10-17【音频可视化整层砍除】：原来这句还写着"保留 viz_bars 走的

    //   aud_dbg_vld/dout/next 三根"。现在自研那套 viz_bars 也砍了 ⇒

    //   **aud_dbg_dout / aud_dbg_next 两个端口和网线一起删**（只留 aud_dbg_vld，

    //   它是串口字段 28 bit3 的"有音频数据流"判据，跟可视化无关）。

    //   ★ 备份与还原：`E:\FPGA\ygcom\.viz_backup_20261017\`。



    // ============================================================

    //  ★★★ 2026-10-03 第二版（上板才知道的）★★★

    //   第一版只做了"突发期间让读等一等"，结果**上板还是花**：

    //   旧图在装载期间就出现稀疏线状花屏，而且写进去的新图也带花（越按越多）。

    //   ⇒ 坐实了 M0 那条结论：**读写只要有重叠就会互相破坏**（读会读到错的、

    //     写也会写坏）。光"错开一拍"不够，必须**在时间上彻底分开**。

    //

    //   做法：用现成的背压 `a_wr_full` 把 A 的推字**只放行到"显示刚才没在读"的窗口**：

    //        push_win = 显示连续 ≥32 拍没有读请求（显存域，同步到控制域）

    //        A 看到的 full = 真 full | ~push_win

    //   ⇒ A 在"显示正在搬行"的时候自动停手（背压是正统握手机制，一个字都不丢），

    //     于是 FIFO 只在"显示没在读"的窗口里长，**写引擎的突发也就只从那种窗口里起**；

    //     突发本身再由下面的 `mem_rd_ok` 让显示让几拍路 —— 两者在时间上分开。

    //   ★ 窗口有多宽：一行 26.4 µs 里，显示只在开头 ~6.4 µs 搬这一行，

    //     其余 ~20 µs 都是窗口 → A 最多停一行时间，**吃得下**。

    //   ★ 为什么不用"整帧消隐"（第一版）：那样子 A 一停就是 16 ms 一帧一次

    //     —— 上板实测**第一张图都装不出来（纯白底）**，A 的流式写口受不了这么长的停。

    //   ★ 会不会变慢：窗口占一行时间的 ~75%，而装着速率的瓶颈是 SD（~17,000 字/秒），

    //     FIFO 每 20 ms 才攒够一次突发 → 放行窗口足够，装载速度不变。

    //   ★ 上板判读：还是花 → 把第 2b 节那行 `define LOAD_WITH_READS 关掉

    //     （退回"整段禁读"的三步方案）。

    // ============================================================

    // ★★ 关键实验用：自测图正在写的时候，把"显示的读"关掉

    //    （M0 踩过"读写同时抢同一颗 SDRAM → 读出来的数据是错的"这个坑）

    wire        disp_rd_en_g;

    // ★★★ 2026-10-06：块级读通路的连线（见第 3b 节）

    wire        d_blk_req_raw;              // 行缓冲的块请求（未过闸门）

    wire        d_blk_req;                  // 过了"装载期间禁读"闸门的块请求

    wire [20:0] d_blk_base, d_blk_len;

    wire        d_blk_want;

    wire        blk_rd_req, blk_rd_re;

    wire [20:0] blk_rd_base, blk_rd_len;



    // ★ 显示链的读请求/读地址（disp_top 的输出）—— 提前声明：

    //   下面 0c 节"只放行到显示没在读的窗口"要用它（ModelSim 不许先用后声明）

    wire        disp_rd_en;

    wire [20:0] disp_rd_addr;

    // ★ 显示链的读请求/读地址（disp_top 的输出）—— 提前声明：

    //   第 1b 节"只放行到显示没在读的窗口"要用它（ModelSim 不许先用后声明）



    // ★ 写引擎活动状态（sdr_arb 引出来，给读口握手用；见下面第 2b 节）

    wire        wr_burst, wr_guard;

    wire        occ_hi_w;                  // ★ sdr_arb 报的'占用已满'（occ>=512）

    wire        occ_pre_w;                 // ★ sdr_arb 报的"快到突发了"（occ>=240）

    // ★ rd_mute（"万一 A 卡死"的 300 秒兜底）在下面才赋值，但第 2b 节的

    //   读口握手要用它 —— 先声明（ModelSim 不允许先用后声明）。

    wire        rd_mute;



    // ---- ★ 转场相关的跨域信号（★ 必须先声明：下面第 1a 节的同步器、

    //      以及后面描述符那一段都要用；ModelSim 对"先用后声明"会报重复定义）----

    wire        tr_req;         // 像素域：一拍请求

    wire [1:0]  tr_fx;          // 像素域：淡入用哪种特效

    wire        tr_may_load;    // 像素域：屏上全米白，A 可以去写

    wire        tr_active;      // 像素域：正在转场

    wire        tr_swap;        // 像素域：一拍，请对调前台/后台

    wire        tr_show_back;   // 像素域：现在"该显示的是后台那张"（装载/淡入）

    // ★ 2026-10-04：特效从哪一端开始 —— 装载期间整段禁读（屏上米白）时用 1，

    //   否则装载一结束旧图会被读回来，"从旧图开始划"就会先闪一下旧图。

    wire        tr_from_white;



    // ---- 行探针（8 个固定行）+ 诊断计数 ----

    // ★★★ 2026-10-15【逐步减重 · 第①步】`chk_row0..7` 是 `pix_check` 的输出，

    //   删模块后连线一并删除（它们本来就没接到任何下游）。

    wire [15:0] lb_drop, lb_abort;

    wire [15:0] lb_off, lb_alignbad;   // 逐字对齐校验（地址图专用）

    // ---- 读口自测（★ 2026-09-27 下午换成"官方读侧"，见 rtl\vendor_read_test.v）----

    wire        st_busy, st_done, st_rd_en;

    wire [20:0] st_rd_addr;

    wire [15:0] st_read_cnt, st_bad, st_off, st_first;

    wire [15:0] st_w0, st_w1, st_w2, st_w3;

    wire        st_rd_en_m;            // 读口二选一（下面 assign）

    wire [20:0] st_rd_addr_m;

    // ★★★ 2026-10-15【逐步减重 · 第①步】`stwr_done_lat / st_dly / st_go` 只服务

    //   "自测图写完 50ms 后跑一次读口自检"，读口自检本身 2026-10-09 就删了

    //   ⇒ 这一组是纯死逻辑，随 stub_a_writer 一起删。



    // ============================================================

    //  ★★★ 2026-10-05：音频链（A 轨 top_aud）的跨小节连线与命令

    //     —— 全部在这里声明（Verilog 不许"先用后声明"，这个工程踩过五次）

    // ============================================================

    // 音效区参数（★ 必须和 A 的 sfx_ctrl 里那两个数【完全一致】）

    // ★★★ 2026-10-11 v9【契约变更（用户批准）】：音频区提到"两个大槽"后面、并定长 120000 字。

    //   旧账：原来音频基址 1861660 正好是小槽区（缩放/缩略图）的起点 ⇒ 两者整块重叠

    //   ⇒ 图像一往小槽写就把音乐盖掉（实测抓到的音频字是打包过的 RGB565 像素）⇒ 一片沙沙。

    //   现在：音频 1861660..1981660（120000 字 = 5 秒 @48k），小槽区挪到 1981660 起。

    //   ★ 契约见 artwork_def.v v9；A 的 sfx_ctrl/top_aud 里那两个**默认参数**要跟着同步

    //     （本工程是顶层显式传参覆盖的，所以不传也行，但默认值别留着误导人）。

    //              ★★★ 2026-10-14 深夜【查爆音·搬基址】原 21'd1861660（契约 SDRAM_AUDIO_BASE）+16384 字；仍在音效区内 [1861660,1981660)

    //              ★★★ 2026-10-14 深夜【功能·开关切音频】探针用完，**还原成契约值**：

    //                  +16384 那一版是"查爆音"时的临时搬运，结论早就有了；现在只有**一个**音效槽，

    //                  地图必须精确 ⇒ 回到 21'd1861660。

    //                  ★ 交付仓 `工程代码\rtl\common\artwork_def.v` 里 `SDR_AUDIO_BASE` 也是

    //                    21'd1861660（v9），**这两处必须一致**（改了这里就得同步契约，两人确认 + 升版本）。

    //                  校验：1861660 + 120000 = 1981660 = 音效区末尾 = 契约 `SDR_SMALL_BASE` ✓

    localparam [20:0] SFX_BASE    = 21'd1861660;   // = 契约 v9 `SDR_AUDIO_BASE`

    // ★★★ 2026-10-13【第二处修复 · 播放长度】：装载端写的是**文件真实长度**

    //   （`top_a.v`: `sfx_words = smp_cnt[20:1]`，mus0 = 86640 字 ≈ 3.61 s），

    //   而播放端（`a_image\sfx_ctrl.v`: `sfx_words <= SFX_STRIDE`）用的是 **stride**。

    //   v9 把 stride 提到 120000 字（5 s）⇒ **播放会越过有效数据 1.4 s**，那一段是

    //   从没被写过的 SDRAM ⇒ 上板表现"音乐放完之后又出现沙沙"。

    //   ⇒ 先回到 RC3 的 72000（3 s，永远只放有效数据）；**正式修法**是让播放端用

    //     "实际装入的字数"（把 `top_a` 的 `smp_cnt[20:1]` 引到 `sfx_ctrl` 的 `sfx_words`），

    //     见《B轨待改清单》§30.8。

    localparam integer SFX_STRIDE = 120000;   // ★★★ 回到契约 v9 的 120000（72000 会截掉 mus0.wav 最后 0.6 秒）；放完后的杂音改由「播放长度=实际字数」解决，不再靠缩短长度

    // ★★★ 2026-10-15【音频溢出保护】：音效区容量（字），21 位、和 a_wr_len 同宽 ——

    //   唯一来源就是上面那条 SFX_STRIDE（契约 v9 校验：1861660 + 120000 = 1981660 ✓）。

    //   两处夹子都用它：① 播放长度（下面 latch `aud_words_act` 处）

    //                   ② 装载长度（传给 top_a 的 AUDIO_MAX_WORDS）

    localparam [20:0] SFX_WORDS_CAP = SFX_STRIDE;

    // ============================================================

    //  ★★★★ 2026-10-06【音频回退开关】AUDIO_OFF

    //    = 1：**完全不启动音频链** —— 不装音效、不播放 ⇒ 音频一个读都不发

    //         ⇒ 显示回到"只有转场（10-04 那版）"的干净行为：图正常、**没有白条**。

    //         上板证据：22:06 那版（音频被饿到几乎没声）用户反馈"白条纹不在了"，

    //         而两次把显示弄坏（白屏/白条）的改动都在**读口**上 ——

    //         合起来说明 **干扰显示的是"音频那边的读"**，不是显示自己读得快。

    //    = 0：恢复音频（音乐 + 已知的沙沙声）。

    //    ★ 修音频时把它改回 0 即可，装音效/播放的逻辑一行都没删。

    // ============================================================

    // ★★★★ 2026-10-06 晚【音频改走块级读口】—— 开关打回 0

    //   上一档（=1）是过渡档："先把显示的块级读通路单独验干净，音频一条读都不发"。

    //   现在显示那条路已经在仿真里逐像素验过（tb_m2_blk_chain 19200/19200 全对），

    //   音频也换成【同一个仲裁器的音频口】（a_image\aud_blk_rd.v），

    //   所以打回 0：自动装音效 + 每次换图自动播一次。

    //   ★ 音频饿不死显示：块口是**显示优先**，而且两头都有看门狗兜底

    //     （blk_rd_arb 的 SERV_MAX + aud_blk_rd 的 SERV_MAX）。

    localparam AUDIO_OFF = 1'b0;



    // 读口绕道（line_buf ↔ top_aud ↔ sdr_arb）—— ★ 2026-10-06 起这几根全部作废：

    //   line_buf 走块口、音频也走块口，谁也不再用"逐拍 disp_rd_en/addr"。

    //   保留 `aud_line_req` 只是给串口的 flags 字段看着（它不再是任何读口的驱动）。

    wire        aud_line_req;



    // 音频链的其它线

    wire        clk_aud, pll_aud_locked;

    wire        aud_busy_w;           // top_aud 报"还在读/放"

    // ★ 音频域复位：等音频 PLL 也锁上（sys_rst_n 里已经含另外两个 PLL）

    //   ★★ 只能先声明、后面再 assign —— sys_rst_n 的声明在下面几百行，

    //      在这里直接写等式会造出隐式网线，ModelSim 会报"already declared"。

    wire        aud_rst_n;

    wire        hdmi_audio_valid, hdmi_acr_valid;

    wire [23:0] hdmi_audio_left, hdmi_audio_right;

    wire [19:0] hdmi_acr_cts, hdmi_acr_n;

    // 音频诊断（先接线网 / 进串口，见字段 28）

    wire [20:0] aud_dbg_base, aud_dbg_words;

    wire        aud_dbg_vld, aud_dbg_play_tgl;

    // ★ 2026-10-17【音频可视化】：viz 只旁听的另外两根（top_aud 已重新引出）

    wire [31:0] aud_dbg_dout;

    wire        aud_dbg_next;

    wire [15:0] aud_dbg_cnt;            // ★★ 第 8 条：音频数据自检（字数）

    wire [31:0] aud_dbg_sum;            // ★★ 第 8 条：音频数据自检（32 位和）

    // ★★★ 2026-10-17【资源分配优化】：原 `aud_dbg_underrun`（2026-10-09 块级 FIFO 饿死

    //   探针）随 `aud_blk_rd.o_underrun` / `top_aud.dbg_aud_underrun` 一起删除。

    //   ★ 它原来进两处：串口**字段 26**（现改送常量 0，帧格式/字段数一字未动）与

    //     `dbg_chain[10]`（见下面那段，位序不变，该位现在恒 0）。

    //   ★ 真判据仍在，一个字没删：`aud_blk_stall`（= blk_rd_arb 的块级掐断 sticky）

    //     走 **字段 12 的 bit1** 与 **字段 30 的 bit10**。

    // ---- ★★★ 2026-10-06 音频的块级读口（top_aud ↔ blk_rd_arb 的音频口）----

    wire        aud_a_req;              // top_aud → 闸门

    wire        aud_a_req_g;            // 闸门后 → blk_rd_arb.a_req

    wire [20:0] aud_a_base, aud_a_len;

    wire        aud_a_gnt, aud_a_next;

    wire [31:0] blk_a_data;

    wire        aud_blk_stall;

    // ★ 装载期间禁读闸门（先声明，赋值在下面第 8 节前）—— 显示和音频共用

    wire        disp_rd_gate;



    // 音频装载 / 播放的小状态机（C 轨还没接，这里自产命令）

    reg         aud_want;             // 1 = 这一次装载是"装音效"

    reg         aud_loaded;           // 音效已经在 SDRAM 里了

    reg         aud_fail;             // 音效装载失败过（不再重试）

    reg         aud_load_pulse;       // → A 的 start

    reg         aud_play_req;         // → sfx_ctrl 的 play_sfx（一拍）

    // ★★★ 2026-10-17【修 · 换音频失真】→ sfx_ctrl 的 stop_sfx（一拍）：换音频前先把上一首停掉。

    //   不加这一根的话会有一个竞态：`sfx_ctrl` 是"播放中（busy）就丢掉新 play 命令"，

    //   而 busy 要等整首词发完才落、装载期间音频读又被掐断 ⇒ 装载完那一拍 play 被丢，

    //   旧指针（旧 base/旧字数）继续读**已被覆写**的音效区 ⇒ 听感就是"失真/串味"。

    reg         aud_stop_req;

    // ★★★ 2026-10-17【修 lint · 消除 HDL-7225】：`aud_words_act` 原来声明在音频状态机那段

    //   （第 2173 行附近），但它的**首次使用**是更上面的 `u_aud` 端口连接（现在 2082 行附近）

    //   ⇒ TD 报 `CRITICAL-WARNING: 'aud_words_act' is already implicitly declared`

    //   （隐式声明是 1 位网线；TD 这次把它并到了显式 reg 上，播放长度的夹取实测是对的，

    //    但这属于"能编译、语义靠工具兜底"的隐患）⇒ **声明挪到所有使用之前**。

    reg  [20:0] aud_words_act;        // 本次装入音效的【实际字数】（a_wav_done 时刻 latch a_wr_len）

    reg  [1:0]  aud_st;               // 0=等图 1=等 1 秒 2=装载中 3=做完

    reg  [25:0] aud_wait;



    // ============================================================

    //  ★★★ 2026-10-08【字幕：装载 + 叠加】—— 最小可用版

    // ------------------------------------------------------------

    //  两件事：

    //   ① 装载：上电后（**等音频那条自检做完**，避免两个"自产装载"撞车）

    //            自动装**卡里第 1 条 .SUB**：sd_mode=2 / skip=0 / sub_base=字幕区基址。

    //   ② 叠加：disp_top 的第 ④ 级（subtitle_ovl）把遮罩叠到画面上，

    //            **bit=1 画黑（字）、bit=0 透传**。

    //  ★ 位置先给一个暂定值（贴底居中），但**是"顶层 -> disp_top -> 模块"的端口**，

    //    不是常数 —— 以后 C 轨的窗口表（`WIN_SUB` 那一条）直接替掉这几个 wire 即可。

    //  ★ 极性/尺寸全部按契约：800×64 1bpp，SDR_SUBTITLE_BASE / _STRIDE。

    // ============================================================

    // ★★★ 2026-10-11【一次性诊断：用"字幕那条已证明无害的取数机器"去看**音频区**】

    //   背景：音频一直是沙沙声；我用手写的小探针抓过 32 个字，和卡上 WAV 对不上，

    //   但那一版顺手加了 ~700 LUT 把布局挤坏（白条 + 没声音），所以结论不作数。

    //   这一版【**一行新逻辑都不加**】：只把字幕那条链的**取数基址**指到音频区、

    //   并把叠加位置挪到屏幕外（这样屏上不会多出一块噪声）。

    //   取数机器本来就在 `b163417` 上验证过是逐字精确的（字幕 0/1600 全对）。

    //   ★ 偏移 1000：mus0.wav 的第一个"有声"字在第 1128 个、mus1.wav 在第 2571 个

    //     ⇒ 取 [1000, 2600) 这一段正好把**两条 WAV 的起音**都包进来（前面应当是一串 0）。

    //   ★ 字段 19/20 = 这段的"和 / 第一个非零字"，字段 21/22/25 = 逐字倒出。

    //   ★★★ 2026-10-11 修正：**上一版把基址搞错了** —— `SUB_BASE` 是"装载**写**"和

    //     "取数**读**"**共用**的（顶层 a_sub_base 与 disp_top.sub_base 都用它），

    //     所以改它等于把 .SUB 写到了音频区、把音频数据盖掉（串口倒出来就是字幕遮罩）。

    //   ⇒ 现在拆成两个：**装载写**仍旧用 SUB_BASE（字幕区，不动）；

    //     **取数读**用下面这个 SUB_FETCH_BASE（音频区）—— 只改"读"。

    //   ★ 查完把 SUB_FETCH_BASE 改回 2085760、SUB_Y0_DFLT 改回 528 即可。

    localparam [20:0] SUB_BASE       = 21'd2041660;   // ★ v9 契约 SDR_SUBTITLE_BASE（装载写这里）

    // ★★★ 2026-10-11【契约 v9 之后的第二次诊断】：音频区和小槽区已经分开了，

    //   现在倒一次**音频区**（第 1000 个字起）确认那里装的是不是 WAV 的采样：

    //   mus0.wav 开头 1128 个字是静音、之后才起音 ⇒ 期望"约 128 个 0 + 起音"。

    //   （读这条路是逐字验证过的；叠加位置在屏幕外，屏上不会多画东西。）

    // ★★★ 2026-10-13【收尾还原 · 按接手指引 §3】：探针归还，字幕回到正式配置 ——

    //   取数读用**字幕区**（= SUB_BASE），叠加位置回到屏幕底部（y = 600-64-8 = 528）。

    // ★★★★ 2026-10-14【§30.18 判定用 · 临时，验完必须立刻改回 SUB_BASE 并重验字幕指纹】：

    //   探针指到**音频区起点** ⇒ 按一次 KEY3（触发重装）前后各倒一遍，

    //   与 tools\audio_expect.md 期望表逐字比 ⇒ 判定"重装后的数据"对不对。

    localparam [20:0] SUB_FETCH_BASE = SUB_BASE;      // = 字幕区（正式配置）

    localparam [3:0]  SUB_SKIP   = 4'd0;          // 卡里第 1 个 .SUB（在自己的扩展名里数）


    // ★★★ 2026-10-23【字幕双缓冲 + 跟图切换】
    //   要修的两件事：
    //     ① 字幕只在开机装过一次（`sub_st` 走完 0→1→2→3 就停在 done 态），
    //        之后切图字幕内容永远不变 ⇒ 图文对不上；
    //     ② 装载写和显示读**共用 SUB_BASE**（:750 的老注释也承认了），
    //        想"每张图重装字幕"就会边写边读 ⇒ 撕裂/闪。
    //   做法：字幕区本来就是 3200 字 = 两条 1600 字的槽（一条字幕 800×64/32=1600 字）。
    //     · 写：永远写**不在显示**的那一槽（sub_wr_sel = ~sub_rd_sel）
    //     · 读：显示当前槽 —— ★ 2026-10-23 起不再在这里算出 21 位基址，
    //       而是把 `sub_rd_sel` 这一位送进 subtitle_ovl，在**它自己的时钟域里**
    //       2 级同步 + 每趟取字起点锁存（原因见 subtitle_ovl 里那段注释：
    //       21 位基址直接跨 50 MHz → 125 MHz 会在换槽那一拍拼出错地址）。
    //     · 装完才把 sub_rd_sel 翻到新槽 ⇒ 全程无撕裂；装失败就保持旧字幕
    //     · 序号：槽 0 装卡里第 1 条 .SUB、槽 1 装第 2 条 ⇒ 切图时两条交替显示
    localparam [20:0] SUB_SLOT_WORDS = 21'd1600;   // 一条字幕的容量
    reg  sub_rd_sel;                               // 1 = 显示槽 1（物理 +1600）；复位 1 ⇒ 开机先往槽 0 写

        reg         sub_swap_pend;
    reg         sub_rd_sel_next;   // ★ 2026-10-23：下一帧要显示的槽（帧首才兑现）
    wire        frame_start_pix;   // ★ disp_top 导出的帧首单拍（clk_pix 域）

    reg  [25:0] sub_swap_wait;                      // ★ 等翻槽的帧计数（1 s 超时��路用）                      // 1 = 字幕已装好，等 tr_active 落下再翻显示槽
    wire sub_wr_sel  = ~sub_rd_sel;
    wire [20:0] sub_wr_base = SUB_BASE + (sub_wr_sel ? SUB_SLOT_WORDS : 21'd0);

    // 暂定位置：800×64 的字幕条贴在屏幕底部（y = 600 - 64 - 8 = 528）、横向居中

    localparam [11:0] SUB_X0_DFLT = 12'd112;    // ★ 1024×768：800 宽字幕带水平居中

    localparam [11:0] SUB_Y0_DFLT = 12'd696;      // ★ 1024×768：768-64-8 = 696

    localparam [11:0] SUB_W_DFLT  = 12'd800;      // 契约 ART_SUB_W

    localparam [11:0] SUB_H_DFLT  = 12'd64;       // 契约 ART_SUB_H

    localparam [15:0] SUB_INK     = 16'h0000;     // ★ bit=1 画这个颜色（黑 = 文字）

    // ★★★ 2026-10-09 一次性诊断开关：=1 ⇒ **左半屏画自产 8×8 棋盘、右半屏画真字幕**。

    //   左半屏整齐 ⇒ 显示这一级没问题（问题在卡上的素材）；左半屏也歪 ⇒ 显示这一级的问题。

    //   ★ 诊断完改回 0 重新出比特流即可（纯显示级开关，不影响别的）。

   localparam SUB_TPAT = 1'b0;   // ★ 2026-10-09 晚：诊断结束（左半屏棋盘已确认显示级是对的），

                                 //   关掉它 ⇒ 整条 800×64 全画真字幕；数据指纹走字段 19/20。



    wire        a_sub_done;           // ← top_a：这一条字幕写进 SDRAM 了（单拍）

    reg         sub_load_pulse;       // → A 的 start（单拍；sd_mode 也由它选）

    reg         sub_loaded;           // 字幕已经在 SDRAM 里了（= 叠加的 on）

    reg         sub_fail;             // 装载失败过（就当没有字幕，不再重试）

    reg  [1:0]  sub_retry;            // 2026-10-23：同一趟最多再重试 2 次（SD 前端偶发丢字节）

    reg  [1:0]  sub_st;

    reg  [25:0] sub_wait;

    // ★★★ 2026-10-23【字幕提速 · 别让预装抢走 SD 前端】
    //   `sub_pend_w` = 字幕"想装 / 正在装"（状态 1/2）。
    //   预装（prefetch）和字幕都走同一个 A 链，预装先开跑就会把字幕堵到
    //   整张图装完（大图 1 s 以上）⇒ 屏上"图出来了、字幕半天不来"。
    //   ⇒ 顶层的 `pf_go` 与它相与（见下面 pf_go_w），字幕优先。
    wire        sub_pend_w = (sub_st == 2'd1) | (sub_st == 2'd2);
    reg         sub_req_pend;   // ★ 字幕欠一次装（用来压住音频，字幕优先）

    // ---- ★★ 2026-10-09【字幕探针】上板看不到字，就靠这几个数定位 ----

    reg         sub_pulse_lat;        // sticky：字幕装载脉冲发出去过

    reg         sub_done_lat;         // sticky：a_sub_done 回来过

    wire        a_dbg_sub_overrun;    // ← top_a/sub2sdram：丢字

    wire        a_dbg_sub_short;      // ← top_a/sub2sdram：字数对不上

    // ★★★ 2026-10-21【D3 · C2/C3】素材格式信号（由 top_a 透传上来）

    wire [15:0] a_img_bpp;            // 最近一次 BMP 头的位深（24 = 正常）

    wire [31:0] a_aud_rate;           // 最近一次 WAV 的采样率（48000 = 正常）

    wire [15:0] a_aud_bits;           // 位深（16 = 正常）

    wire        a_aud_iv;             // 上面两个值有效

    wire [31:0] a_dbg_sub_wr_cnt;     // ← top_a/sub2sdram：写了多少字（期望 1600）

    // ★ sub_loaded 是 50 MHz 域的电平，要送进像素域用 ⇒ 两位同步器（和预装那条一个做法）

    reg         sub_on_s1, sub_on_s2;



    // ★★★ 2026-10-15【功能 · 开关4（SW4 / C5）→ 字幕水平滚动】跨域用的四级同步寄存器

    //   （声明放在这里、例化/赋值放在下面 1a 节末尾 —— Verilog 不许"先用后声明"，本文件踩过五次）

    reg         sw4_s1, sw4_s2;      // 50 MHz 域：引脚（异步输入）两级同步

    reg         sw4_p1, sw4_p2;      // 像素域：再两级同步 ⇒ 送给 disp_top 的就是 sw4_p2



    // ---- ★ 三选一：谁在发脉冲，sd_mode/skip/基址 就是谁的 ----

    //   ★★ 用【脉冲】而不是"电平"来选：top_a 本来就是在 `start` 那一拍锁存 sd_mode 的，

    //      而电平一旦因为失败没清干净，就会把后面的"装图"也带偏（装载中易主）。

    //      （原来音频用 aud_want 电平选，这版一起改成脉冲 —— 行为等价，但更不容易错。）

    // ★★★★ 2026-10-13【音频沙沙的真凶 · 修复】：

    //   原来这里是 `aud_load_pulse`（**单拍脉冲**）—— 脉冲只有一拍有效，而

    //   `top_a` 里 `skip` / `sfx_base` 是**直通使用、没有锁存**的（只有字幕的 `sub_base_r`

    //   做了锁存）⇒ 从第二拍起 `a_sd_skip`/`sfx_base` 就变回"装图那套"（`0`）

    //   ⇒ **音频数据在装载途中被写坏** ⇒ 上板一片沙沙。

    //   ★ 为什么只有音频中招：图像链本来就是 `sd_mode=0` 这一档，不受影响；

    //     字幕链的基址已经锁存过；**只有音频依赖"整段传输期间稳定"**。

    //   ⇒ 改回 RC3 的**电平**语义（`aud_want` 从发脉冲举到装完才清；装完/失败两条路都会清，

    //     所以不会把后面的装图带偏）。**已上板验证：音乐正常**。

    // ★ 2026-10-21【报警换图】报警边沿强制装一次 EMG* 图（不走轮播，避免 skip 语义混乱）

    reg        img_load_pulse;   // 单拍：我自己发一次「装图」

    reg        img_req_pend;     // 有待发的换图请求

    reg        img_hold;         // ★ 2026-10-21：报警换图独占 SD（从脉冲起到 a_load_done/a_fail），压住音频/字幕去抢
    reg  img_now;            // 1 = 这次请求是热插拔触发的，不等 0.5 s

    reg [25:0] img_wait;

    wire [1:0]  a_sd_mode  = (img_load_pulse || img_hold) ? 2'd0 : (sub_load_pulse ? 2'd2 : (aud_want ? 2'd1 : 2'd0));

    wire [20:0] a_sub_base = sub_load_pulse ? sub_wr_base : 21'd0;



    // ============================================================

    //  ★★★ 2026-10-14 深夜【功能·开关3 切音频】

    //  需求（用户原话）："用开关3做音频切换，每改一次方向，就换下一个音频。"

    // ------------------------------------------------------------

    //  ★ "开关3"= 丝印 **SW3** = FPGA 引脚 **C6**。三处来源（都查过，互为印证）：

    //      · 《HX4S20 开发板手册》p.18 图 2-19：SW1=C8 / SW2=C7 / **SW3=C6** / SW4=C5；

    //      · 原理图网名 `NLSWKEY03` = **C6**；

    //      · 官方 DEMO 约束里 `key[2]`（`SW[2]`）= **C6**，且都写 `PULLTYPE = PULLUP`。

    //      （另：`prj\m2_pin.adc` 里 `sw3` 也必须写 `PULLTYPE = PULLUP` ——

    //        开关"1"那一侧是**开路**的，内部不上拉读数就会悬空乱跳。）

    //    ★ 极性：拨上=1 / 拨下=0，但**两份官方文档互相矛盾** ⇒ 不猜方向：

    //      用本工程新写的 `lib\util\sw_edge_debounce.v`（稳定后**任意方向**变化给一拍脉冲）。

    //    ★ 为什么不用 `key_press_debounce`（KEY3 用的那个）：它只认 1→0 那一半，

    //      拨码开关两个方向都是有效操作；而且它的复位初值是"不按=1"，对拨码开关不成立

    //      （上电会白多一拍）。详见 `lib\util\sw_edge_debounce.v` 文件头。

    //    ★ 顶层端口 ↔ 板上丝印（照《HX4S20 开发板手册》）：KEY1=A2  KEY2=B2  KEY3=B1  KEY4=C1，

    //      其中 **A2 已经被硬复位 `rst_n` 占用** ⇒ 本工程端口 `key1/key2/key3`

    //      实际是板上 **KEY2(B2) / KEY4(C1) / KEY3(B1)**（见上面端口表 + 下面 u_ctrl 的接法）。

    //    ★ 和音频选择彻底解耦：换图按键（2026-10-17 起是 KEY2）只驱动 stub_ctrl，**不再顺带换音频**。

    //

    //  选择寄存器 `sel_aud`：在 `SFX_NUM` 条之间循环，**SW3 每拨一次 +1**（自动换歌见下面"一图一乐"）。

    //    ★ 位宽由 `SFX_NUM` 决定（2 条 ⇒ 1 位），改条数时只改上方的 localparam 即可。

    //    ★ `sel_aud` 的**递增**和"重装+重播"脉冲放在同一个 if 里（见下面音频状态机那段），

    //      所以三个"要动的东西"（skip / 重装 / 串口字段27）永远是同一拍、同一个事件。

    localparam integer SFX_NUM    = 5;            // ★★★ 2026-10-25【用户要求·编号一一对应】卡上 5 个 .WAV ⇒ 图 k 配第 k 首（SEL_AUD_W 自动变 3 位：0..4）。
                                                  //     ★ 必须与卡上实际 .WAV 条数一致：设大了会拨到空位 ⇒ find_bmp 失败 ⇒ a_fail ⇒ 音频链停住（需 KEY4 恢复）；
                                                  //       设小了则最后一张图的配乐回不到第 5 首。卡上还必须有 5 张 .BMP（IMG_N=5），一一对应才成立。
                                                  //     ★ 改了这里，top_aud 的 .SFX_NUM 是同一个宏（见下面例化），不用改两处。
                                                  // 音效条数（★ 2026-10-15 起由 4 条改为 5 条；更早的 2/3 条历史注释已删）

    // ---- ★ D5b【报警音】提前声明：`a_sd_skip` 在下面几百行之前就要用它 ----

    //   Verilog 只认**声明位置**，所以 alert_on / ALARM_SKIP 必须放在 `a_sd_skip` 之前；

    //   驱动它的 always 块仍在下面（报警状态机那块），顺序不影响。

    localparam [3:0] ALARM_SKIP = 4'd4;   // 卡上第 5 个 .WAV（skip=4）= 警报声

    reg        alert_on;

    reg [28:0] alert_hold_cnt;



    localparam integer SEL_AUD_W  = (SFX_NUM <= 2) ? 1 : (SFX_NUM <= 4 ? 2 : 3);

                                                  // 选择寄存器位宽（2 条 ⇒ 1 位；1 位 = 1 个 FF，最省）

    reg  [SEL_AUD_W-1:0] sel_aud;                 // ★ 当前选中的是第几条音频（0 = 卡上第 1 个 .WAV）

    // ---- 音频那一路的 skip = 选中的第几个 .WAV（0 = 卡上第 1 个，在自己的扩展名里数）----

    //   ★ 只改音频这一路：字幕仍走 SUB_SKIP（`sd_mode==2` 那一档，一个字没动）、

    //     装图仍走 `a_skip`（`sd_mode==0` 那一档，由控制桩/key3 管，也一个字没动）。

    //   ★ `find_bmp` 在 start 那一拍锁存 skip（`a_image\find_bmp.v` 第 175 行 `skip_r <= skip;`）

    //     ⇒ 就算 sel_aud 在别处变了，也绝不会把"正在跑的这一趟"带偏。

    // ★ 2026-10-17【修 lint · 消除 HDL-5373】_skip 原来声明在第 620 行，而下面这句就用它 ⇒ 挪上来。

    // ★ 2026-10-17【修 lint · 消除 HDL-5373】`a_skip` 原来声明在下面几百行处，

    //   而下一句 `a_sd_skip` 就用它 ⇒ **声明挪到所有使用之前**。`a_skip` 是 4 位网线，

    //   隐式声明只会有 1 位 ⇒ 属于"能编译但语义靠工具兜底"的隐患。

    wire [3:0]  a_skip;

    reg  [3:0]  sub_skip_lat;

    // ★ D5b：卡上有没有第 5 个 WAV。装失败自动置 0 ⇒ 只丢报警音，不丢 BGM

    reg  alarm_audio_ok;

    // ★★★ 2026-10-24【一图一乐】u_ctrl 给出的"本次请求那张图的序号"（与 req_accept_w 同拍）

    wire [3:0] req_skip_w;

    // 图 k ⇒ 第 k 首音乐（2026-10-25【编号一一对应】去掉原来的 mod：5 张图配 5 首，不再出现"第 4 张图放第 1 首"）

    wire [SEL_AUD_W-1:0] req_aud_mod = req_skip_w[SEL_AUD_W-1:0];



    wire [3:0]  a_sd_skip  = (img_load_pulse || img_hold || alert_on) ? 4'd0 :

                             sub_load_pulse ? sub_skip_lat :     // ★ 一图一字幕：跟图序号走

                             // ★ D5b：报警时音频那一路固定装第 5 条（ALARM_SKIP=4）

                             (a_sd_mode == 2'd1 ? (alert_on ? 4'd0

                                                            : {{4-SEL_AUD_W{1'b0}}, sel_aud})

                                                : a_skip);



    // 行缓冲探针（第一次填充的请求地址/字数 + 收到的头两个字）

    wire [20:0] lb_wbase0;

    wire [11:0] lb_words0;

    wire [31:0] lb_rd0, lb_rd1;



    // ============================================================

    //  0. 两个 PLL

    // ============================================================

    wire clk_pix, clk_par, clk_ser, pll0_locked;

    PLL_0 u_pll0 (

        .refclk  (clk),

        .reset   (~rst_n),

        .extlock (pll0_locked),

        .clk0_out(clk_pix),        // 40 MHz  像素

        .clk1_out(clk_par),        // 100 MHz @90 并行（串化）

        .clk2_out(clk_ser)         // 200 MHz 串化

    );



    wire clk_sdr, clk_sdr180, pll_sdr_locked, clk_sdr_unused;

    PLL_SDR u_pll_sdr (

        .refclk  (clk),

        .reset   (~rst_n),

        .extlock (pll_sdr_locked),

        .clk0_out(clk_sdr_unused), // 100 MHz（用不到）

        .clk1_out(clk_sdr),        // 125 MHz          → SDRAM Clk

        .clk2_out(clk_sdr180)      // 125 MHz @180°    → SDRAM Clk_sft

    );



    // ============================================================

    //  0a-2. ★★ 2026-10-05：音频 PLL（A 轨的音频链要 12.288 MHz）

    //    用原厂例程里现成的 `PLL_HDMI_AUDIO`：C0=75M / C1=375M / C2=12.295082M。

    //    · C2 比 12.288 高 +576 ppm —— 音调高 0.058%，人耳听不出来；

    //    · C0/C1 我们用不到，不接（TD 会把没用的时钟输出摘掉）；

    //    · ★ 这颗片子有 4 个 PLL，现在用到第 3 个（离线综合能过，见资源报告）。

    // ============================================================

    PLL_HDMI_AUDIO u_pll_aud (

        .refclk  (clk),

        .reset   (~rst_n),

        .extlock (pll_aud_locked),

        .clk0_out (),

        .clk1_out (),

        .clk2_out (clk_aud)        // ★ 12.295 MHz 音频域

    );



    // ============================================================

    //  0c. ★★★ 2026-10-03：A 的推字只放行到"显示刚才没在读"的窗口

    //     （为什么这么做 / 上板踩过什么，见第 1b 节那段长注释；

    //       放这里是因为要用上面 PLL 出来的 clk_sdr）

    // ============================================================

`ifdef LOAD_WITH_READS

    // ★★ 2026-10-03 第四版（上板看到"旧图花 + 新图花、越切越多"之后加的）：

    //    第三版只保证"推字发生在显示没在读的窗口里"，**没保证写突发在窗口内跑完** ——

    //    A 可能在窗口的最后一刻推字，引擎的突发（几百字 ≈ 4 µs）就跨进显示

    //    下一次搬行的时刻 → 读写还是重叠 → 旧图（读侧）和新图（写侧）一起花。

    //

    //    修法：**只在窗口的"前段"放行推字**，把窗口的后段留给引擎把突发跑完：

    //       窗口 ≈ 20 µs（一行 26.4 µs 里显示只搬 ~6.4 µs）

    //       前段 ≈ 5 µs 放行（600 拍 @125MHz）→ 后段 ≈ 15 µs 足够跑完 4 µs 的突发

    //   ★ 吞吐不受影响：SD 约 380k 字/秒 → 一行只送来 ~10 个字，

    //     而前段允许 600 个字/行，富余得离谱。

    reg  [11:0] rd_idle_cnt;                     // 显存域：连续多少拍没有读请求

    always @(posedge clk_sdr or negedge rst_n) begin

        if (!rst_n)                       rd_idle_cnt <= 12'd0;

        else if (disp_rd_en)              rd_idle_cnt <= 12'd0;

        else if (rd_idle_cnt != 12'hFFF)  rd_idle_cnt <= rd_idle_cnt + 12'd1;

    end

    // ★★ 2026-10-04 第五版：**推字门控整个去掉**。

    //    第四版把推字限制在窗口前段，结果上板"毫无变化"—— 而串口里

    //    字段 0/1（引擎实写字数 W）和字段 11（A 自己推的字数）对不上账

    //    （低 16 位差约 10,240 个字）⇒ **引擎少写/写错了字**，

    //    正是《B轨待改清单》§一 记过的那一族：**引擎的突发/收尾记账依赖

    //    A 的推字节奏**，人工把推字切成一顿一顿，它的账就错。

    //    ⇒ 结论：**A 的推字一个字都不能门控**（它必须保持原来的连续节奏）。

    //      于是这一档只剩"读口在写突发期间让路"（第一版那套握手）。

    //    判据（每次都能从串口直接看）：字段 0/1 的低 16 位 必须等于 字段 11。

    // ★★★ v7 第一步（2026-10-04，用户方案）：**A 的推字只放行到行场消隐期**。

    //   为什么这条能行而前面 5 版都不行：消隐期显示**根本不读** SDRAM

    //   （没有行请求）⇒ 读写天然分开，既不撞、也不饿显示。

    //   ★ 代价：A 的写口一帧要停 ~16 ms（消隐只占 0.74 ms）⇒ 装载变慢

    //     （1152x864 那张约 14 s）。所以下一步必须做**预取**：

    //     空闲时就把下一张装进后台槽，那 14 s 花在"你正在看图"的时候。

    //   ★ 另一个前提：A 的 sd_read.TIME_OUT 原来只有 2 ms，会把这种长停当超时

    //     （v2 白屏的老根）—— 已同时放大到 40 ms。

    reg pw1, pw2;

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin pw1 <= 1'b0; pw2 <= 1'b0; end

        else        begin pw1 <= vs_w;  pw2 <= pw1; end   // vs 高 = 消隐

    end

    wire push_ok_m   = pw2;                       // 1 = 消隐期，允许 A 推字

    // ★★★ v7 第三步（2026-10-05，用户提醒"读写都要凑 4 的倍数"）：

    //   上板：白线没了 ✓ 但出现**条状花屏且越切越多** ✗。

    //   根因：这颗核"4 字一包"，**每一串突发的起始绝对地址必须是 4 的倍数**。

    //   我上一版把推字按帧切断 ⇒ 引擎的串在中途"断粮" ⇒ 下一串从一个**不是 4

    //   倍数**的地址开始 ⇒ 每 4 个字转一位 ⇒ 条状；断一次多一层 ⇒ 越切越多；

    //   大图断得最多 ⇒ 它下面那段常驻条状。

    //   修法：**每个消隐窗口一次放行整数个 4 字**（这里 512 = 2 个整串），

    //   窗口内放完就关闸、等下一个消隐窗口，**中途绝不切** ⇒ 断粮点永远是 4 的倍数。

    //   ★ 代价：一帧最多 512 字 ⇒ 约 30.7k 字/秒（240k 字约 8 s、497.6k 字约 16 s）。

    //     用户明确说"速度不重要，不花屏优先"，所以就这样；慢的部分交给预取去藏。

    localparam integer PUSH_CHUNK = 512;          // 每个消隐窗口最多放行多少个字（4 的倍数！）

    reg  [9:0] push_cnt_w;

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n)                  push_cnt_w <= 10'd0;

        else if (!push_ok_m)         push_cnt_w <= 10'd0;          // 关闸就清零

        else if (a_wr_we && !a_wr_full) push_cnt_w <= push_cnt_w + 10'd1;  // 真放行一个字才 +1

    end

    wire push_allow  = push_ok_m && (push_cnt_w < PUSH_CHUNK[9:0]);



    wire a_wr_full_g = a_wr_full | ~push_allow;  // ★ A 看到的"满"（窗口外/放满 512 字都报满）

`else

    // ★ 实验关掉时：**完全不动 A 的推字**（回到这次实验之前的行为）

    wire a_wr_full_g = a_wr_full;

`endif



    // ============================================================

    //  0b. 按键旋钮（2026-09-27，测试用）

    //      key1：每按一次"取数组内相位" +1（0→1→2→3→0），默认 3

    //           ★ 实测：这颗核每 4 拍才更新一次读数据（前 3 拍重复旧值），

    //             而"数据有效"脉冲每拍都发。所以这边把地址每 4 拍才推进 1 个字，

    //             并且每 4 个有效脉冲只取 1 个 —— 取哪一拍由这个相位决定，

    //             现场试到"逐字校验 = 0"为止。

    //      ★ 自测图模式下 key1 原本是"让 A 去装真图"，但这一版要一边看图、

    //        一边现场调补偿，所以把 key1 从控制桩那里摘开（桩拿到常 1 = 空闲），

    //        免得按一下就悄悄把自测地址图覆盖掉。

    //      key2 仍然照旧（控制桩里的软复位）。

    // ============================================================

    reg [2:0] zoom_lv;      // 缩放档（0=适配 1=1x 2=1.5x 3=2x 4=3x 5=4x）

    reg [3:0] vol_lv;       // ★ 2026-10-21【百分比】音量档 0..10（10 = 100% = 原来写死的 8'hFF）

    reg [3:0] bri_lv;       // ★ 2026-10-21【百分比】亮度档 0..10（10 = 100% = 原样，0 = 全黑）

    // ★ 2026-10-21【百分比音量】0..10 档 ⇒ 8 位音量字节：lv*255/10 = (lv*51)>>1，10 档正好 255

    // ★★★ 2026-10-24【修复】原来写成 8'd51 的 8 位乘法：Verilog 里 `*` 的结果宽度 = 操作数最大宽度，
    //   8 位会截断 ⇒ lv6..lv10 的 lv*51 回绕成 50,101,152,203,254（再 >>1），实测 60%=12.5%、
    //   50%=50%、100%=50% —— 这就是"50% 反而比 60% 响、最大只有 50%"的根因。改成 16 位中间结果。

    wire [15:0] vol_mult = ({8'd0, vol_lv} * 16'd51);   // 0..510，16 位不会溢出

    wire [7:0]  vol_byte = vol_mult[8:1];               // = (lv*51)>>1，lv10 = 255

    reg [3:0] key_cnt;      // KEY2（菜单"确定"）按了几次 —— 串口字段 18

    // ★★★ 2026-10-17【缩放改到菜单里】

    //   原来这里有一个 KEY2 的消抖实例 `u_k1` + 一段"每按一次 KEY2 就循环 zoom_lv"的

    //   always。现在缩放**只能在菜单里改**（菜单打开 + 光标在 ZOOM 行 + 按 KEY2），

    //   所以那一半整段删除，新的驱动逻辑放在下面菜单块之后（那里才用得到 menu_on/menu_sel）。

    //   ★ 同一根引脚 `key1` 上原来有**两个**消抖实例（`u_k1` 吃引脚复位、`u_k1_ok` 吃

    //     sys_rst_n）—— 现在只保留 `u_k1_ok`（菜单那条）⇒ 顺手省掉一个消抖器。

    //   ★ zoom_lv 仍用**引脚复位** rst_n：软复位（KEY4）重来后缩放档保留。



    // 档位同步到像素域（只按 KEY1 时才变，慢变；两位同步器够用，

    // 跨域瞬间最多错一帧，肉眼看不出来）

    reg [2:0] zoom_p1, zoom_p2;

    always @(posedge clk_pix or negedge rst_n) begin

        if (!rst_n) begin zoom_p1 <= 3'd0; zoom_p2 <= 3'd0; end

        else        begin zoom_p1 <= zoom_lv; zoom_p2 <= zoom_p1; end

    end



    // ============================================================

    //  1. 控制（桩：假装是 C）

    //     ★ 它只吃【引脚复位】—— 因为软复位是它自己产生的

    //       （它内部再自己门控出 ctl_rst_n，见 stub_ctrl.v 文件头）

    // ============================================================

    wire        a_start, soft_rst;

        wire [2:0]  a_use_slot;

    wire [20:0] a_slot_base;

    wire [7:0]  a_img_no;

    wire        a_busy, a_load_done, a_desc_done, a_fail, a_sd_ready;
    wire [5:0]  a_fail_src;      // fail 来源      // ★ 2026-10-23 诊断：fail 的六个来源（声明必须在 top_a 例化之前）
    wire [23:0] a_sub_dbg;       // 诊断：{失因位, 前两字节}

    wire [7:0]  a_ready_n;



    // ============================================================

    //  全设计的复位 —— ★★ 2026-09-27 按官方例程的做法改（关键修复）

    //

    //  官方 top_tf_hdmi_audio.v 里的写法（原文注释）：

    //      "end else if (sys_pll_lock && video_pll_lock) begin

    //          // 等待 PLL 连续稳定 20ms @ 50MHz

    //          if (rst_cnt < 20'd1_000_000) ... rst_all_reg <= 1'b1;"

    //      "// 一旦复位释放，忽略后续微小的 PLL 抖动，防止系统在使用时随机复位"

    //

    //  我们原来是 `rst_n & pll0_locked & pll_sdr_locked & ~soft_rst`：

    //    ① PLL 一报锁定就立刻放行 —— 而锁定信号常常比输出时钟真正稳定早

    //       → SDRAM 的初始化（预充电/刷新/写模式寄存器）可能在时钟还在抖的时候跑

    //       → 模式寄存器没写对，SDRAM 就长期停在错误模式

    //    ② 锁定状态没有锁存 —— PLL 后面轻微抖动会让整块设计中途复位，

    //       SDRAM 跟着重新初始化，而这时显示还在读它（厂商文档明写：

    //       "Sdr_init_done 拉高之前绝对不能读写"）

    //  这两条都会让 SDRAM 停在一个"看起来能用、其实节奏不对"的状态 ——

    //  正好对应我们测到的"每 4 拍才更新一次读数据"。

    // ============================================================

    localparam [25:0] PLL_WAIT_TICKS = PLL_WAIT_US * 50;   // 50MHz

    reg        pll_ok_reg;      // PLL 稳定确认过（之后不再理会抖动）

    reg [25:0] pll_wait;

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            pll_ok_reg <= 1'b0;

            pll_wait   <= 26'd0;

        end

        else if (!pll_ok_reg) begin

            if (pll0_locked && pll_sdr_locked) begin

                // 连续稳定 20 ms @50MHz = 1,000,000 拍；中间抖一下就重新计时

                if (pll_wait >= PLL_WAIT_TICKS) pll_ok_reg <= 1'b1;

                else                            pll_wait <= pll_wait + 26'd1;

            end

            else pll_wait <= 26'd0;

        end

    end



    // 全设计的复位：引脚复位 + PLL 稳定确认（已锁存）+ 软复位

    // ★★★ 2026-10-22【确认拔卡 ⇒ 整块软复位】
//   需求：sd_lost（连续两次读失败 ⇒ 认定卡被拔）一旦成立，直接做一次**整块软复位**，
//         让全设计（含 sd_init、菜单、状态机、字幕/音频装载锁存）从零开始，
//         而不是只复位 A 轨（那条路在实测里恢复要 4 s，用户不能接受）。
//   形式：16 ms **脉冲**（不是挂起到空闲的 FSM —— 那种写法 2026-10-21 v3 实测
//         被 TD 判成常数复位、把设计从 8,708 slices 削到 3,151，绝对不能用）。
//   怎么落：不自己另造复位 —— 把 `sd_lost` 的上升沿（单拍）送进 `stub_ctrl`，
//         和 KEY4 共用同一个 `soft_rst` 发生器（`stub_ctrl.v` 里那台，
//         `ctl_rst_n = rst_n & ~soft_rst`，菜单/串口状态/装载锁存全都吃它）。
//         ★ 用"单拍上升沿"而不是电平：`sd_lost` 是电平，缓复位结束后它还在，
//           直接送进去会一直重触发软复位，板子就再也起不来了。
reg         sd_lost;        // 1 = 认定卡已拔走（声明提前，供 `sd_lost_rise` 使用）
reg         sd_lost_d;
wire        sd_lost_rise = sd_lost & ~sd_lost_d;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) sd_lost_d <= 1'b0;
    else        sd_lost_d <= sd_lost;
end

wire sys_rst_n = rst_n & pll_ok_reg & ~soft_rst;

    // ★ 2026-10-23【一图一字幕】字幕 skip 不再跟“缓冲槽号”，改成跟“当前这张图的序号”：
    //   装图完成的那一刻把 a_skip 锁存下来，字幕那趟读就用它 ⇒ 第 k 张图配第 k 条 .SUB。
    //   （报警时图/字幕都用 skip 0，即 EMG.BMP 配 EMG.SUB，不受影响）
    reg         img_done_d;
    wire        img_done_rise = a_load_done & ~img_done_d;

    // ★ 2026-10-24【字幕先就位】把送给 stub_ctrl 的 a_load_done 延 300 ms：
    //   字幕 FSM 用快的那一份立即开始装（0.14 s），而 commit+转场推后 300 ms，
    //   两者落在同一帧附近上屏。
    reg  [23:0] ldly_cnt;
    reg         a_load_done_dly;
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            ldly_cnt <= 24'd0; a_load_done_dly <= 1'b0;
        end else if (a_load_done) begin
            ldly_cnt <= 24'd1;            // ★ 2026-10-24：遍迟 300 ms 取消（它是字幕“慢几拍”的一半成因）
            a_load_done_dly <= 1'b0;
        end else if (ldly_cnt != 24'd0) begin
            ldly_cnt <= ldly_cnt - 24'd1;
            a_load_done_dly <= (ldly_cnt == 24'd1);
        end else begin
            a_load_done_dly <= 1'b0;
        end
    end

    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            img_done_d   <= 1'b0;
            sub_skip_lat <= 4'd0;
        end else begin
            img_done_d <= a_load_done;
            if (img_done_rise) sub_skip_lat <= a_skip;
        end
    end

    // ============================================================

    //  ★★★ 2026-10-21【D3 · C1】SD 卡"拔掉再插回"自动恢复

    // ------------------------------------------------------------

    //  故障：卡没插（或接触不良）时 `sd_init` 过不去 ⇒ `a_sd_ready=0` ⇒ 兜底页停在

    //        NO_CARD。把卡插回去**什么也不会发生**，必须人按 KEY4 —— 商显挂在墙上，

    //        没人去按。这是"第一高发故障"。

    //  做法：只在 **A 轨空闲**（`~a_busy`）且 **卡没就绪**（`~a_sd_ready`）时，每

    //        `SD_RETRY_MS` 给 A 轨一个局部复位脉冲，让 `sd_init` 重跑一遍。

    //  三条边界（都是从"会出事"的那一侧反推出来的）：

    //    ① **只复位 A 轨**（`a_rst_n`），显示链/HDMI/PLL 一律不动 ⇒ 屏幕不闪、

    //       显示器不重新同步，SDRAM 里的旧画面继续显示（现场观感 = 后台在重试）；

    //    ② **只在 `a_busy=0` 时动手**：装载中途把写突发切断，可能让 sdr 仲裁器

    //       停在半路（这是 10-08 那次"白线 + 沙沙声"的同类风险），所以从根上避开；

    //    ③ **卡一就绪就停**：`a_sd_ready=1` ⇒ 计数器清零、不再复位。

    //  ★ 和 KEY4 的关系：KEY4 走 `soft_rst`（全设计复位），这条只动 A 轨，两者不冲突。

    // ============================================================

    localparam integer SD_RETRY_MS    = 500;

    localparam [24:0]  SD_RETRY_TICKS = SD_RETRY_MS * 50_003;   // 50 MHz ⇒ 25,000,000



    reg  [24:0] sd_retry_cnt;

    reg         a_recover;       // 1 = 正在给 A 轨复位
    reg         alert_q;         // ★ 2026-10-21：报警电平的上一拍（做边沿）
    reg         a_alert_rst;     // ★ 报警/解除各给一拍：整块复位 A 轨（清 SDRAM 写状态 + SD 读状态机）

    reg  [3:0]  a_recover_dly;   // 复位脉宽（8 拍 ≫ 同步器需要的 2 拍）



    // ★ 看门狗的输出：声明放这儿，真正的 always 块在后面（要等 _dbg_* 声明之后）

    reg         a_stall;         // ← 由后面 C1b 看门狗驱动（声明必须在这里，FSM 要用）

    // ★★★ 2026-10-21【D3 · C1e】"卡就绪"的有效版本。

    //   上板实测：**先插卡上电、再拔卡** ⇒ `bus_owner` 一直是 1、`a_sd_ready` 一直是 1，

    //   于是"没卡就重试"这套判据永远不触发（用户看到的是"拔了没反应"）；

    //   插回去时读口对着一个刚上电的卡发 CMD17 ⇒ 读回全 0xFF ⇒ 白图。

    //   做法：用"连续读失败"当拔卡证据（`sd_lost`），把它与 `a_sd_ready` 相与，

    //   从而复用**已经验证过**的 500 ms 重试通道（复位 A 轨 ⇒ 重新 sd_init）。

    //   ★ 为什么用"连续两次失败"而不是一次：一次失败可能只是某个素材坏，

    //     真拔卡时轮播每 3 s 一次，两次也在 3~6 s 内到齐，够快。

    wire        sd_ready_eff;

    wire sd_need_retry = ~sd_ready_eff & ~a_busy & pll_ok_reg & rst_n;



    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            sd_retry_cnt  <= 25'd0;

            a_recover     <= 1'b0;

            a_recover_dly <= 4'd0;

        end

        else begin

            // ① "没卡"计数器：只在 A 轨空闲且卡未就绪时累加

            if (sd_need_retry) sd_retry_cnt <= sd_retry_cnt + 25'd1;

            else               sd_retry_cnt <= 25'd0;



            // ② 复位请求：到点重试 **或** 看门狗判定吊死（C1b）

            if (a_stall || a_alert_rst || (sd_need_retry && (sd_retry_cnt >= SD_RETRY_TICKS))) begin

                a_recover     <= 1'b1;

                a_recover_dly <= 4'd8;

                sd_retry_cnt  <= 25'd0;      // 后写优先：请求那拍把计数器一起清掉

            end

            else if (a_recover_dly != 4'd0) begin

                a_recover_dly <= a_recover_dly - 4'd1;

                a_recover     <= 1'b1;

            end

            else a_recover <= 1'b0;

        end

    end



    // ★ 2026-10-22 第三版（用户反馈：「拨回后 1 秒才开始复位」）：
    //   改成**直接跟开关引脚**的双沿，不再跟 alert_on。
    //   为什么：alert_on 在接点断开后还要保持 ALERT_HOLD_MS=10 s 才清零（报警保持逻辑，
    //   防止干接点瞬断就退出报警），跟它走必然慢，而且慢多少取决于保持计数器走到哪。
    //   现在：拨码引脚 → 两级同步 → 150 ms 去抖 → 双沿 ⇒ 拨过去/拨回来都在 ~150 ms 内
    //   触发同一条整块软复位（与 KEY4/拔卡共用 stub_ctrl 的 soft_rst）。
    //   仍然保留 0.3 s 武装窗口（arm_cnt）：0.3 s 远大于复位后开关注入的任何毛刺宽度，
    //   环堵不住时就只会表现为"少复位一次"，不会变成连续重启。
    reg [1:0]  sw4_s;                 // 两级同步（rst_n 域，软复位不清）
    reg [22:0] sw4_stb;               // 稳定计数：7,500,000 拍 = 150 ms @ 50 MHz
    reg        sw4_v;                 // 去抖后的开关电平

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sw4_s   <= 2'b00;
            sw4_stb <= 23'd0;
            sw4_v   <= 1'b0;
        end
        else begin
            sw4_s <= {sw4_s[0], sw4};
            if (sw4_s[1] != sw4_v) begin
                if (sw4_stb >= 23'd7_500_000) begin
                    sw4_v   <= sw4_s[1];
                    sw4_stb <= 23'd0;
                end
                else sw4_stb <= sw4_stb + 23'd1;
            end
            else sw4_stb <= 23'd0;
        end
    end

    reg sw4_vq;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) sw4_vq <= 1'b0;
        else        sw4_vq <= sw4_v;
    end

    reg [27:0] arm_cnt;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)                          arm_cnt <= 28'd0;
        else if (soft_rst)                   arm_cnt <= 28'd0;
        else if (arm_cnt != 28'd15_000_000)  arm_cnt <= arm_cnt + 28'd1;
    end

    wire alert_arm       = (arm_cnt == 28'd15_000_000);           // 0.3 s @ 50 MHz
    wire alert_rst_pulse = alert_arm & (sw4_v ^ sw4_vq);          // ★ 双沿：拨过去 / 拨回来都复位

    //   为什么整块复位：报警集与广告集是两套素材，装载途中切会让写突发/读状态机/find 引擎都停在半路，
    //   复位一次最干净，代价约 0.5 s（SD 重新初始化）。
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            alert_q     <= 1'b0;
            a_alert_rst <= 1'b0;
        end
        else begin
            alert_q     <= alert_on;
            a_alert_rst <= alert_on ^ alert_q;
        end
    end

    // A 轨专用复位：全设计复位 + 本模块的自动重试脉冲

    wire a_rst_n = sys_rst_n & ~a_recover;





    // ============================================================

    //  ★★★ 2026-10-14 深夜【开关3 切音频】—— SW3（拨码/乒乓开关）消抖，双边沿

    // ------------------------------------------------------------

    //  板上"开关3"= 丝印 SW3 = FPGA 引脚 **C6**。三处来源（都查过，互为印证）：

    //    · 《HX4S20 开发板手册》p.18 图 2-19：SW1=C8 / SW2=C7 / **SW3=C6** / SW4=C5；

    //    · 原理图网名 `NLSWKEY03` = **C6**；

    //    · 官方 DEMO 约束里 `key[2]`（`SW[2]`）= **C6**，且都写 `PULLTYPE = PULLUP`。

    //  ★ 极性：拨上=1 / 拨下=0，但**两份官方文档互相矛盾** ⇒ 这里不猜方向：

    //    用本工程新写的 `lib\util\sw_edge_debounce.v`（稳定后**任意方向**变化给一拍脉冲）。

    //    ★ 为什么不用 `key_press_debounce`：它只认 1→0（按下）那一半 ——

    //      拨码开关两个方向都是有效操作，用它就只能识别一个方向；

    //      而且它的复位初值是"不按=1"，对拨码开关不成立（上电会白多发一拍）。

    //      详见 `lib\util\sw_edge_debounce.v` 文件头。

    //  ★ 顶层端口 ↔ 板上丝印（照《HX4S20 开发板手册》）：KEY1=A2  KEY2=B2  KEY3=B1  KEY4=C1，

    //    其中 **A2 已经被硬复位 `rst_n` 占用** ⇒ 本工程端口 `key1/key2/key3`

    //    实际是板上 **KEY2(B2) / KEY4(C1) / KEY3(B1)**（见上面端口表 + 下面 u_ctrl 的接法）。

    //  ★ 这一路**只**做"选第几条音频"，和 KEY3 换图彻底解耦（KEY3 从此只换图）。

    //  ★ 必须放在 `wire sys_rst_n = ...` **之后**（本文件反复踩过"先用后声明"）。

    // ============================================================

    wire sw3_change;                // 消抖后"任意方向变化"的单拍脉冲（50 MHz 域）

    reg  sw3_pend;                  // ★ 加速连拨：变化已发生、但音频状态机还没受理（当时在装载）

    reg  alert_pend;                // ★ D5b：报警边沿在装载途中发生时先挂起（和 sw3_pend 同一语义）

    sw_edge_debounce #(.CLK_FREQ_HZ(50_000_000), .DEBOUNCE_MS(20)) u_sw3 (

        .clk(clk), .rst(~sys_rst_n), .sw_in(sw3), .change_pulse(sw3_change)

    );



    // ============================================================

    //  ★★★ 2026-10-15【参数菜单·第1步】交互骨架 —— 全部在 **50 MHz 控制域**，慢变

    // ------------------------------------------------------------

    //  ★★★ 2026-10-15【参数菜单·操作方式修订】用户改稿：**SW1 是两档拨动开关，

    //      不能当"按上 / 按下"用** ⇒ 操作方式改成：

    //        · **SW1 = 方向状态位（电平）**：同步后 `menu_dir = sw1`（1 = 上 / 0 = 下）；

    //          原来那段"SW1 方向变化脉冲驱动光标"的逻辑**已整段删除**（`u_sw1` 实例一起删）。

    //        · **KEY3（B1）= 步进按钮**：`menu_on == 1` 时每按一次 ⇒ `menu_sel` 按 `menu_dir`

    //          ±1（4 项，两端回绕）；**菜单关着时 KEY3 仍是老功能：换下一张图**。

    //        · **菜单打开时屏蔽 KEY3 的"换图"作用**：喂给 `stub_ctrl` 的那根按键输入

    //          改成 `key3 | menu_on`（按键**低有效** ⇒ 该表达式 = 1 表示"没按"）：

    //          `menu_on = 1` 时它恒为 1 ⇒ `stub_ctrl` 里的消抖器永远看不到"按下" ⇒ 不换图。

    //          ★ **只动这一处输入**（见下面 `u_ctrl` 那段），`stub_ctrl` 内部**一个字没改**；

    //            `menu_on = 0` 时该门**原样透传** `key3` ⇒ **菜单关闭时行为逐位不变**。

    // ------------------------------------------------------------

    //  控件映射（**用户 2026-10-15 定稿 + 同日操作方式修订**，照这一张表做，不要自行发挥）：

    //    · **SW2（引脚 C7）**   ：每拨动一次 ⇒ 菜单开关 `menu_on` **翻转**

    //                             （只认"变化"，不判方向 ⇒ 手册把方向写反也不影响）

    //    · **SW1（引脚 C8）**   ：菜单的**方向状态位**（**电平，不是脉冲**）——

    //                             两档拨动开关没有"按一下"这个语义，所以**只读电平**：

    //                             两级同步后 `menu_dir = MENU_UP_ON_1 ? sw1_lvl2 : ~sw1_lvl2`

    //                             （1 = 上 / 0 = 下）。它**自己不再改变光标**，只决定

    //                             下一次按 KEY3 往哪边走 ⇒ 上板先拨 SW1、再按 KEY3。

    //                             ★ 方向极性仍然是**一行 localparam**（`MENU_UP_ON_1`），

    //                               上板若发现上下反了，改那一个 bit 即可。

    //    · **KEY3（引脚 B1）**  ：**菜单打开时 = 步进按钮**（每按一次 ±1、4 项回绕）；

    //                             ★★★ 2026-10-17【用户改稿·已上板】菜单**关闭**时 =

    //                             **自动轮播的开/关翻转**（不再是"装载/换下一张"，那个

    //                             功能已交给 KEY2）。开着就每 ~3 s 自动换一张。

    //                             ★ 消抖用的是**本块自己新加的**官方 `key_press_debounce`

    //                               实例 `u_k3_menu`（和 `stub_ctrl` 里那个同款、同参数）——

    //                               用户明确要求本步**不牵扯 `stub_ctrl` 内部**，所以宁可

    //                               多一个实例，也不去复用它内部的 `k1_press`。

    //    · **KEY2（引脚 B2，本工程端口 `key1`）**：两个身份 ⇒

    //                             ① 菜单**打开**时 = "确认"键（进/出调节态，

    //                                见下面 `menu_edit`，行 0 = ZOOM、行 2 = VOLUME）；

    //                             ② 菜单**关闭**时 = **换下一张图**（走 `stub_ctrl` 的

    //                                `key1` 口，被 `key1 | menu_on` 门控）。

    //        ★ 2026-10-17 修正：这里原来写"本步仍不接参数、`key1_ok_press` 悬空"，

    //          早就不是了 —— `key1_ok_press` 现在驱动 `menu_edit`（确认）和 `key_cnt`。

    //    · **KEY4（引脚 C1，端口 `key2`）**：**一字不动**（照旧软复位）。

    //                             ★ 本步**不做任何复位门控**（用户明确要求）——

    //                               `sys_rst_n` 那一行不碰、`stub_ctrl` 内部不碰。

    //    · **SW3（引脚 C6）**   ：**一字不动**（照旧"切 4 条音频"）。

    //                             ★ 所以本菜单块**不消费** `sw3_change`。

    //    · **SW4（引脚 C5）**   ：**一字不动**（照旧"字幕水平滚动"）。

    // ------------------------------------------------------------

    //  ★ 菜单状态：★ 2026-10-18 起菜单 **5 项**（ZOOM / AUDIO / VOLUME / BRIGHT / VISUAL）

    //    ⇒ `menu_sel` 3 位（`MENU_W=3`），`menu_ovl.ROW_N` 必须同为 5。

    //  ★ 菜单关闭（`menu_on = 0`）时既有行为**逐位不变**，逐条论证：

    //      · `menu_on` 被复位成 0、且只有拨 SW2 才翻转 ⇒ 上电行为与改前逐拍一致；

    //      · 本块进入既有逻辑的东西只有两处，且**在 `menu_on = 0` 时都退化成原式**：

    //        ① `stub_ctrl` 的按键输入 `key3 | menu_on` ⇒ `menu_on = 0` 时**恒等于 `key3`**

    //           （按位或常量 0，综合后就是原来那根线）⇒ 换图 / 预装判据逐位不变；

    //        ② 送给 `disp_top` 的 `menu_on_s2/menu_sel_s2` ⇒ 菜单关闭时菜单层被常数

    //           传播消掉（见 disp_top / menu_ovl 的注释）；

    //      · 其余全部只**读**既有信号（`sw2` / `sw1` / `key3` / `key1`），表达式一个没改；

    //        `key1_ok_press` 本步悬空；`u_k3_menu` 的输出只进本块的 `menu_sel`；

    //      · **KEY4 → `soft_rst` → `sys_rst_n`**、**SW3 → 音频状态机**、**SW4 → 字幕滚动**

    //        这三条路**一个字符都没碰**。

    //  ★ 为什么 SW1 现在**不需要** `sw_edge_debounce`：它已经是"状态位"语义（拨到哪边就是哪边），

    //     抖动的后果最多是"某次按键时方向读错一次"；而 `sw1_lvl2` 是**两级同步后的慢变电平**，

    //     在人手/人眼的时间尺度（≫ 20 ms）下不构成问题 ⇒ 原来那个消抖实例 `u_sw1` 已删除。

    //  ★ 为什么 KEY3 的**新消抖实例** `u_k3_menu` 用 `~sys_rst_n` 复位（和 `u_sw2` 一致）：

    //     和 `stub_ctrl` 内部那个（吃引脚 `rst_n`）不同 —— 这里跟软复位一起清：软复位后

    //     菜单本来就该回到干净状态，且这样不会在软复位瞬间漏出一个假脉冲。

    // ============================================================

    localparam integer MENU_N = 4;                  // 菜单项数（★ 2026-10-20【D1·A2】：5→4，删掉行 4 VISUAL）★ menu_ovl 的 ROW_N 必须一样

    localparam integer MENU_W = 3;                  // 光标位宽（5 项 ⇒ 3 位）；改条数时这里也要改

    // ★★★ 2026-10-15【参数菜单·操作方式修订】光标方向极性 —— **整个设计只此一行**

    //   = 1：SW1 电平为 1 ⇒ `menu_dir = 1`（下一次按 KEY3 光标 **+1**，往上走）

    //   = 0：SW1 电平为 1 ⇒ `menu_dir = 0`（下一次按 KEY3 光标 **−1**，往下走）

    //   ★ 上板若发现"上下反了"，只改这一个 bit（不要动别处）。

    localparam MENU_UP_ON_1 = 1'b0;



    wire       sw2_change;                          // SW2：消抖后"任意方向变化"的单拍脉冲

    reg        sw1_lvl1, sw1_lvl2;                  // ★ SW1 **电平**在控制域的同步副本（两级）

    wire       menu_dir;                            // ★ 方向状态位：1 = 上 / 0 = 下（只读电平）

    wire       key3_step_press;                     // ★ KEY3(B1)：菜单"步进"单拍脉冲（本块新实例）

    reg        menu_on;                             // ★ 菜单开关（0 = 关，上电即 0）

    reg        menu_edit;                           // ★ 调节态：1 = 正在调 ZOOM 值（KEY2 进/出，SW1/KEY3 步进）

    reg  [MENU_W-1:0] menu_sel;                     // 光标（0..MENU_N-1）

    wire       key1_ok_press;                       // KEY2(B2)/端口 key1：菜单"确定"脉冲（本步仍悬空）





    // ---- SW2（C7）：消除抖动（20 ms）⇒ 每次拨动给一拍 ⇒ 翻转菜单开关 ----

    sw_edge_debounce #(.CLK_FREQ_HZ(50_000_000), .DEBOUNCE_MS(20)) u_sw2 (

        .clk(clk), .rst(~sys_rst_n), .sw_in(sw2), .change_pulse(sw2_change)

    );



    // ---- ★【操作方式修订】SW1（C8）**不再实例化消抖器** ----

    //   它现在是**方向状态位（电平）**：上面那个 `always` 里的两级同步

    //   （`sw1_lvl1/sw1_lvl2`）+ 一行 `assign menu_dir` 就够了，

    //   不需要"变化出一拍脉冲"的 `sw_edge_debounce`（原来那个 `u_sw1` 已删除）。



    // ---- ★★★【操作方式修订】KEY3（B1）的官方消抖实例：菜单"步进"（专供菜单用）----

    //   ★ 和 `stub_ctrl` 内部那个（吃引脚 `rst_n`）**并行、互不影响** —— 用户要求本步

    //     不牵扯 `stub_ctrl` 内部，所以宁可多一个实例，也不去复用它内部的 `k1_press`。

    //   ★ 参数必须照 `stub_ctrl` 里 KEY3 的用法填（该模块默认 100 MHz，填错消抖时间差一倍）；

    //     `rst` 高有效、`button_in` 低有效（不按 = 1）。复位用 `~sys_rst_n`（理由见块首 ★）。

    //   ★ 它**只**产生 `key3_step_press`，消费者只有一个：下面那个 "菜单打开 + 步进" 分支。

    key_press_debounce #(.CLK_FREQ_HZ(50_000_000), .DEBOUNCE_MS(20)) u_k3_menu (

        .clk(clk), .rst(~sys_rst_n), .button_in(key3), .press_pulse(key3_step_press)

    );



    // ---- KEY2（B2，端口 key1）的官方消抖实例：菜单"确定"----

    //   ★ 参数必须照 `stub_ctrl` 里 KEY3 的用法填（该模块默认 100 MHz，

    //     填错消抖时间就差一倍）；`rst` 高有效、`button_in` 低有效（不按 = 1）。

    //   ★ 它**只**产生 `key1_ok_press`；本步没有任何消费者（面板不写字）。

    //   ★ `stub_ctrl` 里那个已有的 KEY4（= 端口 key2）实例**一个字都没动**。

    //     上面 0b 节那个 `u_k1`（key_press_debounce，`rst` 用 `~rst_n`）也一个字没动

    //     —— 那个是 KEY1/端口 key1 的"调试旋钮"通路，和本实例**并行**、互不影响。

    key_press_debounce #(.CLK_FREQ_HZ(50_000_000), .DEBOUNCE_MS(20)) u_k1_ok (

        .clk(clk), .rst(~sys_rst_n), .button_in(key1), .press_pulse(key1_ok_press)

    );



    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            sw1_lvl1 <= 1'b0;  sw1_lvl2 <= 1'b0;

            menu_on  <= 1'b0;                         // ★ 菜单默认**关**（上电与改前一致）

            menu_sel <= {MENU_W{1'b0}};

            menu_edit <= 1'b0;                        // ★ 调节态默认关

        end

        else begin

            // ---- ★【操作方式修订】SW1 只做**两级同步**：它是"方向状态位"，不是脉冲 ----

            sw1_lvl1 <= sw1;  sw1_lvl2 <= sw1_lvl1;

            // ---- SW2：每拨一次 ⇒ 菜单开/关翻转（消抖模块已滤抖动，不会因弹跳多翻）----

            if (sw2_change) menu_on <= ~menu_on;

            // ============================================================

            //  ★★★ 2026-10-17【菜单·调节态】用户改稿：

            //    · **KEY2 = 确认键**：光标停在 ZOOM 行时，按 KEY2 进入 / 退出**调节态**；

            //    · **调节态里 SW1 决定档位上下**：拨 SW1（消抖后的变化脉冲）⇒ `zoom_lv` ±1

            //      （拨到"上"那侧 = +1，另一侧 = −1，两端回绕 0↔5）；

            //    · 调节态里 KEY3 也按 SW1 方向步进（和光标同样的手感，两者都支持）；

            //    · **非调节态**时 KEY3 仍然是"按 SW1 方向移光标"。

            //    ★ 退出条件（三选一）：菜单关掉、光标被移走、或再按一次 KEY2。

            //    ★ 为什么用 SW1 的**变化脉冲**而不是电平：SW1 是两档拨动开关，

            //      "拨一下"就是一次操作；电平当操作会每拍 +1（不可能）。

            //      方向和脉冲对得上：消抖器要 20 ms 稳定才给脉冲，那时 `sw1_lvl2`

            //      早已是新电平 ⇒ 直接用 `menu_dir` 就是"拨过去之后"的方向。

            // ============================================================

            // ★★★ 2026-10-24【行 1 改成「可视」开关】：4 行全部可调

            //   （0 ZOOM / 1 VISUAL / 2 VOLUME / 3 BRIGHT）⇒ 只有"菜单关掉"才强制退出调节态。

            //   （原式在这里列出 0/2/3 三个可调行、把行 1（AUDIO）排除在外 —— 已随音轨行一起删。）

            if (!menu_on)

                menu_edit <= 1'b0;                    // 菜单关 ⇒ 自动退出调节

            else if (key1_ok_press)

                menu_edit <= ~menu_edit;              // KEY2 = 确认（进/出调节态）



            // ---- KEY3：调节态里不移动光标（让位给档位步进）----

            if (menu_on && !menu_edit && key3_step_press) begin

                if (menu_dir) begin

                    // 上移：3 ⇒ 0，否则 +1

                    if (menu_sel == (MENU_N - 1)) menu_sel <= {MENU_W{1'b0}};

                    else                          menu_sel <= menu_sel + 1'b1;

                end

                else begin

                    // 下移：0 ⇒ 3，否则 −1

                    if (menu_sel == {MENU_W{1'b0}}) menu_sel <= (MENU_N - 1);

                    else                            menu_sel <= menu_sel - 1'b1;

                end

            end

        end

    end



    // ★★★ 2026-10-15【参数菜单·操作方式修订】SW1 电平 ⇒ 方向状态位（极性**只此一行**）

    //   1 = 上 / 0 = 下；极性由上面那个 `MENU_UP_ON_1` 常量定（默认 0 ⇒ SW1 读 0 为"上"）。

    //   ★ 纯组合：只在按 KEY3 那一拍被采样；它本身不产生脉冲、不影响任何既有信号。

    assign menu_dir = MENU_UP_ON_1 ? sw1_lvl2 : ~sw1_lvl2;



    // ============================================================

    //  ★★★ 2026-10-21【D5 · S1 插播态】SW1 当"干接点"：拨上 = 报警

    // ------------------------------------------------------------

    //  语义（对应报告里的"商显 + 应急插播"）：

    //    · SW1 电平 = 1  ⇒ 立刻进报警态（`alert_on = 1`），**当帧生效**

    //    · SW1 电平 = 0  ⇒ 不是立刻退，**保持 10 s** 再恢复

    //      （现场规矩：信号抖动/短暂断开不能打断正在播的疏散提示）

    //

    //  ★ 报警期间只做两件事，不动装载、不动 SDRAM：

    //    ① `alert_on` 送给 disp_top ⇒ alert_ovl 叠"1 Hz 闪的红边框"（2026-10-25 起
    //       只闪边框、不再整屏红罩：现场要求紧急时图也要看得清）

    //    ② 压低 `adv_req_w`（轮播请求）⇒ 报警时**不换图**，

    //       因为一次装载要 0.8 s 且遮蔽显示，插播必须让位

    //

    //  ★ SW1 同时还是菜单方向位（`menu_dir`）：平时不拨，报警时才拨；

    //    菜单里要调方向就先断开 SW1（= 退出报警态）。这是单开关的取舍，

    //    已写进 03 计划表的"交互重排"，不再另加引脚。

    // ============================================================

    localparam integer ALERT_HOLD_MS    = 10000;

    localparam [28:0]  ALERT_HOLD_TICKS = ALERT_HOLD_MS * 50_000;   // 500,000,000



    // ---- ★ D5b【报警音】卡上第 5 个 .WAV（skip = 4）= 警报声 ----

    //   · 报警进来 ⇒ 音频链重装第 4 号 WAV 并从头循环播

    // ★ 2026-10-21：报警触发从 SW1(C8) 换到 SW4(C5)。
    //   板上若另有丝印 BUZ/SW 的开关（不在 SW1~SW4 内），把下面 sw4a_s1 的采样源换成那个引脚即可。
    reg sw4a_s1, sw4a_s2;
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin sw4a_s1 <= 1'b0; sw4a_s2 <= 1'b0; end
        else            begin sw4a_s1 <= sw4;  sw4a_s2 <= sw4a_s1; end
    end
    //   · 报警解除 ⇒ 重装回用户选的那一条（`sel_aud`）

    //   · 报警期间音量强制满档（`{4'hF, 4'hF}`），现场不会"报警声太小听不见"

    //   ★ 卡上没有第 5 个 .WAV 时 ⇒ find 失败 ⇒ aud_fail=1 ⇒ 报警没声音（图仍然报）。

    //     所以**上卡必拷 ALARM.WAV**（见 tools\gen_card_assets.py）。





    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            alert_on       <= 1'b0;

            alert_hold_cnt <= 29'd0;

        end

        else if (sw4a_s2) begin

            alert_on       <= 1'b1;

            alert_hold_cnt <= 29'd0;      // 只要接点闭合就一直报

        end

        else if (alert_on) begin

            if (alert_hold_cnt >= ALERT_HOLD_TICKS)

                alert_on <= 1'b0;         // 断开满 10 s ⇒ 恢复

            else

                alert_hold_cnt <= alert_hold_cnt + 29'd1;

        end

    end



    // ---- 报警边沿（给音频链"重装/换回"用）----

    reg  alert_d;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) alert_d <= 1'b0;

        else            alert_d <= alert_on;

    end

    wire alert_rise =  alert_on & ~alert_d;

    wire alert_fall = ~alert_on &  alert_d;

    // ★ D5b：卡上有没有报警音还没确认（larm_audio_ok=0）时，边沿不触发音频重装

    wire aud_edge   = (alert_rise | alert_fall) & alarm_audio_ok;



    // ---- 报警标志 → 像素域（两级；alert_ovl 在 clk_pix 域）----

    //   ★ 复位用 sys_rst_n：`disp_rst_n` 在下面才声明，而且它会在装载期间被拉低，

    //     拿它复位会让"报警中换图"把红框清掉。跨域异步复位在这里只作用于慢变量，安全。

    reg alert_s1, alert_s2;

    always @(posedge clk_pix or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            alert_s1 <= 1'b0;

            alert_s2 <= 1'b0;

        end

        else begin

            alert_s1 <= alert_on;

            alert_s2 <= alert_s1;

        end

    end



    // ★★ 2026-10-05：音频域的复位（音频 PLL 也锁上才放开）—— 到这里 sys_rst_n 已经声明过了

    assign aud_rst_n = sys_rst_n & pll_aud_locked;



    // ★★ 2026-09-28：写和读绝不能同时进行，但"只禁读"会把行缓冲饿死

    //    （上板实测：禁读一段时间后 disp_rd_en 永远是 0、行缓冲再也发不出请求，

    //      屏上只剩底色）→ 改成**写的时候把显示整块复位**，写完再从干净状态开始；

    //    这时图已经在 DRAM 里，一次就读对。

    //    ★ 开机那次（自测图）用"保持复位直到第一次写完"；

    //      A 每次装图期间也复位（装完自动恢复，屏上是新图）。

    reg disp_rst_hold;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n)      disp_rst_hold <= 1'b1;

        else if (!stwr_busy) disp_rst_hold <= 1'b0;

    end

    wire disp_rst_n = sys_rst_n & ~disp_rst_hold;   // ★ 别用 a_busy 复位整块显示：A 忙标志万一落不下来，屏上就永远无信号（读写互斥靠下面的 disp_rd_en_g 禁读就够了）



    // ★★ 2026-10-02：把"A 的启动"整件事交回 stub_ctrl，只留它一路。

    //    为什么删掉原来那路"保险启动"（a_start_force）：它和 stub_ctrl 各发一次，

    //    ① 上电会重复装两遍第 1 张；② stub_ctrl 内部的"第几张"计数器会因此和

    //    实际装的张数错位 —— 那样按 key3 换图会先重装一遍当前这张，看着像"没反应"。

    //    现在 stub_ctrl 负责"上电自动装第 1 张 + 每按一次 key3 装下一张"，计数自然同步。

    wire a_start_use = a_start;   // ★ 2026-10-21：报警换图改走 stub_ctrl 的请求通路（见 adv_req_w），这里不再另插脉冲         // 送给 A 的启动脉冲（★ 2026-10-21 加报警换图）



    // ★ 上电自动装第一张（100 ms 后）。stub_ctrl 靠这个把 next_no 推到 1，

    //   这样第一次按 key3 就是"第 2 张"。

    localparam integer CTL_AUTO_START = 1;



    // ============================================================

    //  1a. ★★ 转场 ↔ 控制桩 之间的三处跨域（2026-10-03，转场 ④）

    // ------------------------------------------------------------

    //   ① 像素域 → 控制域：front_sel（前台是谁）→ A 写【另一个】槽

    //   ② 像素域 → 控制域：may_load / active（都是长时间稳定的电平）

    //   ③ 控制域 → 像素域：req_tgl（翻一下 = 请求换下一张）/ fx_sel

    //   ★ 全部是慢变电平或"翻转一次"的握手，两位同步器就够；

    //     ★ 千万别把【单拍脉冲】直接跨域 —— 40MHz 和 50MHz 互采一定会漏。

    // ============================================================

    // 前台是谁：转场走完 transition_ctrl 给一拍 swap，就把它对调。

    //   ★ 放在这里（而不是描述符那一段）是因为下面的同步器要用它，

    //     而 Verilog 的声明必须先于使用。

`ifdef USE_DESC

    reg front_sel;

    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n)  front_sel <= 1'b0;

        else if (tr_swap) front_sel <= ~front_sel;

    end

`else

    wire front_sel = 1'b0;              // 写死单路时：前台永远是槽 0

`endif



    reg fs1, fs2;                       // front_sel → 控制域

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin fs1 <= 1'b0; fs2 <= 1'b0; end

        else        begin fs1 <= front_sel; fs2 <= fs1; end

    end

    // A 写【非前台】那个槽：前台=0 就写槽 1，前台=1 就写槽 0

`ifdef USE_DESC

    wire [2:0] a_slot_use = fs2 ? 3'd0 : 3'd1;

`else

    wire [2:0] a_slot_use = 3'd0;       // 写死单路时：就写槽 0

`endif



    reg ml1, ml2, ac1, ac2;             // may_load / active → 控制域

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            ml1 <= 1'b0; ml2 <= 1'b0;

            ac1 <= 1'b0; ac2 <= 1'b0;

        end

        else begin

            ml1 <= tr_may_load; ml2 <= ml1;

            ac1 <= tr_active;   ac2 <= ac1;

        end

    end



    wire        req_tgl;                // 控制桩翻一次 = 请求换下一张

    wire [1:0]  fx_sel_ctl;             // 控制桩选的淡入特效

    wire        k1_press_w;             // ★ 探针：`stub_ctrl` 内部消抖后的**换图按键**脉冲

                                        //   ★★★ 2026-10-17：这根输入现在是 **KEY2（B2/端口 key1）**

                                        //   （原来接的是 KEY3）⇒ 它统计的是"手动换下一张"的次数，

                                        //   轮播自己的请求**不**计入（轮播看字段 22）。

                                        //   ★ 2026-10-15【操作方式修订】：它仍是"**过了菜单门控之后**"

                                        //   的脉冲（输入 = `key1 | menu_on`）⇒ 菜单打开期间不计数。

    wire        req_pend_w;             // ★ 探针：转场请求挂起中



    // ============================================================

    //  ★★★ 2026-10-17【KEY3 改自动轮播】—— 用户改稿

    // ------------------------------------------------------------

    //  旧：KEY3（B1）按一次 = 换下一张图（手动）。

    //  新：**菜单关着时**，KEY3 每按一次 = 轮播开/关翻转；开着就每 ~3 秒自动换一张。

    //      菜单**打开**时 KEY3 仍是"移光标"（和以前一样，缩放要在菜单里改）。

    //  ★ 换图本身还是走 `stub_ctrl` 的老路（转场 → 米白 → 装载 → 淡入），

    //    只是把"按键脉冲"换成"轮播请求脉冲"（`u_ctrl` 新增的 `adv_req` 口），

    //    `stub_ctrl` 内部除受理判据那一处或门外**一个字没动**。

    //  ★ 轮播脉冲只在**空闲窗口**里给（不等转场、不撞装载、不抢挂起请求）：

    //    判据 = `!(a_busy | ac2 | req_pend_w)`，所以不会把一次换图挤掉。

    // ============================================================

    localparam integer CARO_MS = 6000;                       // ★ 2026-10-23：3 s → 6 s（1536x1152 单张要 4.7 s，3 s 会让队列永远追不上，字幕被饿死）

    // ★ 位宽注意：3000 ms × 50 MHz = **150,000,000** ⇒ 至少要 28 位。

    //   一开始写成 [17:0] 被截断成 ~5 ms，实测表现是"每几百毫秒换一张"，

    //   把转场/装载打崩、`fail_latch` 置位（一次上板就抓到了）。

    localparam [31:0]  CARO_TICKS = CARO_MS * 50_000;        // 50 MHz ⇒ 150,000,000

    reg  [31:0] caro_cnt;

    // ★★★ 2026-10-20【D1 · A3】：上电默认 = **1'b1（自动轮播）**。

    //   为什么改：商显/应急场景是**无人值守**上台 —— 原来 1'b0 要求现场有人按一次

    //   KEY3 才开始轮播，评委/路人不按，屏上就永远停在第一张（2026-10-19 评审列为

    //   "场景级致命"）。改成 1 之后：上电 → 装完首图 + 字幕 + 音频 → 3 s 后自动换下一张。

    //   ★ 现场仍可用 KEY3 手动暂停（电平语义没变），`caro_idle` 那两道闸门也没动。

    localparam CARO_ON_AT_BOOT = 1'b1;

    // ★★★ 2026-10-20【找图逻辑·按名字分类 开关】

    //   0 = 只按后缀 .BMP 找（老行为，卡里现有素材不动就能跑）

    //   1 = 只找 `AD*.BMP`（广告位）；`bmp_name_sel=1` 时只找 `MAP*.BMP`（插播图）

    //   ★ 上板实测（10-20 19:50）：设成 1 但卡里没有 AD 开头的图 ⇒ `S` 的 FAIL 位置 1、

    //     Apx=0、屏上没图。所以**必须先把素材改名**（AD1.BMP…）再把它改成 1。

    localparam BMP_NAME_EN = 1'b1;   // ★ 2026-10-21：名字过滤在共享引擎里做，这里开着重合无害

    reg         auto_caro;                                   // 轮播开关

    wire        caro_tick = (caro_cnt >= (CARO_TICKS - 32'd1));

    // ★★★ 空闲闸门（两道）：

    //   ① `!(a_busy | ac2 | req_pend_w)`：不撞装载、不撞转场、不抢挂起请求。

    //   ② `(sub_loaded | sub_fail)`：**开机那趟音频/字幕装载做完之前不许轮播**。

    //      这一条是上板试出来的：轮播从开机就跑的话，第一次换图会和"装字幕/装音频"

    //      那一次 start 撞在一起（A 只有一个 start 口）⇒ 字幕 fail

    //      （实测 field28 变成 6763：字幕 loaded=0/fail=1）。

    //      默认（`CARO_ON_AT_BOOT=0`）本来就不会开机轮播，这一条是防止用户一起机就按 KEY3。

    // ★ 2026-10-23：再加 `sub_pend_w` —— 字幕已经请求但还没发脉冲的那几拍，
    //   不许轮播插一脚进来抢同一个 start 口（实测一半字幕装载被这脚踹掉）。
    wire        caro_idle = ~(a_busy | ac2 | req_pend_w | sub_pend_w | sub_req_pend) & (sub_loaded | sub_fail);   // ★ 字幕还欠着就别轮播（防大图拖慢字幕）

    wire        adv_req_w = (auto_caro & caro_tick & caro_idle & ~alert_on) | img_load_pulse;   // D5: 报警期间停轮播；报警边沿用 img_load_pulse 借同一条请求通路（slot/描述符/切换都由 stub_ctrl 管）



    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            auto_caro <= CARO_ON_AT_BOOT;

            caro_cnt  <= 32'd0;

        end

        else begin

            // 菜单关着时，KEY3 = 轮播开关（低有效按键，`key3_step_press` 已是消抖后的单拍）

            if (key3_step_press && !menu_on) auto_caro <= ~auto_caro;

            if (!auto_caro)      caro_cnt <= 32'd0;

            // 轮播自己发过请求、或用户手动按了 KEY2（换下一张）⇒ 都重新计时，

            // 免得"手按完 0.2 秒又自动换一张"

            else if (adv_req_w || (key1_ok_press && !menu_on)) caro_cnt <= 32'd0;

            else if (!caro_tick) caro_cnt <= caro_cnt + 32'd1;

        end

    end



    // ============================================================

    //  ★★★ 2026-10-17【缩放改到菜单里 · 调节态】用户改稿：

    //    菜单打开 + 光标停在 ZOOM 行（`menu_sel == 0`，见 menu_ovl 的行序）+ 按 KEY2

    //    进入调节态（`menu_edit`），然后在调节态里：

    //      · 拨 **SW1** ⇒ 档位按拨动方向 ±1（上=+1，两端回绕 0↔5）；

    //      · 按 **KEY3** ⇒ 同一方向再步进一次（两套手感都支持）；

    //      · 再按 **KEY2** = 确认，退出调节态。

    //    ★ 面板上 ZOOM 行显示的活值就是它（menu_ovl 已经在用 `menu_zoom_lv`），

    //      所以调的时候能直接在屏上看到档数变化。

    //    ★ 菜单关着 / 光标不在 ZOOM 行 ⇒ 自动退出调节态（见上面那个 always）。

    //    ★ KEY4（软复位）、SW2（菜单开关）、SW3/SW4**都没动**。

    //

    //  ★★★ 2026-10-17【音量也进菜单】（用户要求"把改音量的功能加入菜单"）

    //    和 ZOOM **完全同一套手感**，只是行号不同（行 2 `VOLUME`）：

    //      · 光标停在 VOLUME 行 + 按 KEY2 ⇒ 进/出调节态（复用同一个 `menu_edit`）；

    //      · 调节态里按 KEY3 ⇒ 音量 ±1（方向 = `menu_dir`，和光标移动同一个方向位）；

    //      · **拨 SW1 本身不改任何数值**（用户 2026-10-17 明确要求过，这里照同一条规矩）。

    //    ★ 两端**夹住不绕回**（不是回绕）：音量 15 再加还是 15、0 再减还是 0 ——

    //      避免"按到顶突然跳到静音"这种意外。

    //    ★ 音量真的接到播放链上：`u_aud` 的 `.volume` 就是它（sfx_player 里

    //      `vol4 = volume[7:4]`，所以 `{vol_lv, 4'hF}` ⇒ 有效档 = vol_lv，15 = 原来写死的 8'hFF）。

    //    ★ 用**引脚复位** rst_n（和 zoom_lv 一样）：KEY4 软复位后音量保留。

    //

    //  ★★★ 2026-10-17【亮度也进菜单】（用户要求"做一个调节亮度的功能，类似音量"）

    //    行 3 `BRIGHT`，和 VOLUME **完全同一套手势**（光标停 BRIGHT 行 + KEY2 进调节态

    //    + KEY3 按方向 ±1 + KEY2 确认；SW1 只定方向、自己不改值）：

    //      · 两端**夹住不绕回**（0..15）；

    //      · 上电/软复位默认 15 = **原样**（数学上 `(c×16)>>4 = c` ⇒ 画面逐位不变）；

    //      · 它接的是 `disp_top.menu_bri` → `b_display\bri_scale.v`，

    //        压暗的是"画面 + 可视化柱 + 字幕"，**菜单面板本身不压暗**

    //        （否则亮度调到很低就再也看不清菜单了）；

    //      · 同样用**引脚复位** rst_n：KEY4 软复位后亮度保留。

    //    ★ 行 3 原来是占位 `EXIT`（按 KEY2 什么也不做）⇒ 现在被 BRIGHT 顶替，

    //      退菜单本来就是 SW2 拨一下，不需要 EXIT 这一行。

    // ============================================================

    //  ★★★ 2026-10-18【可视化总开关进菜单】行 4 `VISUAL`（用户要求"把可视化开关加进菜单"）

    //    手势和其它可调行**同构**（光标移到 VISUAL 行 → KEY2 进调节态 → KEY3 改 → KEY2 确认），

    //    但它是**布尔量**：每按一次 KEY3 就 ON↔OFF 翻转（不跟 SW1 方向 —— 只有两态，

    //    分上下没有意义，翻转最省事、也不会"按到顶没反应"）。

    //      · 上电/软复位默认 **1 = 显示**（= 加这个开关之前的行为，绝不影响现有观感）；

    //      · 用**引脚复位** rst_n、和音量/亮度同一口径 ⇒ KEY4 软复位后保留；

    //      · 接 `disp_top.menu_viz_on`：关掉时柱形和那块压暗底一起门掉，

    //        `px_v` 逐位等于 `px_mix`（屏上一点可视化痕迹都不留）；

    //      · 后台 viz_time / viz_freq **照样跑**（它们只旁听音频），重新打开立刻有图。

    // ============================================================

    wire zoom_step = menu_edit & key3_step_press & (menu_sel == 3'd0);  // ★ 档位**只由 KEY3 改**；SW1 只定方向（用户 2026-10-17 明确）

    wire vol_step  = menu_edit & key3_step_press & (menu_sel == 3'd2);  // ★ 同上：音量也只用 KEY3 改

    wire bri_step  = menu_edit & key3_step_press & (menu_sel == 3'd3);  // ★ 同上：亮度（行 3 BRIGHT）

    // ★★★ 2026-10-24【菜单行 1「音轨」→「可视」开关】：行 1 恢复成音频可视化总开关

    //   （2026-10-20 D1 曾把行 4 `VISUAL` 删掉、可视化改常开；用户 2026-10-24 要求

    //     「菜单音轨取消，换成音频可视化的开关」⇒ 复用行 1，手势与其它可调行同构，

    //      但它是布尔量：调节态里每按一次 KEY3 就 ON↔OFF 翻转，不跟 SW1 方向）。

    //   · 上电/软复位默认 **1 = 显示**（= 加这个开关之前的行为，绝不影响现有观感）；

    //   · 用**引脚复位** rst_n、和音量/亮度同一口径 ⇒ KEY4 软复位后保留；

    //   · 串口字段 21 bit9 = viz_on（`dbg_caro_word` 里本来就有这一位）⇒ 不开屏也能看状态；

    //   · 后台 viz_time 照样跑（它只旁听音频），重新打开立刻有图。

    wire viz_step = menu_edit & key3_step_press & (menu_sel == 3'd1);  // ★ 行 1：ON↔OFF 翻转（不看方向）

    reg  viz_on;                                                        // 1 = 显示 / 0 = 关闭



    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            zoom_lv <= 3'd0;

            viz_on  <= 1'b1;                       // ★ 2026-10-24：可视化上电默认开（= 加开关之前的行为）

        end

        else if (zoom_step) begin

            // 方向 = `menu_dir`（1 = 上 = +1），两端回绕

            if (menu_dir) zoom_lv <= (zoom_lv == 3'd5) ? 3'd0 : (zoom_lv + 3'd1);

            else          zoom_lv <= (zoom_lv == 3'd0) ? 3'd5 : (zoom_lv - 3'd1);

        end

        else if (viz_step) begin

            viz_on <= ~viz_on;                    // ★ 行 1 开关：每按一次 KEY3 翻转（只有两态，不分方向）

        end

    end



    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            vol_lv <= 4'd2;                        // ★ 2026-10-24：上电 20%（vol_lv 0..10，2 = 20%；不静音，展会现场一上电就有声但别太响）

        end

        else if (vol_step) begin

            // 方向 = `menu_dir`（1 = 上 = +1），两端**夹住**

            if (menu_dir)  vol_lv <= (vol_lv == 4'd10) ? 4'd10 : (vol_lv + 4'd1);

            else           vol_lv <= (vol_lv == 4'd0)  ? 4'd0  : (vol_lv - 4'd1);

        end

    end



    // ★★★ 2026-10-17【亮度进菜单】：和音量同一套口径（夹住、方向 = menu_dir、引脚复位保留）

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            bri_lv <= 4'd10;                       // ★ 2026-10-21：上电 100%（用户要求：亮度不要开机就压暗）

        end

        else if (bri_step) begin

            if (menu_dir)  bri_lv <= (bri_lv == 4'd10) ? 4'd10 : (bri_lv + 4'd1);

            else           bri_lv <= (bri_lv == 4'd0)  ? 4'd0  : (bri_lv - 4'd1);

        end

    end



    // ★ KEY2（确认键）按下次数 → 串口字段 18（原来这一格统计的是"缩放旋钮"按下次数）

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n)                                key_cnt <= 4'd0;

        else if (key1_ok_press && key_cnt != 4'hF)     key_cnt <= key_cnt + 4'd1;

    end



    // ★ 轮播请求计数（上板判读"到底有没有在换图"）→ 串口字段 22

    reg [15:0] caro_dbg_cnt;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n)                                 caro_dbg_cnt <= 16'd0;

        else if (adv_req_w && caro_dbg_cnt != 16'hFFFF) caro_dbg_cnt <= caro_dbg_cnt + 16'd1;

    end



    // ★★★ 2026-10-17【串口可读】：轮播/菜单/缩放的状态字 → 字段 21（本来恒 0）

    //   位：[7]=auto_caro [6:4]=zoom_lv [3]=menu_on [2:1]=menu_sel [0]=menu_edit

    //   ★ 帧格式/字段数不变，只是把一格常量换成真实状态 —— 上板判读"按了 KEY3 到底开没开"用。

    // ★★★ 2026-10-17【亮度进菜单】：高 4 位本来是常量 0，现在放 `bri_lv`（0..15）——

    //   亮度是"改了就整屏变暗"的功能，没有一格读数就只能靠肉眼看，所以借这 4 位。

    // ★★★ 2026-10-18【可视化开关进菜单】：`menu_sel` 4→5 项变成 **3 位**，

    //   字段 21 一共只有 16 位 ⇒ 重新排一次（位序变了，读串口的脚本要跟着改）：

    //       [15:12] = bri_lv      （亮度 0..15）

    //       [11:10] = 0

    //       [9]     = viz_on      （可视化开关，1 = 显示）

    //       [8]     = auto_caro   （轮播开/关）

    //       [7:5]   = zoom_lv     （缩放档 0..5）

    //       [4]     = menu_on

    //       [3:1]   = menu_sel    （光标 0..4）

    //       [0]     = menu_edit

    //   ★ 判读：默认态（亮度 15 / 可视化开 / 轮播关 / 适配档 / 菜单关）读作 **`F200`**；

    //     把亮度调到 0 读 `0200`；关掉可视化读 `F000`（bit9 落 0）。

    wire [15:0] dbg_caro_word = {bri_lv, 2'd0, viz_on, auto_caro, zoom_lv, menu_on, menu_sel, menu_edit};

    // ★★★ 2026-10-22【临时探针 · 查"拔卡软复位只成功一次"】
    //   字段 13（原行缓冲探针，早就接常数 0）借来报 SD/软复位状态：
    //     [15:8] = 累计触发次数（sd_lost 上升沿个数，饱和到 255；吃 rst_n，不被软复位清）
    //     [7]    = 当前 soft_rst 电平
    //     [6]    = 当前 sd_lost 电平
    //     [5:4]  = fail_cnt（连续读失败次数）
    //     [3]    = a_sd_ready
    //     [2]    = a_load_done 电平锁存（近 2 s 内有没有装载成功）
    //     [1]    = a_busy
    //     [0]    = sd_lost_rise 单拍（很难撞到，仅供逻辑核对）
    reg  [7:0] dbg_sr_cnt;
    reg        dbg_ld_ok;
    reg  [11:0] dbg_ld_tmr;
    reg  [1:0] fail_cnt;        // 连续读失败次数（实现在下面的 sd_lost 段，声明提前给探针用）
    reg  [25:0] lost_tmr;       // ★ 拔卡确认计时（0 = 没在计时）
    // ★ 2026-10-22 用户要求：拔出确认时间对齐到 1 s（原来 2 s）
    //   代价要说清楚：单张读失败后，若重试的那张是 1536×1152（装载要 4.7 s），
    //   1 s 到点时它还没读完 ⇒ 会被判成"卡没了"。所以素材里不要放 >1 Mpx 的图，
    //   或者把这里改回 26'd100_000_000（2 s）。
    localparam integer LOST_CONFIRM_TICKS = 26'd50_000_000;    // 1.0 s @ 50 MHz
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_sr_cnt <= 8'd0;
        end
        else if (sd_lost_rise && (dbg_sr_cnt != 8'hFF)) begin
            dbg_sr_cnt <= dbg_sr_cnt + 8'd1;
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dbg_ld_ok  <= 1'b0;
            dbg_ld_tmr <= 12'd0;
        end
        else if (a_load_done) begin
            dbg_ld_ok  <= 1'b1;
            dbg_ld_tmr <= 12'd3000;      // 约 2 s 后自清
        end
        else if (dbg_ld_tmr != 12'd0) begin
            dbg_ld_tmr <= dbg_ld_tmr - 12'd1;
        end
        else begin
            dbg_ld_ok  <= 1'b0;
        end
    end
    wire [15:0] dbg_sd_word = {dbg_sr_cnt, soft_rst, sd_lost, fail_cnt,
                               a_sd_ready, dbg_ld_ok, a_busy, sd_lost_rise};




    // 控制域 → 像素域：req_tgl 取边沿 = 一拍请求脉冲

    reg rt1, rt2, rt3;

    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin rt1 <= 1'b0; rt2 <= 1'b0; rt3 <= 1'b0; end

        else             begin rt1 <= req_tgl; rt2 <= rt1; rt3 <= rt2; end

    end

    assign tr_req = rt2 ^ rt3;



    // 控制域 → 像素域：fx_sel（只变不抖，两位同步器）

    reg [1:0] fx1, fx2;

    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin fx1 <= 2'd0; fx2 <= 2'd0; end

        else             begin fx1 <= fx_sel_ctl; fx2 <= fx1; end

    end

    assign tr_fx = fx2;



    // ============================================================

    //  ★★★ 2026-10-08【预装 prefetch】控制桩 ↔ 转场 的两根新线

    // ------------------------------------------------------------

    //   pf_ready_w   : 控制域。后台槽里已经装好"下一张"（长时间稳定的电平）

    //   req_accept_w : 控制域。本次换图请求被受理（★ 单拍）—— 音效挂它

    //   ★ 需求：按键时**转场立刻开始**（屏上不再有"按下去 0.3~1.8 秒没反应"）。

    //     顶层在 IDLE 期间就指挥 A 把下一张装进后台槽（见 stub_ctrl 头注释）。

    //   ★ 三处连线，全在这一段里做完（声明必须先于使用 —— 下面 569 行就例化它）：

    //     ① pf_go：允许预装的门。★ 竞态①（撞上音效自检）：顶层

    //        `.start(a_start_use | aud_load_pulse)` + `.skip(aud_want ? 0 : a_skip)`

    //        ⇒ 预装的 a_start 若和 aud_load_pulse 同拍，会被当成"装音效"，

    //        图的脉冲丢了 ⇒ stub_ctrl 等的 a_load_done 永远不来 ⇒ 卡死。

    //        所以音频自检没做完（也没失败）之前，一个预装都不许发。

    //     ② pf_ready → 像素域：慢变电平，两位同步器就够（★ 单拍脉冲绝不能这么跨）。

    //        这就是给 transition_ctrl 的 `back_ready`。

    //     ③ 例化里带上的 .a_load_done / .pf_ready_o / .req_accept_o。

    // ============================================================

    localparam AUD_PF_GO = AUDIO_OFF;             // 音频整个关掉时直接允许预装

    // ★★★ 2026-10-23【字幕优先于预装】
    //   原式只看"音频自检做完没有"；现在再与上 `~sub_pend_w` ——
    //   字幕一旦进入状态 1/2（想装 / 正在装），预装就先让路。
    //   ★ 只影响 stub_ctrl 的"预装"那一条（`pf_go` 在它内部只喂 ③ 号判据），
    //     用户按键/轮播请求、真正的换图装载都不受影响。
    wire       pf_go_w   = (AUD_PF_GO | aud_loaded | aud_fail) & ~sub_pend_w;

    wire       pf_ready_w;

    wire       req_accept_w;



    reg pfr1, pfr2;                               // pf_ready → 像素域（两位同步器）

    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin pfr1 <= 1'b0; pfr2 <= 1'b0; end

        else             begin pfr1 <= pf_ready_w; pfr2 <= pfr1; end

    end

    wire tr_back_ready = pfr2;                    // → disp_top → transition_ctrl



    // ★★ 2026-10-09：字幕的"要不要显示"也是 50 MHz 域的电平 → 像素域，同样两位同步器

    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin sub_on_s1 <= 1'b0; sub_on_s2 <= 1'b0; end

        else             begin sub_on_s1 <= sub_loaded; sub_on_s2 <= sub_on_s1; end

    end



    // ============================================================

    //  ★★★ 2026-10-15【功能 · 开关4（SW4 / C5）→ 字幕水平滚动】—— 端到端就这四级

    // ------------------------------------------------------------

    //     sw4(引脚 C5，异步)

    //       → [50 MHz 域两级同步 sw4_s1/sw4_s2]        ← 防亚稳（就是题目说的"同步 2 拍"）

    //       → [像素域两级同步  sw4_p1/sw4_p2]          ← 跨到 clk_pix（慢变电平，2 级够，

    //                                                     和上面 sub_on / 预装的 pfr 完全一个做法）

    //       → disp_top.sub_scroll → subtitle_ovl.scroll_en

    //       → 帧首（vs 上升沿）`scroll_x += STEP`（按 800 回绕）→ 取字/取位时把列偏移。

    //  ------------------------------------------------------------

    //   ★ 为什么**不加** sw_edge_debounce / 专门的消抖：

    //     ① 这里要的是**电平**（拨到一侧=开、拨回去=关），不是"变化事件"；

    //     ② 机械触点的抖动（几十 µs ~ 几 ms）**天然被滤掉** —— 下游 `scroll_x` 一帧

    //        （16.6 ms）只在**帧首那一拍**采一次 `scroll_en`，抖动最多让"开始/结束"差一帧

    //        （肉眼无感），**绝不会**在帧内改偏移（那才会看到跳/撕裂）。

    //     ③ 又多一层好处：**没有边沿 → 上电不会白多一个脉冲**（sw_edge_debounce 文件头讲过的坑），

    //        拨回去也不会"多走一格"。

    //   ★ 复位各用哪个：50 MHz 那一级跟 `sys_rst_n`（和其它开关/消抖一致）；

    //     像素域那一级跟 `disp_rst_n`（和 sub_on/pfr 一致 —— disp_top 装载期间会被整块复位，

    //     这里跟着复位 ⇒ 复位后首帧 scroll_en=0、scroll_x=0 ⇒ 从"静止原位"开始）。

    // ============================================================

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin sw4_s1 <= 1'b0; sw4_s2 <= 1'b0; end

        else            begin sw4_s1 <= sw4;  sw4_s2 <= sw4_s1; end

    end



    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin sw4_p1 <= 1'b0; sw4_p2 <= 1'b0; end

        else             begin sw4_p1 <= sw4_s2; sw4_p2 <= sw4_p1; end

    end



    // ============================================================

    //  ★★★ 2026-10-15【参数菜单·第1步】菜单状态（50 MHz 控制域）→ 像素域：两级同步

    // ------------------------------------------------------------

    //   `menu_on` / `menu_sel` 都是**慢变电平**（只在人拨 SW2/SW1 时才动，最快也是

    //   20 ms 一次），所以按本工程一贯的做法（`sub_on` / `pf_ready` / `sw4` 全是这一套）

    //   打两级就够。

    //   ★ 复位跟 `disp_rst_n`（和 sub_on/pfr/sw4 的口径一致）：装载期间显示整块被复位时

    //     它跟着复位 ⇒ 复位后首帧菜单是关的。

    //   ★ 跨域瞬间最多错一帧（16.6 ms 内），肉眼无感；绝不会在帧内改（那才可能撕画面）。

    //   ★ 域：这两根接着 disp_top 的 `menu_on/menu_sel`，那里是 clk_pix 域 ⇒ 对。

    // ============================================================

    reg        menu_on_s1, menu_on_s2;                  // menu_on  → 像素域（两级）

    reg  [MENU_W-1:0] menu_sel_s1, menu_sel_s2;         // menu_sel → 像素域（两级）

    // ★ 2026-10-17：`menu_edit` 曾不再需要送像素域（面板高亮条已删，调节态没有画面反馈）
    // ★ 2026-10-24：又要送了 —— 用户要求"确认后外面的框变红"（KEY2 进调节态 ⇒ 选中格描边变红）
    reg        menu_edit_s1, menu_edit_s2;                  // menu_edit → 像素域（两级）



    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin

            menu_on_s1  <= 1'b0;            menu_on_s2  <= 1'b0;

            menu_sel_s1 <= {MENU_W{1'b0}};  menu_sel_s2 <= {MENU_W{1'b0}};

            menu_edit_s1 <= 1'b0;           menu_edit_s2 <= 1'b0;

        end

        else begin

            menu_on_s1  <= menu_on;    menu_on_s2  <= menu_on_s1;

            menu_sel_s1 <= menu_sel;   menu_sel_s2 <= menu_sel_s1;

            menu_edit_s1 <= menu_edit; menu_edit_s2 <= menu_edit_s1;

        end

    end



    // ============================================================

    //  ★★★ 2026-10-15【参数菜单·第2步】把"要显示的活值"也同步到像素域

    // ------------------------------------------------------------

    //  菜单第 2 步要在面板里显示 `zoom_lv`（缩放档 0..5）和 `sel_aud+1`（音频 1..4）。

    //  这两根都在 50 MHz 控制域（KEY2/SW3 改的），必须**先同步到 clk_pix 域**才能进

    //  `menu_ovl`（和 menu_on/menu_sel 同一口径、同一个两级同步器写法、同一个复位）。

    //  ★ 纯"读"通道：既不回写寄存器，也不参与任何既有逻辑 ⇒

    //    `menu_on=0` 时它们只是两根没人看的电平，屏上/时序上零影响。

    //  ★ 面积：`zoom_lv` 3 位 + `sel_aud` 2 位 = 5 个新寄存器（两级同步 = 10 个）——

    //    这是本步**唯一**新加的时序器件。

    // ============================================================

    reg [2:0] zoom_s1, zoom_s2;                  // zoom_lv → 像素域（两级）

    reg [1:0] aud_s1,  aud_s2;                   // sel_aud → 像素域（两级）

    // ★★★ 2026-10-17【音量进菜单】：vol_lv → 像素域（两级，和上面同一口径/同一个复位）

    reg [3:0] vol_s1,  vol_s2;

    // ★★★ 2026-10-17【亮度进菜单】：bri_lv → 像素域（两级，和音量同一口径/同一个复位）

    reg [3:0] bri_s1,  bri_s2;

    // ★★★ 2026-10-18【可视化开关进菜单】：viz_on → 像素域（两级；复位 = 1 显示）

    reg       viz_s1,  viz_s2;



    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin

            zoom_s1 <= 3'd0; zoom_s2 <= 3'd0;

            aud_s1  <= 2'd0; aud_s2  <= 2'd0;

            vol_s1  <= 4'd5;  vol_s2 <= 4'd5;    // ★ 2026-10-24：上电 50%

            bri_s1  <= 4'd10; bri_s2 <= 4'd10;   // ★ 2026-10-21：上电 100%（10 = 原样）

            viz_s1  <= 1'b1;  viz_s2 <= 1'b1;    // ★ 复位 = 显示（= 加开关之前的行为）

        end

        else begin

            zoom_s1 <= zoom_lv;  zoom_s2 <= zoom_s1;

            // ★ 2026-10-25：菜单行 1 已改为可视化开关、不再显示音轨号，这里只留 2 位（显式截断，避免位宽告警）
            aud_s1  <= sel_aud[1:0];  aud_s2 <= aud_s1;

            vol_s1  <= vol_lv;   vol_s2  <= vol_s1;

            bri_s1  <= bri_lv;   bri_s2  <= bri_s1;

            viz_s1  <= viz_on;   viz_s2  <= viz_s1;

        end

    end



    stub_ctrl #(

        .CLK_HZ(50_000_000), .AUTO_DELAY_MS(100), .RST_HOLD_MS(5),

        .SLOT_BASE(0), .AUTO_START(CTL_AUTO_START)

    ) u_ctrl (

        .clk(clk), .rst_n(rst_n),

        // ★★★ 2026-10-15【参数菜单·操作方式修订】**本步唯一动到的既有连线**：

        //   `stub_ctrl` 的按键输入从 `key3` 改成 `key3 | menu_on`（按键**低有效**，

        //   表达式 = 1 表示"没按"）⇒ **菜单打开时它恒为 1，换图那条路被屏蔽**；

        //   `menu_on = 0` 时按位或常量 0 ⇒ **恒等于原来的 `key3`** ⇒ 菜单关闭行为逐位不变。

        //   ★ `stub_ctrl` 内部**一个字没改**（`git status` 里 `rtl/stub_ctrl.v` 未修改）；

        //     模块里 KEY3 的消抖（`u_k1`）/ 请求（`req_take`）/ 预装（`pf_go`）三条判据

        //     都**只看这一根输入**，模块内**没有第二处**引用按键输入 ⇒ 只门控这一处就够。

        //   ★ 唯一副作用（预期内）：菜单打开期间按 KEY3，串口字段 6 的 `k1_press_w`

        //     计数不再增加（那是 `stub_ctrl` 的**输出**探针，喂给 `dbg_report`）。

        // ★★★ 2026-10-17【KEY3 改自动轮播】：手动换一张不再走 KEY3（它是轮播开关），

        //   换图改为 `adv_req`（上面的 `adv_req_w`，3 秒一次、只在空闲窗口给）。

        // ★★★ 2026-10-17【KEY2 改"下一张"】（用户改稿）：

        //   `stub_ctrl` 的按键输入现在是 **KEY2（B2 / 端口 key1）**，仍然按"菜单开着就屏蔽"

        //   的口径写成 `key1 | menu_on`：

        //     · 菜单**关**着 ⇒ 恒等于 `key1` ⇒ **按一下 KEY2 = 换下一张**（手动）；

        //     · 菜单**开**着 ⇒ 恒为 1（没按） ⇒ 不换图，KEY2 那条路让给菜单的"缩放调节"。

        //   ★ 手动换图和轮播请求同走 `adv_take = k1_press | adv_req`（`stub_ctrl` 内）。

        .key1(key1 | menu_on), .key2(key2), .adv_req(adv_req_w), .force_load(img_load_pulse),

        .sd_ready(sd_ready_eff), .sd_lost_i(sd_lost_rise), .alert_rst_i(alert_rst_pulse),
        .a_busy(a_busy), .hold(stwr_busy),

        // ★ 转场握手：屏上全米白了才真的去装；转场期间不受理新请求

        .may_load(ml2), .tr_active(ac2),

        .slot_in(a_slot_use),

        .a_start(a_start), .a_skip(a_skip),

        .a_use_slot(a_use_slot), .a_slot_base(a_slot_base),

        .a_img_no(a_img_no), .soft_rst(soft_rst),

        .req_tgl(req_tgl), .fx_sel(fx_sel_ctl),

        .k1_press_o(k1_press_w), .req_pend_o(req_pend_w),

        // ★★★ 2026-10-08【预装】四根新线

        .pf_go(pf_go_w), .a_load_done(a_load_done_dly),

        .pf_ready_o(pf_ready_w), .req_accept_o(req_accept_w),
        .req_skip_o (req_skip_w)        // ★★★ 2026-10-24【一图一乐】这张图是第几张（与 req_accept 同拍）

    );



    // ============================================================

    //  1b. 【已删除】B 自己的自测图写入器 stub_a_writer（2026-10-15 逐步减重·第①步）

    // ============================================================

    //  被删掉的东西：

    //    · `always` 块（stwr_cnt / stwr_start / stwr_fired 的产生器）

    //    · `stub_a_writer #(.PAGE_W(640),.PAGE_H(480),.PAT_MODE(2)) u_self`

    //  为什么删了行为不变（三条硬证据）：

    //    ① 复位分支里写死 `stwr_fired <= 1'b1`（"关掉开机自测图，让 A 装真图"），

    //       ⇒ `!stwr_fired` 分支永不执行 ⇒ `stwr_start` 恒 0 ⇒ 该模块**从不上电自检**，

    //         `stwr_busy` 恒 0、`stwr_done` 恒 0（上板早就如此）。

    //    ② 写口二选一按 `stwr_busy` 选（见下面第 2b 节）⇒ 一直选的就是 A 的真实图。

    //    ③ 它的 8 个输出里 6 个（a_wr_*）只进那个二选一；剩下 busy/done 只进

    //       "读闸门 / disp_rst_hold / 串口 flags bit3 / 那个 50ms 延时器"，

    //       而那个延时器的唯一消费者 `st_go` 早在 2026-10-09 读口自检删除后就死了。

    //  ⇒ 现在 `stwr_busy` 是常量 0，所有这些下游取值与删之前完全相同。

    //  ★ 要恢复：`git show HEAD:rtl/top_m2.v`（搜 stub_a_writer）把这段放回来，

    //    并把 prj\M2.al 里那条 <File Path="../rtl/stub_a_writer.v"> 加回去。



    // ============================================================

    //  2. A 的装载机（SD → BMP → 565 → SDRAM 写口 + 描述符）

    // ============================================================

    wire [2*64-1:0] a_desc;

    wire        a_commit_tgl, a_ack_tgl;

    wire [31:0] a_dbg_px_cnt, a_dbg_wr_cnt;

    wire [15:0] a_dbg_first_px;

    wire        a_dbg_overrun, a_dbg_warn_odd;

    wire [31:0] a_dbg_first_addr;   // A 报的第一个像素的地址（期望 (H-1)*W = 479*640）



    // ★★ 2026-10-02 接上 A 的新接口（A 轨 368cbfd「音频+缩放」）：

    //    A 的 top_a 从这一版起同时管"装图"和"装音频"，start 那一拍由 sd_to_wav 决定装哪个。

    //    · 本版（M1_super 第一遍）只装一张 BMP → sd_to_wav 恒 0、sfx_base 恒 0；

    //    · 音频的三个诊断口先接到线网上备用（以后接串口探针看 wav_cnt / wav_odd）。

    //    ★ 注意：这四路是【新增】的，漏接不会报错 —— sd_to_wav 悬空成 Z 时，

    //      top_a 内部 bmp_start / wav_start 会同时变成不定态，两条链都不启动。

    wire        a_wav_done;

    wire [31:0] a_dbg_wav_cnt;

    wire        a_dbg_scaled, a_dbg_wav_odd;



    // ★★★ 2026-10-15【音频溢出保护】：把"音效区容量"传进 top_a ——

    //   top_a 用它同时夹【装载长度 sdr_len】和【放行的采样数】⇒ 超出 5.0 s 的字一个都不写，

    //   绝不越界写进后面的小槽区 / 字幕区。契约常量仍然只在上面 SFX_STRIDE 一处定义。

    top_a #(.SLOT_NUM(2), .AUDIO_MAX_WORDS(SFX_STRIDE), .BMP_NAME_EN(BMP_NAME_EN)) u_a (

        // ★★★ 2026-10-21【D3 · C1】这里从 `sys_rst_n` 改成 `a_rst_n`：

        //   多串了一个"卡没插时每 500 ms 自动重试"的局部复位脉冲（见上面 C1 那段）。

        //   `a_rst_n = sys_rst_n & ~a_recover`，正常运行时与 `sys_rst_n` 完全一样。

        .sys_clk(clk), .sys_rst_n(a_rst_n),

        // ★★★ 2026-10-17【SD 读时钟：25 MHz 试过、**不可靠**，现在退回 12.5 MHz】

        //   走法：`.clk_spi(clk_par)`（100 MHz）⇒ SCLK = 25 MHz。上板遥测：`load_done` 掉、

        //   `a_dbg_px_cnt` 以 3.9 Mpx/s 疯跑（= 11.8 MB/s > 25 MHz 的物理上限 3.1 MB/s）

        //   ⇒ 读回的是错数据、在反复重试。**不是时序问题**：时序报告里 100 MHz 域

        //   SWNS +0.971 ns、0 违例。⇒ 判定为卡/走线的信号完整性扛不住。

        //   现在 `top_a` 内部用的是 sys_clk（SCLK 12.5 MHz，实测 379 kpx/s = 1.14 MB/s）；

        //   这一根保留着，将来换卡/换走线可以一行切回 `clk_par`。

        .clk_spi(clk),

        .spi_miso(sd_miso), .spi_mosi(sd_mosi),

        .spi_clk(sd_dclk), .spi_cs(sd_ncs),

        // ★★★ 2026-10-08：A 的 top_a 改成**三选一**（`sd_to_wav` 一位 → `sd_mode` 两位）——

        //   0 = 装图（控制桩那套，和以前一模一样）

        //   1 = 装音频（自产的音效自检）

        //   2 = 装字幕（自产的字幕自检；卡里第 1 个 .SUB）

        //   ★ sd_mode / skip / 基址 全部由【发脉冲的那一个】决定，而且 top_a 本来

        //     就在 `start` 那一拍锁存 ⇒ 三条链绝不会中途易主。

        //   ★ 三个脉冲由各自的 FSM 产生，且字幕那条**等音频做完**才动 ⇒ 不会撞。

        .start(a_start_use | aud_load_pulse | sub_load_pulse),

        .sd_mode(a_sd_mode),

        .skip(a_sd_skip),   // ★ 2026-10-21：改吃统一的那根（原来这里自己又拼了一遍，漏了报警换图的 skip=0）

        // ★★★ 2026-10-20【找图逻辑·按名字分类】：0 = 只找 `AD*.BMP`（广告位），

        //   1 = 只找 `MAP*.BMP`（插播画面）。S1 插播态做出来后这里接 `alert_on`。

        .bmp_name_sel(1'b0),

        // ★★★ 2026-10-21【报警素材集】alert_on=1 ⇒ 三条链都只认 EMG*；=0 ⇒ 排除 EMG*

        .name_emg_only(alert_on),

        .use_slot(a_use_slot),

        .slot_base(a_slot_base), .img_no(a_img_no),

        .sfx_base(a_sd_mode == 2'd1 ? SFX_BASE : 21'd0),

        .sub_base(a_sub_base),

        .busy(a_busy), .load_done(a_load_done), .desc_done(a_desc_done),

        .ready_n(a_ready_n), .fail(a_fail), .o_fail_src(a_fail_src),
        .o_sub_dbg(a_sub_dbg),
    .sd_ready(a_sd_ready), .led_init(),
        .o_fe_done(a_fe_done),

        .sub_done(a_sub_done),

        .a_wr_req(a_wr_req), .a_wr_base(a_wr_base), .a_wr_len(a_wr_len),

        .a_wr_ack(a_wr_ack),

        .a_wr_data(a_wr_data), .a_wr_we(a_wr_we),

        // ★ 只给 A 看到"消隐期之外就算满" —— 它的推字就只发生在消隐期

        .a_wr_full(a_wr_full_g), .a_wr_done(a_wr_done), .sdr_ready(sdr_ready),

        .a_desc(a_desc), .a_commit_tgl(a_commit_tgl), .a_ack_tgl(a_ack_tgl),

        .dbg_px_cnt(a_dbg_px_cnt), .dbg_first_px(a_dbg_first_px),

        .dbg_wr_cnt(a_dbg_wr_cnt),

        .dbg_overrun(a_dbg_overrun), .dbg_warn_odd(a_dbg_warn_odd),

        .dbg_first_addr(a_dbg_first_addr),

        .wav_done(a_wav_done), .dbg_wav_cnt(a_dbg_wav_cnt),

        .dbg_scaled(a_dbg_scaled), .dbg_wav_odd(a_dbg_wav_odd),

        // ★★ 2026-10-09 字幕链的诊断（上板看不到字，靠这三个数定位）

        .dbg_sub_wr_cnt(a_dbg_sub_wr_cnt),

        .dbg_sub_overrun(a_dbg_sub_overrun),

        .dbg_sub_short(a_dbg_sub_short),

        // ★★★ 2026-10-21【D3 · C2/C3】素材格式（兜底页用它讲清楚"到底哪儿不对"）

        .o_img_bpp(a_img_bpp), .o_aud_rate(a_aud_rate),

        .o_aud_bits(a_aud_bits), .o_aud_info_valid(a_aud_iv)

    );





    // ============================================================

    //  3. 存储封装（SDRAM 例化在它里面）

    // ============================================================

    wire        sdr_init_done, sdr_busy, sdr_init_ref_vld;

    wire [23:0] sdr_wr_cnt;

    wire        rd_vld;

    wire [31:0] rd_data;



    // ★★ 2026-09-28：读口【完全交给显示】。

    //    上板实测：读口自测（`vendor_read_test`，按官方读引擎写的那套）会一直占着

    //    读口不放（串口里 disp_rd_en=0、行缓冲全是被掐断），显示一条数据都读不到，

    //    屏上只剩合成器底色（纯蓝）。自测实例留着（它只是数收到的数据，无害），

    //    但读口不再做"二选一"。

    // 读口【永远】归显示

    // ★★★ 2026-10-05：读口现在**绕经 top_aud**（A 的音频链要借读口取音效 PCM）。

    //   绕道方式（A 的说明书 §3.2，line_buf.v / sdr_arb.v 一行都不改）：

    //      disp_top.mem_rd_en/addr  → top_aud.line_rd_req/addr

    //      top_aud.line_rd_data/vld → disp_top.mem_rd_data/vld

    //      top_aud.sdr_rd_en/addr   → sdr_arb.disp_rd_en/addr   （= 下面这两根）

    //      sdram.Sdr_rd_dout/Sdr_rd_en → top_aud.mem_rd_dout/vld

    //   ★ 仲裁是"显示优先、音频只捡显示不用的拍"，**绝不压 disp_rd_en**

    //     （line_buf 的 fsent 是自己数的，压一拍就少收一个字 → 那行错位）。

    //   ⇒ 原来那两根直连线由 top_aud 驱动。

    // ★★★ 2026-10-06：音频和显示都改成块级之后，**没有任何东西再用逐拍读口**了，

    //   所以这两根打桩成 0（sdr_arb 内部的读侧本来就已经断开、App_rd_* 也没接）。

    assign st_rd_addr_m = 21'd0;

    assign st_rd_en_m   = 1'b0;



    // ============================================================

    //  ★★★ 2026-10-03（转场"不经过米白"）★★★  读口：整段禁读 → 只在写突发时等一等

    // ------------------------------------------------------------

    //  旧做法（`define 关掉时）：`a_busy` 期间把显示读**整段掐掉** →

    //     装载那几秒屏上是米白（这就是"三步方案"里那一步的来历）。

    //     ★ 但掐读是**有损**的：行缓冲按"发出去多少就收多少"记账，

    //       这一行只能等看门狗放弃（屏上那行变底色）。

    //  新做法（默认打开）：请求**原样**送下去，只在写引擎**突发**的那几拍

    //     让行缓冲**等一等**（`mem_rd_ok=0`，见 line_buf 的 rd_ok 那一段）。

    //     → 装载期间**旧图继续显示**，屏上不再有米白那一段。

    //  ★ 为什么代价极小：SD 慢，写突发是 512 字 / 约 20 ms 一次、每次约 4 µs

    //     （0.02% 的时间）；显示一行有 26 µs 余量，最多被推迟几 µs。

    //  ★★ 上板判读：万一看到花屏/错误像素，把下面这行注释掉就回到旧行为。

    // ============================================================

// `define LOAD_WITH_READS

//   ★★★ 2026-10-05【v7 收手】—— 用户在 v7 第三次迭代（4 字分块）上板后反馈

//     "和上一次没有什么差别"：条状花屏依旧、且越切越多。

//     三次迭代都没能消掉花屏 ⇒ 按用户定的优先级（**不花屏优先、速度不重要**），

//     回到确认干净的档：**装载期间整段禁读**（屏上是桌面米白）。

//   ★ "缩短米白"改走另一条**不碰这颗核**的路：

//     PC 端把演示素材先缩到 ~1152×864（写 497,664 字而不是 884,736 字，少 1.78 倍，

//     而且 BMP 文件更小、SD 读得也更快）。A 的 bmp_scale 那条路不要碰（上板证明会白屏）。

//   ★★★ 2026-10-05【v7 要打开它】：注意！下面 v7 的"推字只放行到消隐期"

//     （push_ok_m = vs / a_wr_full_g）是写在 **这个 ifdef 里面**的 ——

//     开关关着的时候那一支根本不编译，v7 就等于没改（上板看到的就是原来的

//     "米白 + 装载很快"）。所以 v7 必须：**开关打开** + 推字窗口 = 消隐期。

//     打开后的行为：读口不再整段禁读（旧图一直在）+

//                   写突发只在消隐期（那段时间显示不读）⇒ 既不撞也不饿。

//   ★★ 2026-10-04【又收回一次】：v6（提前 8 个字让路）上板仍然是

//      "白线扫屏 + 旧图花条纹"（写侧已经干净了：新图是好的），说明

//      **只要装载期间显示还在读，就一定会饿到显示** —— 这条路走不通。

//      ⇒ 默认回到"整段禁读"（屏上米白、图像干净）。

//      ⇒ "既要没米白、又要不花"只剩一条路：**把写限制在消隐期**（显示那段时间

//        根本不读），代价是 A 的写口一帧要停 ~16 ms —— 而 A 的 sd_read 里

//        TIME_OUT = 2 ms，所以必须先把它放大，这是 v2 白屏的老根，也是 v7 的前提。

//   ★★ 2026-10-04 【结论：默认关掉】——目标是"装载过程中不花屏"，而这一档做不到：

//      ① 突发期间让读等一等 → 上板：稀疏花屏（且花屏跟着缩放放大 ⇒ 坏的是写进 SDRAM 的图）

//      ② 整帧消隐才推字       → 上板：第一张图都出不来（A 的流式写口停 16ms 就死）

//      ③ 显示空闲窗口推字     → 上板：按 KEY3 没反应 + 花

//      ④ 只放行窗口前段       → 上板：毫无变化、依旧花

//      ⑤ 串口对账：引擎实写字数 vs A 自己推的字数 差 ~10,240 字

//      ⇒ 结论：**这颗 SDRAM 核 + 这颗原厂写引擎，容忍不了"边读边写"**。

//        只要装载期间显示还在读，写进去的图就有坏点（越切越多）。

//      ⇒ 要"不花屏"，只能：**装载期间整段禁读**（屏上是桌面米白），

//        这正好也是之前你确认能用的那档。

//      ⇒ 真想再试：取消这里注释（同时 0c 节的推字窗口也会一起生效）。

//   ★★ 2026-10-03：**默认关掉**。这一档（"装载期间继续读，只让写突发躲开显示"）

//      连着两版上板都没过：

//        v2（推字窗口=整帧消隐）→ A 写口一次停 16 ms，**第一张图都出不来**；

//        v3（推字窗口=显示没在读）→ **按 KEY3 没反应**（还没定性：可能是

//             中断在"装载没等到描述符"那一步，也可能是读写交织在别的环节上出事）。

//      ⇒ 先回到这次实验之前的、**确认能工作的**状态：

//        装载期间整段禁读（屏上米白）+ 两步直接转场（白 → 划像/淡化 → 新图）。

//      ⇒ 想再试就把这一行的注释去掉（同时第 1b/0c 节的推字窗口也会一起生效）。



`ifdef LOAD_WITH_READS

    assign aud_line_req = disp_rd_en;                   // 不再整段掐

    // ★★ v6（2026-10-04）：让路条件里加 `occ_pre`（占用快到 256 就先让）——

    //    请求是寄存的，"等突发开始再让"已经晚几拍，那几拍正是坏数据的来源。

    //    代价：每 ~330 µs 让 ~20 µs（SD 25MHz 下 16 个字），比一行 26.4 µs 还小。

    // ★★★ 2026-10-05【v7 关键修正】：这一档**不再让路**。

    //   用户上板：旧图在 ✓（读口没被整段禁读）但**白线还在扫** ✗

    //   ⇒ 那是"让路"造成的饿显示：`wr_burst|wr_guard|occ_pre` 会在装载期间

    //     反复把读口掐掉，几次连在一起就够让一行的取数跨过行尾 → 露一行底色

    //     （= 往上扫的白条）。

    //   ★ 而在 v7 里让路**本来就是多余的**：写突发已经被 `push_ok_m = vs`

    //     限制在**行场消隐期**，那段时间显示**根本不发读请求**（没有行首脉冲）

    //     ⇒ 读写天然分开，不需要再让谁让路。

    //   ⇒ 所以这里直接放行：`mem_rd_ok = 1'b1`。

    wire   mem_rd_ok  = 1'b1;                           // v7：不让路（写只在消隐期）

    wire   rd_allowed = 1'b1;                           // 给串口 flags 看

    // 这一档装载期间屏上一直是旧图 → 特效**从旧图那一端**开始划

    assign tr_from_white = 1'b0;

`else

    assign aud_line_req = disp_rd_en_g;                 // 旧行为：整段禁读（默认档）

    // ★★★★ 2026-10-06【试过并否掉 · 第二例】：曾把这里接成"每 2 拍放行 1 拍"的节流

    //   （想在"每拍一个读"上少发一半）。**上板结果：只有白屏 + 沙沙声** ——

    //   和把 `~sdr_busy` 接进来那次的症状一样。⇒ **结论：`line_buf` 的 `rd_ok` 这个口

    //   在当前的取数逻辑里【不能拿来当节流旋钮】**（一旦不是恒 1，整行就取不完）。

    //   ⇒ 已回退成恒放行。要做节流只能在【上层按块调度】做，不能在逐拍请求上做。

    wire   mem_rd_ok  = 1'b1;                           // 握手恒放行

    wire   rd_allowed = disp_rd_en_g;

    // ★★ 老档：装载期间屏上是米白（读被整段掐掉）→ 特效必须**从米白那一端**开始划。

    // ★★★ 2026-10-08【最小实验】装载期间**不再禁读**（上一条已经改掉），屏上一直是**旧图**

    //   ⇒ 特效必须**从旧图那一端**开始划（= 0），否则会先闪一下米白。

    assign tr_from_white = 1'b0;

`endif





    // ★★★ 2026-10-15【逐步减重 · 第①步】"自测图 vs 真实图"的写口二选一已拆掉，

    //   写口**固定接真实图通路**（A 的 bmp→SDRAM）。

    //   为什么等价：选择信号 `stwr_busy` 原本恒 0（自测图写入器从不上电自检），

    //   所以这 5 个三目运算符的结果**一直就是** a_wr_* 这一支。

    //   ★ 要恢复自测图档：把 `stwr_busy ? stwr_* : a_wr_*` 写回来，并恢复

    //     stub_a_writer 例化与 M2.al 条目（见上面第 1b 节的说明）。

    wire        wr_req_m  = a_wr_req;

    wire [20:0] wr_base_m = a_wr_base;

    wire [20:0] wr_len_m  = a_wr_len;

    wire [31:0] wr_data_m = a_wr_data;

    wire        wr_we_m   = a_wr_we;



    // ★ 存储本体的 App 接口（顶层例化 sdram，sdr_arb 只把信号引出来）

    wire        sdr_wr_en;

    wire [20:0] sdr_wr_addr;

    wire [3:0]  sdr_wr_dm;

    wire [31:0] sdr_wr_din;

    wire        sdr_rd_en;

    wire [20:0] sdr_rd_addr;



    // ★★★ 2026-10-04：**读写同拍**的"红线指示灯"（sticky）

    //   这颗 SDRAM 核只要在同一拍既收到读请求又收到写请求，就会坏数据。

    //   这里在显存域盯着 `App_rd_en & App_wr_en`：**一旦撞上就永久置 1**

    //   （软复位/重新下载才清），再同步到控制域放进串口 `flags` 的 bit14。

    //   ⇒ 判据：只要 flags bit14 = 1，就一定能解释"写进去的数据坏"；

    //     而 bit14 一直 0，坏数据就别赖读写了，得去查引擎/A 侧。

    // ★★ 2026-10-04：这三个都做成【寄存器】—— TD 的调试插入只保证寄存器能被抓

    //    （组合线网经常被优化掉，用户实测"列表里只有 clash_lat、没有 clash_now"）。

    //    app_rd_en_q / app_wr_en_q 是"核实际看到的读写请求"打一拍（两者同拍）

    //    ⇒ 触发用 app_wr_en_q（一定会停）就能顺便看 app_rd_en_q 有没有同时为 1。

    //    clash_q 就是"同拍撞上"的直接标志，clash_lat 是它的 sticky 版。

    reg app_rd_en_q, app_wr_en_q, clash_q, clash_lat;

    // ---- ★★ 写侧镜像（2026-10-04）：厂商模块（frame_fifo_write）内部的 reg

    //     在综合时会被重编码/改名，ChipWatcher 抓不到（用户实测 u_arb/u_wr/state

    //     找不到）。所以**不要在别人的模块里抓**，改成在顶层用我自己的寄存器

    //     把要看的量镜像出来 —— 而且全部喂进串口字段 25..28，

    //     有真实负载 ⇒ 一定不会被优化掉。

    //   ★★ 位宽**刚好用满**：TD 只保留"被用到的位"，位宽留大了会被剪掉高位、

    //      甚至改名 → watcher 列表里就找不到那个名字（用户踩过两次）。

    // ★★★ 2026-10-18【删掉三个没人读的计数器】wr_beats / wr_bursts / clash_cyc

    //   （+ 只给 wr_bursts 做上升沿的 app_wr_en_qq，共 48 位寄存器 + 3 个 16 位加法器）

    //   它们的串口格位早被借走（字段 25/26 常量 0、27 给了 sel_aud），**没有任何消费者**，

    //   留着只是白占面积。交接文档 §⑥ ③ 一直挂在待办里，这次因为"布线打不上"

    //   （`PHY-8023`，96% slices 太满）顺手删掉腾地方。

    //   ★ `app_wr_en_q` 保留：它还有真实负载（`clash_lat` 的表达式里）。

    always @(posedge clk_sdr or negedge rst_n) begin

        if (!rst_n) begin

            app_rd_en_q <= 1'b0; app_wr_en_q <= 1'b0;

            clash_q <= 1'b0;     clash_lat   <= 1'b0;

        end

        else begin

            app_rd_en_q <= sdr_rd_en;

            app_wr_en_q <= sdr_wr_en;

            clash_q     <= sdr_rd_en & sdr_wr_en;   // ← 读写同拍（寄存一拍）

            // ★★ 2026-10-04：`clash_lat` 里**同时**或上 app_rd_en_q & app_wr_en_q ——

            //   语义完全一样（同拍撞上，或它晚一拍的版本），但这样一来

            //   `app_rd_en_q` / `app_wr_en_q` 就有了**真实的负载**，

            //   TD 不会再把它们当成"没人用的寄存器"剪掉

            //   （用户实测 `clash_lat` 在、`app_wr_en_q` 不在，就是被剪了）。

            //   ★ 以后凡是要给 ChipWatcher 抓的寄存器，都必须挂一个真实负载。

            clash_lat   <= clash_lat | clash_q | (app_rd_en_q & app_wr_en_q);

        end

    end

    reg cl1, cl2;

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin cl1 <= 1'b0; cl2 <= 1'b0; end

        else        begin cl1 <= clash_lat; cl2 <= cl1; end

    end



    // ★★ 2026-10-04：**occ 高位指示**（1 位，串口 flags bit14）

    //   `u_arb/occ` 是我们自己估的 FIFO 占用，写引擎的开工条件

    //   `into_burst = (rdusedw > BURST_SIZE=256)` 就看它。

    //   多位总线在 ChipWatcher 的 CSV 里导不准（实测 wr_beats 这种只加不减的计数器

    //   都在乱跳），所以这里压成 **1 位**：occ ≥ 512 就是"引擎认为满"。

    //   ★ 判据：**空闲时如果这一位一直是 1 ⇒ 引擎会永远突发、永远和显示抢读**。

    reg occ_hi_m;                                  // 显存域采样

    always @(posedge clk_sdr or negedge rst_n) begin

        if (!rst_n) occ_hi_m <= 1'b0;

        else        occ_hi_m <= occ_hi_w;

    end

    reg oh1, oh2;

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin oh1 <= 1'b0; oh2 <= 1'b0; end

        else        begin oh1 <= occ_hi_m; oh2 <= oh1; end

    end



    // ★★★ 2026-10-08【最小实验】读写两边的忙标志（互相接起来 = 恢复原厂仲裁）

    //   ★ 声明必须放在下面两个例化之前（这个工程踩过五次"先用后声明"）

    wire        rd_busy_w;                 // 读通路：读突发进行中（vendor_rd_path.o_rd_busy）

    wire        wr_busy_w;                 // 写引擎：突发中/马上突发（sdr_arb.o_wr_busy）



    sdr_arb u_arb (

        .clk_ctl(clk), .rst_ctl_n(sys_rst_n),

        .a_wr_req(wr_req_m), .a_wr_base(wr_base_m), .a_wr_len(wr_len_m),

        .a_wr_ack(a_wr_ack),

        .a_wr_data(wr_data_m), .a_wr_we(wr_we_m),

        .a_wr_full(a_wr_full), .a_wr_done(a_wr_done), .sdr_ready(sdr_ready),

        .clk_mem(clk_sdr), .clk_mem_180(clk_sdr180), .rst_mem_n(sys_rst_n),

        .disp_rd_en(st_rd_en_m), .disp_rd_addr(st_rd_addr_m),

        .o_wr_burst(wr_burst), .o_wr_guard(wr_guard),

        .o_occ_hi(occ_hi_w), .o_occ_pre(occ_pre_w),

        .o_wr_cnt(sdr_wr_cnt),

        // ★★★ 2026-10-08 最小实验：把原厂的读写仲裁接上（见《B轨待改清单》§22）

        .rd_busy(rd_busy_w),            // ← 读通路：读突发进行中

        .o_wr_busy(wr_busy_w),          // → 读通路：写侧忙（突发中/马上突发）

        // ★ 存储本体挪到顶层了：App 接口引出去，顶层接 sdram

        .App_wr_en(sdr_wr_en), .App_wr_addr(sdr_wr_addr),

        .App_wr_dm(sdr_wr_dm), .App_wr_din(sdr_wr_din),

        // ★★★ 2026-10-06：**读口不再由 sdr_arb 驱动**（交给下面的 vendor_rd_path）

        .App_rd_en(), .App_rd_addr(),

        .Sdr_init_done(sdr_init_done), .Sdr_init_ref_vld(sdr_init_ref_vld),

        .Sdr_busy(sdr_busy)

    );



    // ============================================================

    //  3b. ★★★ 2026-10-06：**官方读通路**（块级）—— 显示的行取数走这里

    //      · vendor_rd_path = frame_fifo_read + 读 FIFO（把 wrusedw 引出来）

    //      · blk_rd_arb     = 块级仲裁（显示优先；音频口留着，现在音频关着）

    //      · 读口 sdr_rd_en/sdr_rd_addr 由 vendor_rd_path 驱动（sdram 那两行不用改）

    //      · 读写互斥仍靠 disp_rd_gate（装载期间不许发块请求）

    // ============================================================

    wire        vrd_ack, vrd_fin, vrd_used_nz, vrd_busy, vrd_valid;

    wire [31:0] vrd_dout;

    wire [9:0]  vrd_used;                  // ★ 探针：FIFO 现在几个字

    wire [15:0] vrd_rd_en_cnt;             // ★ 探针①：官方控制器发过多少次 App_rd_en

    wire        vrd_fifo_seen;             // ★ 探针②：FIFO 曾经非空过吗

    wire [15:0] blk_fin_cnt;               // ★ 探针③：仲裁器服务完几个块

    wire [15:0] blk_aud_cnt;               // ★ 探针：其中几块是音频

    wire        blk_timeout;               // ★ 探针：仲裁器看门狗掐断过（sticky）

    wire        blk_d_gnt;

    wire        dbg_want_seen, dbg_lock_seen;   // ★ 探针 bit6/bit7（o_want 到过 / 锁拿到过）

    // ★ 2026-10-08：o_dv 由 2 位扩到 3 位 —— bit0 = 显示 / bit1 = 音频 / bit2 = 字幕

    wire [2:0]  o_blk_dv;

    // ---- ★★★ 2026-10-08 字幕的块级读口（top ↔ blk_rd_arb 的第三个客户）----

    //   ★ 这一组**不过**"装载期间禁读"闸门：字幕只在图装完之后才去读，

    //     那时闸门早就是 1 了；而过了闸门反而会在闸门为 0 时把 req 掩掉、

    //     让 subtitle_ovl 的取数 FSM 卡在"等授权"上（得不偿失）。

    wire        sub_blk_req;

    wire [20:0] sub_blk_base, sub_blk_len;

    wire        sub_blk_gnt, sub_blk_next, sub_blk_fin;

    wire [31:0] sub_blk_data;

    wire [15:0] sub_row_cnt;

    wire        sub_hit;

    wire [15:0] sub_sum16;           // ★ 指纹：片上字幕 RAM 求和低 16

    wire [10:0] sub_nz;              // ★ 指纹：第一个非零字下标

    wire        sub_nz_v;

    // ★★★ 2026-10-17【资源分配优化】：`sub_dump_idx` / `sub_dump_word`

    //   （2026-10-11 的"字幕 RAM 逐字倒出"调试线）连同 subtitle_ovl 的探针口一起删除，

    //   串口字段 21/22/25 改送常量 0（见 dbg_report 例化处）。字段 19/20（指纹）保留。

    wire [31:0] blk_d_data;



    vendor_rd_path u_vrd (

        .clk_mem          (clk_sdr),

        .rst_mem_n        (sys_rst_n),

        .sdr_init_done    (sdr_init_done),

        .sdr_init_ref_vld (sdr_init_ref_vld),

        .sdr_busy         (sdr_busy),

        .wr_busy          (wr_busy_w),      // ★ 原厂互锁：写侧忙 ⇒ 读不发突发

        // 读口（独占 SDRAM）

        .App_rd_en        (sdr_rd_en),

        .App_rd_addr      (sdr_rd_addr),

        .Sdr_rd_en        (rd_vld),

        .Sdr_rd_dout      (rd_data),

        // 块请求

        .rd_req           (blk_rd_req),

        .rd_ack           (vrd_ack),

        .rd_fin           (vrd_fin),

        .rd_base          (blk_rd_base),

        .rd_len           (blk_rd_len),

        // 取数

        .rd_re            (blk_rd_re),

        .rd_dout          (vrd_dout),

        .rd_valid         (vrd_valid),

        .rd_used          (vrd_used),

        .rd_used_nz       (vrd_used_nz),

        .o_rd_busy        (vrd_busy),

        .o_rd_en_cnt      (vrd_rd_en_cnt),

        .o_fifo_seen      (vrd_fifo_seen)

    );

    assign rd_busy_w = vrd_busy;            // 给写引擎看（同一根线上游）



    blk_rd_arb u_blk (

        .clk_mem        (clk_sdr), .rst_mem_n(sys_rst_n),

        // 官方读侧

        .rd_req         (blk_rd_req), .rd_ack(vrd_ack), .rd_fin(vrd_fin),

        .rd_base        (blk_rd_base), .rd_len(blk_rd_len),

        .rd_en          (blk_rd_re), .rd_data(vrd_dout),

        .rd_used_nz     (vrd_used_nz),

        // ★★★ 2026-10-11：交付认官方 FIFO 的 valid（见 blk_rd_arb 文件头）

        .rd_dv          (vrd_valid),

        // ★★ 2026-10-09：短块收尾要用"官方还忙不忙"来判（漏掉一拍宽的 read_finish 时

        //   不再死等到看门狗 —— 那一下会把显示/音频的读口卡 65 µs）

        .rd_busy        (rd_busy_w),

        // 显示口（接到 disp_top 的 blk_*）

        .d_req          (d_blk_req), .d_base(d_blk_base), .d_len(d_blk_len),

        .d_gnt          (blk_d_gnt), .d_next(d_blk_want),

        .d_data         (blk_d_data), .o_dv(o_blk_dv), .d_done(),

        // 音频口：★ 2026-10-06 起接到 top_aud 的块级音频读客户端

        .a_req          (aud_a_req_g), .a_base(aud_a_base), .a_len(aud_a_len),

        .a_gnt          (aud_a_gnt), .a_next(aud_a_next), .a_data(blk_a_data), .a_done(),

        // ★ 字幕口（2026-10-08）：一次一行的 25 字短块，优先级排在最后

        .s_req          (sub_blk_req), .s_base(sub_blk_base), .s_len(sub_blk_len),

        .s_gnt          (sub_blk_gnt), .s_next(sub_blk_next),

        .s_data         (sub_blk_data), .s_done(sub_blk_fin),

        .o_blk_cnt      (blk_fin_cnt), .o_aud_blk_cnt(blk_aud_cnt),

        .o_sub_blk_cnt  (),

        .o_timeout      (blk_timeout)

    );



    // ============================================================

    //  ★★★ 2026-10-06 诊断：读通路【整条链】的 sticky 位图（串口字段 30）

    //   上一版探针已证明"官方控制器一次 App_rd_en 都没发"。那到底卡在链的哪一环？

    //   这一位图一次就能看出来（每一位一旦置起就保持，直到复位）：

    //     bit0 = 行缓冲的原始块请求 blk_req 出现过

    //     bit1 = 过了"装载期间禁读"闸门、仲裁器看到的 d_req 出现过

    //     bit2 = blk_rd_arb 受理并授权过（read_req_ack 回来过）

    //     bit3 = blk_rd_arb 把请求转发给官方控制器（rd_req）过

    //     bit4 = 官方控制器受理（read_req_ack）过

    //     bit5 = 官方控制器真的发过 App_rd_en（= 驱动 SDRAM 的读使能，就是 sdr_rd_en）

    //   ★ 判读：从 bit0 往上看，**第一个还是 0 的那一位就是断点**。

    //  ★★★ 2026-10-08【最小实验】再加两位，专看"原厂读写仲裁到底有没有生效"：

    //     bit8 = 读忙(O_rd_busy) 和 写忙(O_wr_busy) **同拍都高**过（sticky）

    //            两者本来就该互斥，同拍高说明互锁没拦住 ⇒ 会看到读写命令撞车

    //     bit9 = 显示读请求**被推迟超过 200 拍**过（sticky；200 拍 ≈ 1.6 µs）

    //            有它 = 写突发确实把显示挡住过（配合字段 29 看挡得最久多少拍）

    // ============================================================

    // ★★★ 2026-10-17【面积优化·低风险】读通路 sticky 位图 + 读推迟计数整块删除

    //  ------------------------------------------------------------

    //  这里原来有 26 个触发器 + 两个 always：

    //    ① `dbg_chain[15:0]` —— 读通路各环节"到过没有"的 sticky 位图（串口字段 30）；

    //    ② `rd_defer_cnt/rd_defer_max` —— 显示读请求被写突发挡住的**最长拍数**（字段 29）。

    //  两者**只喂遥测**（没有任何逻辑消费它们），而判读早就不靠它们了：

    //    · "读口活着没有"看字段 15/16（行缓冲读地址在动）；

    //    · "读写撞车没有"看字段 12 的 bit1（`aud_blk_stall` sticky）。

    //  ⇒ 整块删除，字段 29/30 接常数 0（**帧格式不变**）。

    //  回退：把这两段加回来即可（`d_blk_req_raw/…/dbg_lock_seen` 这些信号都还在）。



    // ============================================================

    //  3a. 存储本体：★ 例化在【顶层】（和官方例程 / M0 一样）

    //      原来它套在 sdr_arb 里面（u_arb/u_sdram/sdram），现在挪出来。

    // ============================================================

`ifdef SIM_SDRAM

    fake_sdram u_sdram (

`else

    sdram u_sdram (

`endif

        .Clk              (clk_sdr),

        .Clk_sft          (clk_sdr180),      // ★ 必须接 180° 那一相

        .Rst              (~sys_rst_n),

        .Sdr_init_done    (sdr_init_done),

        .Sdr_init_ref_vld (sdr_init_ref_vld),

        .Sdr_busy         (sdr_busy),

        .App_wr_en        (sdr_wr_en),

        .App_wr_addr      (sdr_wr_addr),

        .App_wr_dm        (sdr_wr_dm),

        .App_wr_din       (sdr_wr_din),

        .App_rd_en        (sdr_rd_en),

        .App_rd_addr      (sdr_rd_addr),

        .Sdr_rd_en        (rd_vld),

        .Sdr_rd_dout      (rd_data)

    );



    // ============================================================

    //  ★★ 2026-09-28：抓【SDRAM 写口上前 4 个字】= 图像左上角前 4 个像素。

    //     和电脑上那张原图的同位置逐点对比：

    //       一致  → 卡/存储都对，问题在显示侧

    //       不一致→ A 的取数/打包错了（能看出是偏移、上下翻、还是每两个像素互换）

    //     ★ 覆盖写：留下的就是【最后一次】写进去的值（= A 的真图，

    //       而不是开机那张自测图）。

    // ============================================================

    // ★★ 2026-09-28 改法（上一版"当地址=0 时抓"在加补偿后永远不触发，读到一堆 0）：

    //   改成抓【最后 4 笔写的地址】+ 最新那一笔的数据 ——

    //   这样能直接看出 A 的那一串写到哪个地址区间去了（落在哪、结束在哪）。

    // ★★ 2026-09-28 第二轮：写口落点已经查清（举多少落多少），这 8 个字段

    //    改抓【第 200 行、x = 0/2/4/.../14 这 8 个“屏上真实像素”】——

    //    用来定位"每隔几列有一小条右移"的横向问题。

    // ★★ 2026-09-28 第三轮：原来采的是【屏幕第 200 行、窗口列 0..14】，

    //    但那一行在原图里正好是一大片纯色（窗口列 0..14 全一样），

    //    有错位也看不出来。改成采原图【第 241 行】（它对 2 像素的横移

    //    8 个采样点全都会变），并且分两处采：

    //      左端：窗口列 0/2/4/6     （屏幕 x = 80/82/84/86）

    //      中段：窗口列 300/302/304/306（屏幕 x = 380/382/384/386）

    //    行映射：屏幕第 y 行 = 原图第 (y-60) 行（窗口左上角在 80,60）

    //            → 采原图第 241 行就是采【屏幕第 301 行】。

    //    原图第 241 行的标准答案（从卡里那张 BMP 用脚本算出来的）：

    //      左端 0/2/4/6     = 29D1 21D1 21F1 2211

    //      中段 300/302/304/306 = 2127 2969 20E7 18C6

    //    右移 2 像素会变成 21D1 21F1 2211 2231 / 2969 20E7 18C6 5AAD，

    //    所以只要错位，这 8 个数立刻就对不上。

    // ★★ 2026-09-28 第四轮（★ 整行扫描探针）：把"固定 8 个点"升级成

    //    "每帧换一组、40 帧把一整行 320 个字全读回来"。

    //    为什么：固定 8 个点只能看到 8 个字，错位的【形态】（从第几个字开始歪、

    //    是重复、跳字还是整段平移）看不全 —— 这次要一次量到底。

    //

    //    原理：窗口是 x = 80..719（640 宽），屏幕列 80+2k 对应行内第 k 个字。

    //          第 i 帧取 k = 8i .. 8i+7（屏幕列 80+16i .. 80+16i+14），

    //          i 从 0 走到 39 就把 k = 0..319 全部覆盖一遍。

    //          探针是在【屏幕第 301 行】取的（= 窗口第 241 行 = 源图第 241 行），

    //          和串口里 lb_* 那组数采的是同一行的搬运结果。

    //    判读：自测图 PAT_MODE=2 里"字的值 = 它的字地址"，所以第 k 个字正确的

    //          时候，读回来的低 16 位应当 = 0x2980 + k（本行行首 = 238*320）。

    //    ★ 组号用 vs 的上升沿推进（frame_start_w 在本文件里声明得比较晚，

    //      这里用不了；vs_w 是提前声明过的）。

    //    ★ 每 4 帧才换一组：串口一条帧 200ms ≈ 12 帧，若每帧都换，组号

    //      每次刚好跳 12（mod 40），永远只能看到 1/4 的组；改成 4 帧换一组

    //      后每次跳 3（3 与 40 互质）→ 40 条帧就能把整行 320 个字走一遍。

    // ★★★ 2026-09-28 第六轮（★ 边缘巡检）：上面那版只抽【偶数像素】（字的"高半字"），

    //     奇数像素从来没看过，上/下边缘那两行也没抽 —— 而用户看到的问题正好是

    //     "四条边缘各差 1 个像素"。这一版一次下载把这几处全覆盖：

    //       每一趟(pass)固定"看窗口哪一行 + 取偶数还是奇数像素"，在这一行上扫 40 组。

    //         pass 0: 窗口第   0 行（图的【上边缘】）  偶数列

    //         pass 1: 窗口第   0 行                    奇数列

    //         pass 2: 窗口第   1 行                    偶数列

    //         pass 3: 窗口第 479 行（图的【下边缘】）  偶数列

    //         pass 4: 窗口第 479 行                    奇数列

    //         pass 5: 窗口第 241 行（已用偶数验过的那行）奇数列 ← 补上盲区

    //       每组 8 个采样点 = 16 个像素（间隔 2）：屏幕列 80+16i+2j+half。

    //     ★ 组号每 4 帧走一格（40 格 ≈ 8 秒走完一趟），走完一趟换 pass（共 6 趟 ≈ 48 秒）。

    //    ★ 第七轮改成【列巡边】：每一趟查"左边缘 16 列"或"右边缘 16 列"的

    //      偶数/奇数像素，组号 g 决定查哪一行（第 0 行 + 每 12 行一行，共 40 行）：

    //         pass 0: 窗口列 0..15 的偶数像素    pass 1: 同左，奇数像素

    //         pass 2: 窗口列 624..639 的偶数像素 pass 3: 同右，奇数像素

    //      （每组的 8 个采样点 = 该行端点上的 8 个像素，间隔 2。）

    //    ★ 第十轮【只盯最左一列、逐行铺开】：pass 只区分"取偶数像素(列0)/奇数像素(列1)"，

    //      组号 g 决定从第 8g 行开始，连续看 8 行 → 40 组铺满第 0..319 行。

    //      这样一次抓取就能看出"每 3 行一个字错"这条周期（上一版一次只抽到 12 处）。

    // ============================================================

    //  ★★★ 2026-10-17【删死探针】（原 1773~1822 行整段删除）

    //  ------------------------------------------------------------

    //  这里原来是一整套"最左一列逐行扫描"探针：

    //      pass_i / dump_i / dump_div / vs_d（计数器）

    //      px0..px7 + px_grp（128+ 个触发器，按 dbg_x/dbg_y 采 8 个点）

    //  它唯一的消费者是 `dbg_report` 的字段 6~9（经 `reppar` 隔帧交替）。

    //  ★ 为什么删：上一轮"面积优化"的注释里写着"转场探针已删 ⇒ 字段 6~9 恒 0"，

    //    但**实际没删干净** —— `.row4(px0)..row7(px3)` 还接着，只是采样列正好落在

    //    窗口左边缘（当前图/缩放恰好全黑）才读到 0000，属于"注释说谎 + 白占面积"。

    //  ★ 现在字段 6~9 真的接常数 0（见下面 dbg_report 例化处的 `.row0`~`.row7`），

    //    整套探针寄存器/计数器一并删掉 ⇒ 省 128+ FF 与若干 12 位比较器。

    //  ★ 要恢复（查"每 3 行一个字错"那种周期性问题）时：

    //      git show <旧 commit>:rtl/top_m2.v 搜 pass_i，把 1773~1822 原样贴回来，

    //      并把 dbg_report 的 `.row0..row7` 改回 `.row4(px0)..row7(px3)`。

    // ============================================================



    // ============================================================

    //  3b. 【已删除】读口自测的"自测图写完后 50ms 触发"延时器

    //      （2026-10-15 逐步减重·第①步）—— 它等的是 `stwr_done`（自测图写入器），

    //      而写入器在上板配置里从不上电自检（stwr_fired 复位即 1）⇒ 这段从来没跑过；

    //      它唯一的消费者 `st_go` 也早在 2026-10-09 读口自检被删后就死了。

    //      下面 1473 行起就是那次"删读口自检"的原文说明。

    // ============================================================



    // ======================================================================

    //  ★★★ 2026-10-09【集成临时改动 · 省面积】**删掉读口自检 u_selftest**

    //    （`vendor_read_test` + 它内部的 `frame_read_write` 两颗 FIFO，共 ~285 LUT）

    //  · 它从 **2026-09-28** 起就**没有任何作用**了：读口当时已经"完全交给显示"，

    //    顶层把它的输出打桩成 0（`st_rd_en_m/st_rd_addr_m` = 0，见上面那一行），

    //    `st_go` 拉高也读不到任何东西 —— 属于纯挂着的死逻辑。

    //  · 它的 8 个输出里，只有 `st_bad` 还进串口（另外几格早被写侧镜像/转场探针占掉了）。

    //    ⇒ 这里把 `st_bad` 直接接 0（`st_bad`/`st_first` 那两格在转场探针模式下本来就不看）。

    //  ★ 要恢复：把这段例化放回来、并把下面那行 assign 删掉。

    //    例化原文在 git 历史里（`git show 651aa6a:rtl/top_m2.v`，搜 vendor_read_test）。

    // ======================================================================

    assign st_bad  = 16'd0;

    assign st_busy = 1'b0;      // 串口 flags 的 bit12 用它（自检都没了，恒 0）



    // ============================================================

    //  4. 描述符接收侧（A 写 → B 每帧读）

    //     ★ 第一遍上板它只是"接上、正常工作"，但显示参数不从它取

    // ============================================================

    wire [2-1:0] desc_valid;

    wire [2*21-1:0] desc_base;

    wire [2*12-1:0] desc_src_w, desc_src_h;

    wire [2*2-1:0]  desc_format;

    wire [2-1:0]    desc_transposed;

    wire [2*8-1:0]  desc_img_no;

    wire [15:0]     desc_version;

    wire            desc_pending;



    wire            frame_start_w;

    wire [15:0]     frame_id_w;



    desc_rx #(.SLOT_NUM(2)) u_desc (

        .clk_ctl(clk), .rst_ctl_n(sys_rst_n),

        .a_desc(a_desc), .a_commit_tgl(a_commit_tgl), .a_ack_tgl(a_ack_tgl),

        .clk_pix(clk_pix), .rst_pix_n(disp_rst_n), .frame_start(frame_start_w),

        .o_valid(desc_valid), .o_base(desc_base),

        .o_src_w(desc_src_w), .o_src_h(desc_src_h),

        .o_format(desc_format), .o_transposed(desc_transposed),

        .o_img_no(desc_img_no),

        .o_version(desc_version), .o_pending(desc_pending)

    );



    // ============================================================

    //  5. 显示链

    // ============================================================

    wire        win_on;

    wire [11:0] win_x0, win_y0, win_w, win_h;



    // ★★ 2026-10-02：窗口改成【铺满全屏 800x600】，用来显示 800x600 的图。

    //   配套把上面的 `define USE_DESC 打开 —— 源图尺寸从 A 的描述符里读，

    //   这样 800x600 铺满整屏、640x480 就摆在左上角（右边/下边留底色），

    //   换图不用改代码。（B 的 win_sample 自带"窗口比源图宽/高"两个兜底）

    stub_win_table #(

        .WIN_X0(0), .WIN_Y0(0), .WIN_W(1024), .WIN_H(768)

    ) u_win (

        .win_x0(win_x0), .win_y0(win_y0),

        .win_w(win_w), .win_h(win_h), .win_on(win_on)

    );



`ifdef USE_DESC

    // ---- 显示参数来自 A 的描述符 ----

    // ★★★ 2026-10-03（转场）：从"挑最新的那一张"改成【前台 / 后台两路一起给】。

    //   · front_sel = 0 → 槽 0 当前台（合成器的 A 路）、槽 1 当后台（B 路）；

    //                  = 1 → 反过来。

    //   · 转场走完 transition_ctrl 会给一拍 swap，这里就把前台/后台对调。

    //     ★ 对调那一拍屏上正好"精确等于新图"，所以一点跳变都看不见。

    //   · A 往【非前台】那个槽写（见下面 a_slot_use）—— 于是"前台正在显示的那份"

    //     永远不会被覆盖；这就是原来 ⑤ 想用 slot_free 保证的事，结构上就成立了。

    wire        src_valid = desc_valid[front_sel];

    wire [20:0] src_base  = front_sel ? desc_base[41:21]  : desc_base[20:0];

    wire [11:0] src_w     = front_sel ? desc_src_w[23:12] : desc_src_w[11:0];

    wire [11:0] src_h     = front_sel ? desc_src_h[23:12] : desc_src_h[11:0];



    // 后台那一路（同一个槽，只是取反）

    wire        src_b_valid = desc_valid[~front_sel];

    wire [20:0] src_b_base  = front_sel ? desc_base[20:0]  : desc_base[41:21];

    wire [11:0] src_b_w     = front_sel ? desc_src_w[11:0] : desc_src_w[23:12];

    wire [11:0] src_b_h     = front_sel ? desc_src_h[11:0] : desc_src_h[23:12];

`else

    // ---- 先写死：大槽 0、640x480（第一遍上板，变量最少）----

    //   ★★ 这两个数【必须和卡里那张图的实际尺寸一致】★

    //      卡里是 640x480 的图 → 就写 640 / 480。

    //      写错的话行距（每行多少个字）就和 A 写进去的对不上，屏上是花屏。

    //      （打开 USE_DESC 之后就不用管了：尺寸从描述符里读，见上面那段）

    wire        src_valid = 1'b1;

    wire [20:0] src_base  = 21'd0;

    wire [11:0] src_w     = 12'd640;

    wire [11:0] src_h     = 12'd480;

    // 第二路：关掉（常数传播，整块逻辑不综合）

    wire        src_b_valid = 1'b0;

    wire [20:0] src_b_base  = 21'd0;

    wire [11:0] src_b_w     = 12'd640;

    wire [11:0] src_b_h     = 12'd480;

`endif



    // ============================================================

    //  5b. 缩放档位 → step + 居中偏移（★ M2 新增）

    //     level 0 = 适配（整张图缩进窗口、居中）；1..5 = 1x/1.5x/2x/3x/4x

    //     "适配"那一次除法在这里算（udiv_q16_up，换档/换图才跑一次）

    // ============================================================

    // ★★★ 2026-10-03 ★ 缩放几何：前台/后台**各一套** ★（见台账 §十五 / §十六）

    //   为什么要两套：直接划像/叠化时**两张图同时在屏上**，而它们的适配缩放

    //   不一样。共用一套的话，进来的那张会被拿出去的 step/off 取样 ——

    //   就是上板抓到的"只露左上角、收尾才闪回正位"（§十五）。

    //   ★ 资源：zoom_dual 里只留**一套**算术（除法 + 两处乘法），

    //     输入按相位轮流喂两个槽的尺寸、输出分两个寄存器组锁住 ——

    //     比"例化两个 zoom_sel"省 4 个 DSP（预算只剩 3 个）。

    wire [31:0] z_a_step, z_a_offu, z_a_offv;

    wire [31:0] z_b_step, z_b_offu, z_b_offv;



    zoom_dual u_zoom (

        .clk_pix(clk_pix), .rst_pix_n(disp_rst_n),

        .level(zoom_p2),

        .a_w(src_w),   .a_h(src_h),

        .b_w(src_b_w), .b_h(src_b_h),

        .win_w(win_w), .win_h(win_h),

        .a_step(z_a_step), .a_off_u(z_a_offu), .a_off_v(z_a_offv),

        .b_step(z_b_step), .b_off_u(z_b_offu), .b_off_v(z_b_offv),

        .busy()

    );



    wire        hdmi_locked;



    // ============================================================

    //  ★★★ 2026-10-03 转场探针（"装载期间继续读"那一档卡住时用来定位）

    //  一条链是：KEY3 → 请求 → A 起装 → 描述符生效 → 转场 → 对调前台。

    //  这四组数（塞进串口字段 6/7/8/9）能一眼看出断在哪一节：

    //     6 = {KEY3 次数, 请求次数}      键有没有被看到 / 请求有没有发出去

    //     7 = {a_start 次数, a_wr_ack 次数}   A 有没有被放行去写

    //     8 = {描述符版本变化次数, a_wr_done 次数}  装载有没有真的完成

    //     9 = {swap 次数, 状态位}         转场有没有走完

    //  ★ 计数在一个域里做、用"翻一次"的位过域（脉冲直接跨域会漏）。

    // ============================================================

    // ① 像素域：把两个"事件"变成翻转位（翻一次永远不会漏）

    reg        ver_tgl, ver_d;

    reg        swap_tgl;

    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin

            ver_tgl <= 1'b0; ver_d <= 16'd0; swap_tgl <= 1'b0;

        end

        else begin

            ver_d <= desc_version;

            if (desc_version != ver_d) ver_tgl  <= ~ver_tgl;   // 描述符生效一次

            if (tr_swap)               swap_tgl <= ~swap_tgl;  // 转场走完一次

        end

    end

    // ★★★ 2026-10-17【面积优化·低风险】转场探针整块删除

    //  ------------------------------------------------------------

    //  这里原来有三样东西：① 三组翻转位同步器（ver/swap/req 各 3 级）；

    //  ② 七个 8 位计数器（KEY2 次数 / 请求 / a_start / a_wr_ack / 版本变化 /

    //     转场完成 / a_wr_done）；③ 四个拼好的 16 位探针字 tr_p0..p3

    //     —— 它们唯一的下家就是串口字段 6~9。

    //  实测 ≈ 120 LUT，且**只服务遥测**：转场早就调好了，判读也不再依赖它们。

    //  ⇒ 整块删除，字段 6~9 改为常数 0（**帧格式 33 字段不变**，读串口的脚本照旧）。

    //  ★ 唯一的同步量 `ver_tgl`/`swap_tgl` 仍然保留 —— 它们在别处被用作事件。

    //  回退：把这段加回来即可（注释里保留了口径：边沿 = 两级同步后异或）。

    // ------------------------------------------------------------



    // ★★ 2026-09-28：写和读绝不能同时进行，但"只禁读"会把行缓冲饿死

    //    （实测：禁读一段时间后 disp_rd_en 永远是 0、行缓冲再也发不出请求，

    //      屏上只剩底色）。所以改成：**只要有写在跑，就把显示整块复位**，

    //    写完再从干净状态开始 —— 这时图已经在 DRAM 里，一次就读对。

    // ★★★ 2026-10-21【D2 · B2】兜底页状态（产生逻辑在本文件后面 load_done_latch 之后）

    wire        fs_on_w;

    wire [1:0]  fs_state_w;

    wire [1:0]  fs_hint_w;      // ★ D3 · C2/C3：{音频格式坏, 图像格式坏}



    // ★★★ 2026-10-25【不黑屏 · 切换白闪】整屏白门控（产生逻辑在文件末尾 MBOOT 段）
    wire wb_white;

    disp_top u_disp (

        .clk_pix(clk_pix), .clk_par(clk_par), .clk_ser(clk_ser),

        .rst_pix_n(disp_rst_n),

        .src_valid(src_valid), .src_base(src_base),

        .src_w(src_w), .src_h(src_h),

        // ★★ 2026-10-03（转场）：第二路 = 后台那个槽 + 转场三级

        .src_b_valid(src_b_valid), .src_b_base(src_b_base),

        .src_b_w(src_b_w), .src_b_h(src_b_h),

        // ★ 后台那一路自己的缩放几何（前台的在下面 step_q16/off_*）

        .step_b_q16(z_b_step), .off_ub_q16(z_b_offu), .off_vb_q16(z_b_offv),

        .tr_req(tr_req), .tr_fx(tr_fx), .tr_ver(desc_version),

        .tr_from_white(tr_from_white),

        // ★★★ 2026-10-08【预装】：后台槽已就绪 ⇒ 按键时转场走快速路（跳过 LOAD）

        .tr_back_ready(tr_back_ready),

        .tr_may_load(tr_may_load), .tr_active(tr_active), .tr_swap(tr_swap),

        .tr_show_back(tr_show_back),

        // ★★★ 2026-10-08【字幕叠加】：先给暂定位置；以后换成 C 的 WIN_SUB 那一行

        .sub_on(sub_on_s2),          // ★ 50 MHz 域 → 像素域，过了两位同步器

        .sub_x0(SUB_X0_DFLT), .sub_y0(SUB_Y0_DFLT),

        .sub_w(SUB_W_DFLT), .sub_h(SUB_H_DFLT),

        // ★ 2026-10-23【双缓冲跨域】只送"常数基址 + 1 位槽号"：
        //   21 位基址直接跨 50 MHz → 125 MHz 会在换槽那一拍拼出中间值；
        //   槽号在 subtitle_ovl 里 2 级同步 + 取字起点锁存（见该模块注释）。
        .sub_base(SUB_BASE), .sub_slot(sub_rd_sel), .sub_ink(SUB_INK),

        .sub_tpat(SUB_TPAT),

        // ★★★ 2026-10-15【功能 · 开关4 → 字幕水平滚动】：sw4 已在像素域（四级同步的最后一级）

        .sub_scroll(1'b1),   // ★ 2026-10-21：SW4 改用报警触发，字幕改成常滚动

        // ★★★ 2026-10-15【参数菜单·第1步】菜单层（在 subtitle_ovl 之后、565→888 之前）

        //   ★ 传进去的是**像素域**的同步副本（上面那两级）：菜单关闭（menu_on=0）时

        //     整个菜单层被常数传播消掉 ⇒ 一个门都不多、屏上逐像素回到改前。

        .menu_on(menu_on_s2), .menu_sel(menu_sel_s2), .menu_edit(menu_edit_s2),

        // ★★★ 2026-10-15【参数菜单·第2步】菜单里要显示的活值（像素域同步副本、只读）

        //   zoom_lv ⇒ 行 0 `ZOOM` 的数值（0..5）；行 1 = 可视化开关（2026-10-24 起显示 开/关，
        //   原来这里送的是 sel_aud+1 音轨号）

        //   ★ 菜单关闭时这两根只是"没人看的电平"（menu_ovl 里被 menu_on 门掉）。

        .menu_zoom_lv(zoom_s2), .menu_sel_aud(aud_s2),

        // ★★★ 2026-10-17【音量进菜单】：行 2 `VOLUME` 的活值（0..15，像素域同步副本、只读）

        .menu_vol(vol_s2),

        // ★★★ 2026-10-17【亮度进菜单】：行 3 `BRIGHT` 的活值 0..15 + 真的压暗画面

        //   （disp_top 里插了一级 `bri_scale`；15 = 原样；菜单面板本身不压暗）

        .menu_bri(bri_s2),

        // ★★★ 2026-10-18【可视化开关进菜单】：行 4 `VISUAL` 的 ON/OFF + 真的关掉可视化层

        //   （disp_top 里用 `~menu_viz_on` 把柱形 mask 和压暗 band 一起门掉）

        .menu_viz_on(viz_s2),

        // ★★★ 2026-10-21【D2 · B1/B2 兜底页】：没卡 / 坏图 / 装载中 ⇒ 深底自检页（代替米白空屏）

        .fs_on(fs_on_w), .fs_state(fs_state_w),

        .fs_hint(fs_hint_w),

        // ★★★ 2026-10-21【D5 · S1 插播态】报警标志（像素域同步后的电平）

        .alert_on(alert_s2),

        // ★★★ 2026-10-17【音频可视化】音频域那几根（viz 只读旁听）

        .clk_aud(clk_aud), .rst_aud_n(aud_rst_n),

        .aud_viz_vld(aud_dbg_vld), .aud_viz_dout(aud_dbg_dout), .aud_viz_next(aud_dbg_next),

        .s_blk_req(sub_blk_req), .s_blk_base(sub_blk_base), .s_blk_len(sub_blk_len),

        .s_blk_gnt(sub_blk_gnt), .s_blk_next(sub_blk_next),

        .s_blk_dv(o_blk_dv[2]), .s_blk_data(sub_blk_data), .s_blk_fin(sub_blk_fin),

        .o_sub_row_cnt(sub_row_cnt), .o_sub_hit(sub_hit),

        .o_sub_sum16(sub_sum16), .o_sub_nz(sub_nz), .o_sub_nz_v(sub_nz_v),

        // ★★★ 2026-10-17【资源分配优化】：`.o_sub_dump_idx/.o_sub_dump_word`

        //   两条接线随 subtitle_ovl 的探针口一起删除（字段 21/22/25 改送 0）。

        .win_on(win_on),

        .win_x0(win_x0), .win_y0(win_y0), .win_w(win_w), .win_h(win_h),

        .step_q16(z_a_step), .off_u_q16(z_a_offu), .off_v_q16(z_a_offv),

        .clk_mem(clk_sdr), .rst_mem_n(disp_rst_n),

        // ★★★ 2026-10-06：块级读通路（原来这里是 mem_rd_en/addr）

        .blk_req(d_blk_req_raw), .blk_base(d_blk_base), .blk_len(d_blk_len),

        // ★★★ 2026-10-05：读数据不再直连 SDRAM 控制器，而是**经 top_aud 分流**

        //   （top_aud 只把"显示要的那份"给回来，音频的数据它自己收进 FIFO）

        .blk_gnt(blk_d_gnt), .blk_want(d_blk_want), .blk_dv(o_blk_dv[0]), .blk_data(blk_d_data),

        .o_dbg_want_seen(dbg_want_seen), .o_dbg_lock_seen(dbg_lock_seen),

        // ★★ 音频 6 根 → my_hdmitop（同一个像素域）

        .I_audio_valid(hdmi_audio_valid),

        .I_audio_left (hdmi_audio_left),

        .I_audio_right(hdmi_audio_right),

        .I_acr_valid  (hdmi_acr_valid),

        .I_acr_cts    (hdmi_acr_cts),

        .I_acr_n      (hdmi_acr_n),

        .HDMI_CLK_P(HDMI_CLK_P),

        .HDMI_D0_P(HDMI_D0_P), .HDMI_D1_P(HDMI_D1_P), .HDMI_D2_P(HDMI_D2_P),

        .HDMI_DDC_SCL(HDMI_DDC_SCL), .HDMI_DDC_SDA(HDMI_DDC_SDA),

        .o_video_locked(hdmi_locked),

        .o_frame_start(frame_start_w), .o_frame_id(frame_id_w),

        .o_de(de_w), .o_vs(vs_w),

        .o_dbg_x(dbg_x), .o_dbg_y(dbg_y),

        .o_rgb565(rgb565_w),

        .dbg_wbase(lb_wbase0), .dbg_fwords(lb_words0),

        .dbg_rd0(lb_rd0), .dbg_rd1(lb_rd1),

        .o_drop_cnt(lb_drop), .o_abort_cnt(lb_abort)

        ,.o_off_first(lb_off), .o_align_bad(lb_alignbad)
    ,.frame_start_o(frame_start_pix)
    ,.wb_white(wb_white)          // ★★★ 2026-10-25【不黑屏】整屏白门控（开机首图前 / 切换白闪）

    );



    // ============================================================

    //  5a-2. ★★★ 2026-10-05：A 轨音频链（top_aud）

    //    它内部收了 4 个模块：sfx_ctrl / sdr_rd_arb / sfx_player / audio_arc_calculate。

    //    在这里只做三件事：① 时钟复位；② 读口绕道（见上面第 2b 节那几行）；

    //                      ③ 音频 6 根接进 disp_top → my_hdmitop。

    //    ★ 复位：mem/pix 域都用 sys_rst_n（**不要**用 disp_rst_n ——

    //      display 在装载期间会被整段复位，那会把"静音兜底"的音频流也一起掐断）。

    // ============================================================

    top_aud #(

        .SFX_NUM    (SFX_NUM),        // ★★★ 2026-10-14 深夜【功能·开关切音频】：原来写死 2，

                                      //   现在共用文件上方那个 localparam ⇒ 条数只有【一处】定义，

                                      //   `sel_aud` 的取模循环和它永远一致（改条数只改那一行）。

        .SFX_STRIDE (SFX_STRIDE),

        .SFX_BASE   (SFX_BASE),

        .ACR_N      (6144)

    ) u_aud (

        .clk_ctl(clk),          .rst_ctl_n(sys_rst_n),

        .clk_mem(clk_sdr),      .rst_mem_n(sys_rst_n),

        .clk_aud(clk_aud),      .rst_aud_n(aud_rst_n),

        .clk_pix(clk_pix),      .rst_pix_n(sys_rst_n),



        // ---- C 轨命令（现在由顶层那个小状态机自产）----

        .play_sfx(aud_play_req), .stop_sfx(aud_stop_req),

        .sfx_id(4'd0), .volume(alert_on ? 8'hFF : vol_byte), .busy(aud_busy_w),

        .aud_words_act(aud_words_act),   // ★ 实际字数 → top_aud → sfx_ctrl



        // ---- ★★★ 2026-10-06 块级音频读口（接 blk_rd_arb 的音频口）----

        //   a_req 过和显示同一道"装载期间禁读"闸门（§6.3-1 红线）。

        .a_req     (aud_a_req),

        .a_base    (aud_a_base),

        .a_len     (aud_a_len),

        .a_gnt     (aud_a_gnt),

        .a_next    (aud_a_next),

        .a_data    (blk_a_data),

        .a_dv      (o_blk_dv[1]),

        .rd_ok     (disp_rd_gate),



        // ---- 音频 6 根 ----

        .o_audio_valid(hdmi_audio_valid),

        .o_audio_left (hdmi_audio_left),

        .o_audio_right(hdmi_audio_right),

        .o_acr_valid  (hdmi_acr_valid),

        .o_acr_cts    (hdmi_acr_cts),

        .o_acr_n      (hdmi_acr_n),



        // ---- 诊断（进串口字段 28）----

        .dbg_sfx_base (aud_dbg_base),

        .dbg_sfx_words(aud_dbg_words),

        .dbg_play_tgl (aud_dbg_play_tgl),

        .dbg_aud_vld  (aud_dbg_vld),

        .dbg_aud_dout (aud_dbg_dout),

        .dbg_aud_next (aud_dbg_next),

        .dbg_blk_stall(aud_blk_stall),

        .dbg_aud_cnt  (aud_dbg_cnt),

        .dbg_aud_sum  (aud_dbg_sum)

        // ★★★ 2026-10-17【资源分配优化】：`.dbg_aud_underrun(...)` 这一行已删

        //   （探针随 aud_blk_rd/top_aud 一起删除）。端口表少一格，

        //   **串口帧格式与字段数完全不变**（字段 26 由 dbg_report 那侧改送 0）。

    );



    // ============================================================

    // ★★★ 2026-10-24【临时调试·音量排查】音频输出数字幅度探针（串口字段 30）
    //   目的：实测"每个音量档"的音频输出平均幅度，判断 50% 档是否真的比 60% 档大。
    //   取 hdmi_audio_left[23:8]（= sfx_player 输出的 16 位采样，左右声道相同），
    //   每 8192 个采样（48 kHz ⇒ 171 ms）算一次平均绝对值（≈ RMS 的线性版），
    //   再两级同步到 50 MHz 控制域，送 dbg_report 的字段 30。
    //   ★ 调完删掉本段 + 把字段 30 还原成 sub_ft。
    wire signed [15:0] aud_mon     = hdmi_audio_left[23:8];
    wire        [16:0] aud_mon_abs = aud_mon[15] ? (~{aud_mon[15], aud_mon} + 17'd1)
                                                 : {1'b0, aud_mon};
    reg  [28:0] aud_sum;
    reg  [12:0] aud_win_cnt;
    reg  [16:0] aud_avg_out;
    always @(posedge clk_pix or negedge disp_rst_n) begin
        if (!disp_rst_n) begin
            aud_sum     <= 29'd0;
            aud_win_cnt <= 13'd0;
            aud_avg_out <= 17'd0;
        end
        else if (hdmi_audio_valid) begin
            if (aud_win_cnt == 13'd8191) begin
                aud_avg_out <= aud_sum[28:13];      // 8192 个采样的平均绝对值
                aud_sum     <= 29'd0;
                aud_win_cnt <= 13'd0;
            end
            else begin
                aud_sum     <= aud_sum + {12'd0, aud_mon_abs};
                aud_win_cnt <= aud_win_cnt + 13'd1;
            end
        end
    end
    reg [16:0] aud_avg_s1, aud_avg_s2;
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin aud_avg_s1 <= 17'd0; aud_avg_s2 <= 17'd0; end
        else            begin aud_avg_s1 <= aud_avg_out; aud_avg_s2 <= aud_avg_s1; end
    end
    wire [15:0] aud_avg_dbg = aud_avg_s2[15:0];   // 最大 32768 = 0x8000，16 位放得下


    //  5b. 【已删除】逐像素自检 `pix_check`（2026-10-15 逐步减重·第①步）

    // ============================================================

    //  它做的唯一一件事：拿 HDMI 上真实的 rgb565_w 和"自测图期望值"逐像素比。

    //  为什么删了**什么都不会少**（硬证据）：

    //    · 它的 11 个输出（chk_cmp/chk_bad/chk_got/chk_exp/chk_u/chk_v + chk_row0..7）

    //      在整个工程里**一个下游都没有** —— 既不进 dbg_report，也不进数码管、

    //      不进任何显示/字幕/音频通路（这就是一颗纯悬空的比较器）；

    //    · 它是【只读】模块：输入只有 clk_pix/de_w/dbg_x/dbg_y/rgb565_w，没有输出接回设计。

    //    · 期望值按自测图（PAT_MODE=2）算，而屏上早就是真图 ⇒ 读数本来就没意义

    //      （顶层第 2183 行附近的老注释也这么写着）。

    //  ★ 要恢复：`git show HEAD:rtl/top_m2.v`（搜 pix_check）把例化放回来，

    //    并把 prj\M2.al 里那条 <File Path="../rtl/pix_check.v"> 加回去。

    // ============================================================



    // ============================================================

    //  6. LED：一眼看出卡在哪一步

    // ============================================================

    reg load_done_latch;

    reg fail_latch;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            load_done_latch <= 1'b0;

            fail_latch      <= 1'b0;

        end

        // ★★★ 2026-10-21【D3 · C1】自动重试开始时把失败锁存清掉：

        //   否则"卡没插时的旧账"会一直挂着 —— 重插成功后红灯还亮、兜底页还判 BAD_IMG，

        //   现场看到的就是"插了卡还是报错"。

        //   ★ 2026-10-21 晚订正：**不再清 `load_done_latch`**。

        //     清了它，兜底页会立刻跳回 LOADING（`fs_state` 的判据是 !load_done_latch），

        //     屏上从"上一张好图"变成黑底 LOADING 大页，而重试往往几十毫秒就成功 ——

        //     现场观感是"插卡那一刻屏幕闪一下"。（上板实测 2026-10-20 21:55）

        //     保留它 = 重试期间继续显示上一张好图，效果和"后台在偷偷重试"一致。

        //   ★★★ 2026-10-21 23:2x【C1g，按用户 m02795 的建议改回来】

        //     "NO_CARD 时把画布判为无效，别让后面接着读错"：

        //     拔卡那一刻 A 轨可能正写到一半（一笔突发只写了几行），SDRAM 里那张图

        //     是**半新半旧**的；而显示侧只要 `load_done_latch` 还是 1 就照读不误

        //     ⇒ 屏上出现的正是"白块 / 错行 / 整体偏移"（上板实测 2026-10-20 22:0x）。

        //     所以恢复期间必须**主动作废画布**：清 `load_done_latch`，

        //     让 `fs_state` 落回 LOADING、整屏换成兜底页，等新装载完成再恢复出图。

        //     代价只是插卡后多一段 LOADING 页（本地几十毫秒 ~ 1 秒）。

        else if (a_recover) begin

            load_done_latch <= 1'b0;

            fail_latch      <= 1'b0;

        end

        else begin

            // ★ 这两个都是【单拍脉冲】，必须锁存 ——

            //   串口每 0.5 秒才看一次，不锁存就会漏掉（这会直接骗人）

            if (a_load_done) load_done_latch <= 1'b1;

            // ★ 装载成功一次就把 fail 清掉：一次成功说明链路是通的，

            //   之前那笔账（多半是卡没插）不该继续亮灯。

            if (a_load_done) fail_latch      <= 1'b0;

            if (a_fail)      fail_latch      <= 1'b1;

        end

    end



    // ============================================================

    //  ★★★ 2026-10-21【D3 · C1e】拔卡检测（读失败计数 ⇒ sd_lost）

    // ------------------------------------------------------------

    //  上板事实（2026-10-20 22:2x 实测，全程不按键）：

    //    拔卡那一刻正在装图 ⇒ `a_fail` 亮（f2 bit4）、`f22` 停住；

    //    此后 **22 秒**没有任何动作（屏上还是旧图，用户看到"拔了没反应"）；

    //    22 s 后才由 C1b 看门狗复位 A 轨、重装、字幕重新载入，自己恢复。

    //  结论：恢复通道是好的，**判据来得太晚**。这里把它提前到"连续两次读失败"。

    // ============================================================


    
    // ★ `a_fail` 是**电平**（一直亮到下次 start），不是脉冲 ⇒ 必须取上升沿，

    //   否则一个坏素材就会把计数器瞬间顶满、把好卡判成"拔走了"。

    reg         a_fail_d;

    wire        a_fail_rise = a_fail & ~a_fail_d;

    // ★★★ 2026-10-23 诊断：top_a 的 fail 来源锁存成粘滞位 → 串口 .sb_flags
    //    （原来这个字段固定送 16'd0，正好空着）
    reg  [5:0]  fail_src_lat;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) fail_src_lat <= 6'd0;
        else        fail_src_lat <= fail_src_lat | a_fail_src;
    end

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) a_fail_d <= 1'b0;

        else            a_fail_d <= a_fail;

    end

    // ============================================================
    //  ★★★ 2026-10-22【扇区级挂死看门狗】治"偶尔不复位"
    // ------------------------------------------------------------
    //  上一版看门狗盯 `a_wr_len`（写了多少字），上板结果是**一直复位**：
    //  找 FAT / 找簇 / 扫目录那一段本来就不写 SDRAM，1 s 不写很正常。
    //  正确的进度信号是 **SD 前端有没有在读扇区**：
    //    · 找图时扇区一直在读 ⇒ 脉冲一直有 ⇒ 不误判
    //    · 卡真被拔  ⇒ SPI 上没有响应、状态机干等 ⇒ 脉冲立刻停 ⇒ 判得出来
    //  只在这两种情况下才计时：
    //    · 有装载在跑（`a_busy` 或 `req_pend_w`）
    //    · 卡已经初始化完（`a_sd_ready=1`；SD init 阶段本来就不读扇区）
    //  1 s 没有扇区脉冲 ⇒ 当成一次失败，喂给同一个 lost_tmr（再 1 s 确认）。
    reg  [25:0] fe_gap;              // 1.0 s @ 50 MHz = 50,000,000
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)                              fe_gap <= 26'd0;
        else if (a_fe_done)                      fe_gap <= 26'd0;
        else if (!(a_busy | req_pend_w))         fe_gap <= 26'd0;
        else if (!a_sd_ready)                    fe_gap <= 26'd0;
        else if (fe_gap != 26'd49_999_937)       fe_gap <= fe_gap + 26'd1;
    end

    reg  fe_stall_d;
    wire fe_stall      = (fe_gap == 26'd49_999_937);
    wire fe_stall_rise = fe_stall & ~fe_stall_d;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) fe_stall_d <= 1'b0;
        else        fe_stall_d <= fe_stall;
    end

    // ============================================================
    //  ★★★ 2026-10-22 晚【卡在位电平的下降沿 = 立即判"卡被拔"】
    // ------------------------------------------------------------
    //  hp8.csv 实测（看门狗版，用户拔卡）：
    //    4.44 s  f2=009F（FAIL）f13 低字节 = 0x2A（fail_cnt=2）
    //    5.20 s  f13 低字节 = 0x00（bit3 = a_sd_ready 掉了）、f25=0003（NO_CARD）
    //    全程 `f13` 高字节 = 00 ⇒ **soft_rst 一次都没触发**。
    //  原因：拔卡瞬间 `a_sd_ready` 就掉成 0，而下面 `else if (!a_sd_ready)` 分支
    //        每拍都在清 `sd_lost`/`lost_tmr` —— 1 s 确认永远走不完 ⇒ sd_lost 出不来。
    //  所以：卡在位电平的**下降沿本身就是证据**，直接判，不再等确认。
    //  `!soft_rst` 是躲开"我们自己复位把 A 轨打掉、sd_ready 跟着掉"的那一下。
    //  注意 sd_lost 只会是单拍（下一拍就被 !a_sd_ready 分支清掉），这正好是
    //  stub_ctrl 要的上升沿；不会反复触发（之后再没有 1→0 的边沿）。
    reg  sd_rdy_d;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) sd_rdy_d <= 1'b0;
        else        sd_rdy_d <= a_sd_ready;
    end
    wire sd_rdy_fall = sd_rdy_d & ~a_sd_ready;

    // ★ 2026-10-23【复位后 3 s 抑制窗】治"越复位越乱、串口一帧都不出"
    //   现象：烧了下降沿判据版之后，板子连串口都没有一帧（帧计数器被反复复位）。
    //   机理：软复位会把 A 轨打掉 ⇒ 它重新 init 时会先"乐观地"把 a_sd_ready 拉高
    //         再掉下来（卡不在时尤其明显）⇒ 又产生一个新的下降沿 ⇒ 再复位……
    //         于是复位周期比串口的 200 ms 上报周期还短，屏和串口全是死状。
    //   做法：每次软复位后先把判据"缴枪"3 s，等 A 轨 init 稳定了再允许认下降沿。
    //         真实拔卡时系统通常已经稳定运行很久，抑制窗早过了，不影响灵敏度。
    reg [27:0] fall_arm;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)                  fall_arm <= 28'd0;
        else if (soft_rst)           fall_arm <= 28'd150_000_000;   // 3.0 s @ 50 MHz
        else if (fall_arm != 28'd0)  fall_arm <= fall_arm - 28'd1;
    end
    wire fall_arm_ok = (fall_arm == 28'd0);

    // ★ 2026-10-22【已废弃：装载无进展看门狗】
    //   试过用 "a_busy=1 且 a_wr_len 1 s 不动" 当挂死判据，上板结果是**一直复位**：
    //   a_busy 是 bmp/wav/sub 三条链的总 busy，而找 FAT / 找簇 / 扫目录那一段本来就
    //   不往 SDRAM 写数据，超过 1 s 很常见 ⇒ 看门狗把正常装载当成挂死。
    //   要可靠地判断"读挂死"，必须看 **SD 前端有没有在读到数据**（扇区级进度），
    //   而不是看 SDRAM 写了多少字。留作后续（需要 top_a 引出扇区计数）。
    //   现在回到只认 a_fail 上升沿的判据。

    always @(posedge clk or negedge rst_n) begin

        if (!rst_n) begin

            fail_cnt <= 2'd0;

            lost_tmr <= 26'd0;

            sd_lost  <= 1'b0;

        end

        else if (sd_rdy_fall && !soft_rst && fall_arm_ok) begin

            // ★ 2026-10-22：卡在位电平掉了 ⇒ 立刻判"卡没了"（下降沿本身就是证据）

            sd_lost  <= 1'b1;

            fail_cnt <= 2'd0;

            lost_tmr <= 26'd0;

        end

        else if (!a_sd_ready) begin

            // A 轨刚被复位、还没 init 完 ⇒ 不计失败，等它重新就绪

            fail_cnt <= 2'd0;

            lost_tmr <= 26'd0;

            sd_lost  <= 1'b0;

        end

        else if (a_load_done) begin

            fail_cnt <= 2'd0;

            sd_lost  <= 1'b0;           // 成功一次就撤销"拔卡"判定

        end

        // ★ 2026-10-23：**单笔 a_fail 不再判拔卡**。
    //   原因：1536×1152 那张图装载 ~1.3 s，装到一半就超过 1 s 确认窗口，
    //   整机会被当成"卡拔了"复位（实测每 8.9 s 复位一次）。
    //   真正的挂死由 fe_stall_rise（扇区停摆 1 s）和 !a_sd_ready 两条覆盖。
    else if (fe_stall_rise) begin

            // ★ 2026-10-22【2 秒确认】用户要求：识别"SD 卡没了"的时间改成 2 s。
            //   旧判据是"连续两次读失败"（每轮轮播 3 s 才有一次尝试）⇒ 实际 3~6 s 才认出来。
            //   新判据：**第一次读失败**就启动 2 s 计时器，2 s 内只要有一次装载成功
            //   （`a_load_done`）就撤销；否则判 `sd_lost`（⇒ 走整块软复位，见 stub_ctrl 的
            //   `sd_lost_i`）。这样"坏一个素材"不会误判（下一次装载会成功），
            //   真拔卡时最迟 2 s 内出 NO_CARD 页。
            if (fail_cnt != 2'd3) fail_cnt <= fail_cnt + 2'd1;

            lost_tmr <= LOST_CONFIRM_TICKS;

        end

        else if (lost_tmr != 26'd0) begin

            lost_tmr <= lost_tmr - 26'd1;

            if (lost_tmr == 26'd1) sd_lost <= 1'b1;   // 2 s 到点仍没成功 ⇒ 判拔卡

        end

    end

    assign sd_ready_eff = a_sd_ready & ~sd_lost;



    // ============================================================

    //  ★★★ 2026-10-21【D2 · B2】兜底页状态机（NO_CARD > BAD_IMG > LOADING > OK）

    // ------------------------------------------------------------

    //  三个输入都在 50 MHz 控制域，先在 `clk` 域算成 3 根电平，再各自两级同步到

    //  `clk_pix`（`failsafe_pg` 在像素流水里，必须同域）。判据：

    //    · NO_CARD  = !a_sd_ready            —— SD 卡初始化就没过（没卡/接触不良）

    //    · BAD_IMG  = fail_latch && !load_done_latch

    //                                       —— 卡在、报过错、而且**一张都没成**

    //                                          （成功过一张就不再报 BAD：接着显示旧图更合理）

    //    · LOADING  = !load_done_latch       —— 正在认 FAT / 读 BMP

    //    · OK       = load_done_latch        —— 已出图 ⇒ fs_on=0，兜底页整个消失

    //  ★ 上电 0.5 s 内一律按 LOADING 显示：否则 SD 还没初始化完就会先闪一下

    //    "NO SD CARD"，现场看着像故障（这是 2026-10-19 评审里点过的坑）。

    // ============================================================

    wire        fs_nocard_w = ~sd_ready_eff;

    wire        fs_bad_w    = fail_latch & ~load_done_latch;

    wire        fs_ld_w     = ~load_done_latch;





    // ============================================================

    //  ★★★ 2026-10-21 晚【D3 · C1b】播放中拔卡 → 装载线程会"吊死"，必须看门狗

    // ------------------------------------------------------------

    //  上板实测（用户 2026-10-20 21:49）：**先插卡上电、再拔卡、再插回** ⇒ 卡住不动。

    //  机理：`sd_init` 只在上电跑一次，`a_sd_ready` 会一直是 1 ⇒ 上面那套"没卡就重试"

    //        根本不会触发；而拔卡时若正有一笔 SD 读在跑，`sd_read` 等不到数据就

    //        **永远等下去**（SPI 上没有超时）⇒ `a_busy` 卡在 1 ⇒ 轮播停住、屏幕冻住。

    //  做法：**按"有没有进展"判活**，而不是按时间判活。

    //    · 四个进度计数（像素/图像字数/字幕字数/音频字数）任意一个在动 ⇒ 活着；

    //    · 连续 `A_STALL_MS` 一个都不动、而且 `a_busy=1` ⇒ 判定吊死，打一拍 `a_stall`；

    //    · `a_stall` 直接复用上一条的 `a_recover` 通道（复位 A 轨）⇒ 复位后

    //      `a_sd_ready` 自然落 0 ⇒ 兜底页显示 NO SD CARD ⇒ 卡插回来由 500 ms 重试接住。

    //  ★ 为什么是 2 s 而不是 500 ms：`find_bmp` 翻簇/翻根目录时**不产生像素**，

    //    大目录下可能几百毫秒没有任何计数变化，判太紧会在正常装载时误杀。

    //  ★ 只取低字节/低半字比较（够用且省触发器）：低位变化最快，看门狗只需要"变没变"。

    // ============================================================

    localparam integer A_STALL_MS    = 2000;

    localparam [26:0]  A_STALL_TICKS = A_STALL_MS * 50_000;     // 50 MHz ⇒ 100,000,000



    reg  [26:0] a_stall_cnt;

    reg  [15:0] a_px_prev, a_wr_prev;

    reg  [7:0]  a_sub_prev, a_wav_prev;

    // （a_stall 的声明在上面 FSM 之前，这里只驱动）



    wire a_prog_chg = (a_dbg_px_cnt[15:0]    != a_px_prev)  ||

                      (a_dbg_wr_cnt[15:0]    != a_wr_prev)  ||

                      (a_dbg_sub_wr_cnt[7:0] != a_sub_prev) ||

                      (a_dbg_wav_cnt[7:0]    != a_wav_prev);



    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            a_stall_cnt <= 27'd0;

            a_stall     <= 1'b0;

            a_px_prev   <= 16'd0;

            a_wr_prev   <= 16'd0;

            a_sub_prev  <= 8'd0;

            a_wav_prev  <= 8'd0;

        end

        else begin

            a_stall    <= 1'b0;

            a_px_prev  <= a_dbg_px_cnt[15:0];

            a_wr_prev  <= a_dbg_wr_cnt[15:0];

            a_sub_prev <= a_dbg_sub_wr_cnt[7:0];

            a_wav_prev <= a_dbg_wav_cnt[7:0];

            if (!a_busy || a_prog_chg)

                a_stall_cnt <= 27'd0;

            else if (a_stall_cnt >= A_STALL_TICKS) begin

                a_stall_cnt <= 27'd0;

                a_stall     <= 1'b1;

            end

            else

                a_stall_cnt <= a_stall_cnt + 27'd1;

        end

    end

    // ============================================================

    //  ★★★ 2026-10-21【D3 · C2/C3】失败原因：{音频格式, 图像格式}

    // ------------------------------------------------------------

    //  背景：44.1 kHz 的 WAV、32 位 BMP **不会报错**，只会被静默丢掉 ——

    //        现场看到的是"图好好的、就是没声音"，或者"BAD IMAGE"但不知为何。

    //  判据（都能从 top_a 透传上来的头字段直接读）：

    //    · 图像：bmp_bpp 读到了，却不是 24 ⇒ 32 位/8 位/16 位 BMP

    //    · 音频：fmt 头有效，却是 44.1 kHz 或非 16 位

    //  ★ 这两个量是"最近一次解析结果"，好素材解析成功后自然回到 24/48000，

    //    所以不需要锁存清除逻辑；只有兜底页会用它（那时反正已经失败了）。

    // ============================================================

    wire fmt_img_bad_w = (a_img_bpp != 16'd0) && (a_img_bpp != 16'd24);

    wire fmt_aud_bad_w = a_aud_iv &&

                         ((a_aud_rate != 32'd48000) || (a_aud_bits != 16'd16));



    reg         fs_fi_s1, fs_fi_s2;     // 图像格式坏（像素域两级同步）

    reg         fs_fa_s1, fs_fa_s2;     // 音频格式坏



    reg         fs_nc_s1, fs_nc_s2;

    reg         fs_bd_s1, fs_bd_s2;

    reg         fs_ld_s1, fs_ld_s2;

    reg  [24:0] fs_boot_cnt;                 // 40 MHz 数到 2e7 ≈ 0.5 s 就停

    reg         fs_boot_done;



    always @(posedge clk_pix or negedge disp_rst_n) begin

        if (!disp_rst_n) begin

            fs_nc_s1 <= 1'b0; fs_nc_s2 <= 1'b0;

            fs_bd_s1 <= 1'b0; fs_bd_s2 <= 1'b0;

            fs_ld_s1 <= 1'b1; fs_ld_s2 <= 1'b1;

            fs_fi_s1 <= 1'b0; fs_fi_s2 <= 1'b0;

            fs_fa_s1 <= 1'b0; fs_fa_s2 <= 1'b0;

            fs_boot_cnt  <= 25'd0;

            fs_boot_done <= 1'b0;

        end

        else begin

            fs_nc_s1 <= fs_nocard_w;  fs_nc_s2 <= fs_nc_s1;

            fs_bd_s1 <= fs_bad_w;     fs_bd_s2 <= fs_bd_s1;

            fs_ld_s1 <= fs_ld_w;      fs_ld_s2 <= fs_ld_s1;

            fs_fi_s1 <= fmt_img_bad_w; fs_fi_s2 <= fs_fi_s1;

            fs_fa_s1 <= fmt_aud_bad_w; fs_fa_s2 <= fs_fa_s1;

            if (!fs_boot_done) begin

                if (fs_boot_cnt == 25'd20_000_000) begin

                    fs_boot_done <= 1'b1;

                end

                else begin

                    fs_boot_cnt <= fs_boot_cnt + 25'd1;

                end

            end

        end

    end



    // 优先级：NO_CARD > BAD_IMG > LOADING > OK（`fs_boot_done` 前强制 LOADING）

    assign fs_state_w = (!fs_boot_done) ? 2'd1 :

                        fs_nc_s2        ? 2'd3 :

                        fs_bd_s2        ? 2'd2 :

                        fs_ld_s2        ? 2'd1 : 2'd0;

    // 只要还在"没出图"的任意一个状态就出兜底页；OK 时整页消失

    assign fs_on_w    = (fs_state_w != 2'd0);

    // ★ D3 · C2/C3：只在"确实是格式问题"时才改文案（bit0 图像 / bit1 音频）

    assign fs_hint_w  = {fs_fa_s2, fs_fi_s2};



    // ============================================================

    //  ★★★ 2026-10-05：音频上板首试 —— 自产的"装音效 + 播放"命令

    // ------------------------------------------------------------

    //  为什么要有它：C 轨还没接，`play_sfx / sfx_id / volume` 没有来源。

    //  这一版让顶层自己发一遍，把整条链（SD → SDRAM → top_aud → HDMI）走通。

    //

    //  ★ 顺序（全自动，不用按键）：

    //     上电 → 装第一张图（原有流程一个字没改）→ 图显示出来

    //          → 等 1 秒 → **屏上米白 ≈ 音效时长**（装音效；装载期间显示整段禁读

    //            是当前唯一确认不花屏的那一档）

    //          → 图自己回来 + **自动播一次**

    //     之后每**拨一次开关3（SW3=C6）**才换下一条音频并重播一次

    //     （★★ 2026-10-14 深夜改：换图用的 KEY3 从此**只管换图**，不再顺带换/播音频；

    //       "换图带音效"这个旧行为一并取消 —— 见下面 `sel_aud` 与那个受理 if 的注释）

    //     （sfx_ctrl 正在播时会自动忽略新命令）

    //

    //  ★ 判据（串口字段 28 的高 8 位）：

    //     bit15 aud_fail / bit14 aud_loaded / bit13 音频PLL锁 / bit12 aud_busy

    //     bit11 有音频数据流 / bit10 play_tgl 在翻 / bit9:8 状态机

    // ============================================================

    // ★★★ 2026-10-13【换照片时那阵沙沙的修复】：`aud_arm` = "人来按过 KEY3、等着响一次"

    reg         aud_arm;

    // ★★★ 2026-10-21【D4 · BGM 循环】

    //   `aud_ran` = "这一遍真的放过（busy 拉起来过）"。

    //   state 3 靠它判"放完了"：busy 掉下来那一刻再发一次 play 请求，

    //   数据还在 SDRAM 音效区里，不重装（重装要 0.2 s、还会闪一下屏）。

    //   ★ 不用 `!busy` 直接触发，否则刚进 state 3、busy 还没拉起来的几拍也会被当成"放完"。

    localparam integer BGM_LOOP = 1;       // 0 = 回到"只放一遍"的老行为（回退开关）

    // ★ 2026-10-21【D4 · 消接缝"嗒"声】：放完之后先留一段静音再重起。

    //   原因：`sfx_player` 在 data_done 之后是"指数衰减到 0"，衰减要几十毫秒；

    //   原来 busy 一掉就立刻重发 play，新一遍的第 0 个采样直接顶上去 ⇒ 跳变 = 一声"嗒"。

    //   留 40 ms（2,000,000 拍 @50 MHz）让衰减走完，重起时再从 0 起。

    localparam [25:0] BGM_GAP = 26'd2_000_000;

    reg         aud_ran;

    reg  [25:0] aud_gap;

    // ★★★ 2026-10-17【提速 · 装载音乐】`aud_first` = "还没装好过第一条音频"

    //   上面 state 1 那 1 秒（50_000_000 拍 @50MHz）本来只是**开机**为了让用户先看清图片，

    //   但拨 SW3 换音频时也会照着走一遍 ⇒ 每换一条都要白等 1 秒（实际装载只要 0.2 s 左右）。

    //   ⇒ 用 `aud_first` 把两者区分开：开机第一趟只留 40 ms（让首帧/转场彻底落定），

    //     之后（第一条真的装完 = `a_wav_done`）`aud_first` 清零 ⇒ 换音频时**立即开装**。

    reg         aud_first;

    // ★ 等多久才开装：开机第一趟 40 ms（★ 2026-10-25 P0-5：state 1 门条件已保证"图显示完 + A 轨空闲"，原来白等 1 s）；之后只是"等上一条停稳"，

    //   2000 拍 @50MHz = 40 µs —— 足够让 stop 的 toggle 跨到显存域、让在途的音频读收干净。

    wire [25:0] aud_wait_need = aud_first ? 26'd2_000_000 : 26'd2000;   // ★ P0-5: 50_000_000(1s) -> 2_000_000(40ms)

    // ★★★ 2026-10-17【修 · 自然放完那一声"啦"】：见下面 `aud_st==2` 里那段长注释。

    //   raw = 夹到音效区容量；al = 再向下取到 64 字整块（aud_blk_arb 的 BLK_WORDS）。

    //   ★ 为什么先减 64 再取整：实测**最后一块会多交付 2 个字**（把播放长度取到 64 整块后，

    //     交付数 49602 = 49600 + 2）。留 64 字的余量 ⇒ 那 2 个字一定还是**歌内真实数据**；

    //     否则文件长度正好是 64 的整数倍（例如被 SFX_WORDS_CAP=120000 夹住的长音乐）时，

    //     多出来的 2 个字就是音效区外的陈旧字 ⇒ 那声"啦"会回来。

    //     代价：最多多丢 127 字 = 5.3 ms 尾巴，听不出来。

    wire [20:0] aud_len_raw = (a_wr_len > SFX_WORDS_CAP) ? SFX_WORDS_CAP : a_wr_len;

    wire [20:0] aud_len_al  = (aud_len_raw - 21'd64) & ~21'd63;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            aud_first      <= 1'b1;

            aud_want       <= 1'b0;

            aud_loaded     <= 1'b0;

            aud_fail       <= 1'b0;

            aud_load_pulse <= 1'b0;

            aud_play_req   <= 1'b0;

            aud_st         <= 2'd0;

            aud_wait       <= 26'd0;

            aud_arm        <= 1'b0;

            aud_ran        <= 1'b0;      // ★ D4 · BGM 循环：复位清"这一遍放过没有"

            aud_gap        <= 26'd0;

            sw3_pend       <= 1'b0;      // ★★★ 2026-10-14 深夜【开关3 切音频】复位清掉挂起的拨动

            alert_pend     <= 1'b0;      // ★ D5b

            alarm_audio_ok <= 1'b1;      // ★ D5b：先当作卡上有，装失败再置 0

            // ★★★ 2026-10-17【修 bug ③】`sel_aud` 原来**没有复位**（全文只有递增那两行赋值）

            //   ⇒ KEY4 软复位之后，别的音频状态全清、它却留着上一次的选择：

            //     重装的是"软复位前那条"，和"复位后回到干净状态"的预期不一致，

            //     而且它是本块里唯一没复位的寄存器（属于漏写，不是设计）。

            //   ★ 复位后回到第 1 条（= 卡上第一个 .WAV），和上电行为一致。

            sel_aud        <= {SEL_AUD_W{1'b0}};

        end

        else begin

            aud_load_pulse <= 1'b0;

            aud_stop_req   <= 1'b0;      // ★ 只在下面"受理 SW3"那一路置一拍

            // ★★★ 2026-10-14 深夜【开关3 切音频】—— 开关3 一变化就先"挂起一次换下一条"

            //   ★ 这一句和 `aud_load_pulse <= 1'b0;` 同级、无条件执行：

            //     变化若发生在"装载中 / 音频还没装好"，事件也不会丢 —— 挂起位一直留着，

            //     等下面那个受理 if 真的成立（`aud_loaded`、不在装载中）时才被受理并清零。

            //     ⇒ 快速连拨两次，第二次不会被漏掉。

            //   ★ 同一 always 里【后赋值优先】：下面受理分支在**后面**，

            //     所以"同拍既置位又受理"时以"受理并清零"为准（正是我们要的）。

            // ★★★ 2026-10-25【MULTI BOOT】SW3 改为「切显示分辨率」，手动切歌停用：
            //   音乐现在由「一图一乐」跟着图片自动走（图 k ⇒ 第 k 首），不再需要拨开关。
            //   拨 SW3 只登记一次分辨率切换请求，等到「下一张图」的请求到来时才重配置位流。
            if (1'b0) sw3_pend <= 1'b1;

            // ---- 什么时候响一次音效 ----

            // ★★★ 2026-10-13【修复 · 换照片时的沙沙】：原来挂的是 `req_accept_w`

            //   （= "换图请求被受理"），而**【预装 prefetch】在 IDLE 期间也会产生一次受理**

            //   ⇒ 音效会在没人按键时自己重播；更要命的是那次重播**正落在装载正在写 SDRAM

            //   的时刻**，撞上本工程的红线"**读写不能重叠**" ⇒ 读回来的音频被打错 bit

            //   ⇒ 用户听到的"**换照片时一阵沙沙**"（第一遍播放是干净的，因为它在装载之后）。

            //   （10-08 之所以从 `a_load_done` 改成 `req_accept_w`，是为了避开"预装时 a_load_done

            //     也会来一次"；现在两边一起解决：**只由人按 KEY3 武装**，**等这一张真的装完**才响。）

            // ★★★ 2026-10-14【用户方案：声音也像图片一样"每次重新装载"】：

            //   按 KEY3（换图）时，让音效**重走一遍装载流程**（= 把音效重新灌进 SDRAM），

            //   装完（下面 `aud_st==2` 那条 `a_wav_done` 分支）再播 —— 与图片那套

            //   "重新装载 → 再显示"完全同构。两个好处：

            //     ① 治"音频区放久了会坏"（每次换图都刷新一遍音频数据，和图片一样）；

            //     ② **装载与播放天然分开**（装完才播），彻底避开旧写法"装载期间直接重播"

            //        撞"读写不能重叠"红线的问题。

            //   ★ 注意：这里要放在下面 case 之前 —— 同一 always 里后赋值优先，

            //     `aud_st==2` 分支的 `aud_play_req <= 1'b1` 必须能覆盖这一句。

            // ★★★ 2026-10-24【一图一乐】换图 ⇒ 音乐跟着换（第 k 张图配第 k 首；2026-10-25 去掉 mod，5 图 5 曲一一对应）
            //   · u_ctrl 在受理请求那一拍给出"这张图是第几张"(req_skip_w)，这里换算成音乐序号；
            //   · req_aud_mod == sel_aud 说明"这张图的配乐就是当前这首"⇒ 什么都不做；
            //   · 否则用的是和下面 SW3 切歌完全一样的三件套：清 loaded/fail、进 1 态重新装、
            //     先 stop —— 音频 FSM 会自己走"重装 WAV → 从头播 → 循环"，不用另写通路；
            //   · 报警期间（alert_on）不抢：报警音由下面"报警边沿"块负责，退出报警后那张图的
            //     换图请求会再进来一次（img_req_pend 的 alert_fall 边沿），配乐自然跟上；
            //   · 只在 (aud_loaded || aud_fail) 时才算"换歌"：正在装载/等待时不动它
            //     （state2 的 a_sd_skip 在装载开始那拍已经锁定了，半路改只会更乱）。
            if (req_accept_w && !alert_on && (req_aud_mod != sel_aud)) begin
                sel_aud <= req_aud_mod;
                if (aud_loaded || aud_fail) begin
                    aud_loaded   <= 1'b0;
                    aud_fail     <= 1'b0;
                    aud_st       <= 2'd1;
                    aud_wait     <= 26'd0;
                    aud_stop_req <= 1'b1;
                end
            end

            // ★★★ 2026-10-14【重新打开"重装"】+【音频块 512 字】= 全套修复：

            //   失真已确认是"每 64 字一条块边界接缝"（`a_image\top_aud.v` 里 BLK_WORDS 64→512

            //   上板验证：失真明显变轻/消失），与"重装"无关（A/B 已证）⇒ 重装照旧打开。

            // ★★★ 2026-10-14 深夜【功能·开关3 切音频】—— "拨一下 ⇒ 换下一条音频 + 立刻重装 + 从头播"

            //   ★ 触发事件 = **开关3（SW3 = C6）** 消抖后的"任意方向变化"脉冲，两条并用：

            //       `sw3_change`（本拍刚变）+ `sw3_pend`（变过但还没被受理，见块首置位那句）

            //     ⇒ 连拨不漏；和换图彻底解耦（`k1_press_w` 只驱动 `stub_ctrl` 换图，2026-10-17 起那根是 KEY2）。

            //   ★ 来源依据（C6 / 双边沿 / 不用 `key_press_debounce` 的理由）：

            //     见文件上方 `sel_aud` 声明处那一大段注释 + `lib\util\sw_edge_debounce.v` 文件头。

            //   ★ `sel_aud` 的递增就放在**这个 if 里面**（不是无条件 on sw3_change）：

            //     `a_sd_skip` 是【组合直通】到 `wav_analyze → find_bmp` 的（skip 在那里才锁存），

            //     只有"这次脉冲确实会引发一次、且仅一次、且不在装载途中"的装载时才改它才安全：

            //       · `aud_st==2`（装载中）时这个 if 不成立 ⇒ 选择位只会在上一次装载

            //         **真正结束之后**才变，绝不会在装载途中被改坏；

            //       · 也顺手排除"`sub_load_pulse` 与开关3 变化同拍"把字幕那一趟的 skip 带偏。

            //   ★ 取模循环：到"最后一条"回 0，否则 +1。

            // ★★★ 2026-10-17【修 bug ④】受理条件里原来那个 `&& !aud_fail` 是个**死锁**：

            //   `aud_fail` 只在 `sys_rst_n` 清（本块复位），而本块一旦 fail

            //   （找文件失败 / 文件超过音效区容量 / SD 读错）就再也进不了 0/1 态

            //   ⇒ **SW3 换音频这条功能永久失效，只能按 KEY4 或重新上电**。

            //   （`SFX_NUM` 设得比卡上实际 .WAV 条数大时必然踩到，注释里写着"需 KEY4 恢复"。）

            //   ⇒ 改成允许"失败后重试"：`(aud_loaded || aud_fail)` 都受理，

            //     并且受理时把 `aud_fail` 清掉（下一态就是 1 → 重新装载）。

            //   ★ 对正常路径逐位无影响：`aud_loaded=1, aud_fail=0` 时条件与原式等价。

            // ★★★ 2026-10-25【MULTI BOOT】SW3 改作切分辨率 ⇒ 音频手动切歌分支停用
            //   （保留块体只为让下面的注释/历史可查；条件恒假，TD 会整块优化掉。）
            if (1'b0) begin

                aud_loaded <= 1'b0;        // 让它重走装载（= 音效也像图片一样每次刷新）

                aud_fail   <= 1'b0;        // ★ 修 bug ④：失败后允许 SW3 重试，不再需要 KEY4

                aud_st     <= 2'd1;        // → 等 A 链空闲 + 上一首停稳 → 装载

                aud_wait   <= 26'd0;

                sw3_pend   <= 1'b0;        // ★ 受理了：清掉挂起（若本拍同时置位，以后赋值为准 ⇒ 干净）

                aud_stop_req <= 1'b1;      // ★★★ 2026-10-17【修 · 失真】先停上一首！

                                           //   否则"旧播放指针 + 已被覆写的区域"= 串味，

                                           //   而且装载完那一拍 play 还会被 sfx_ctrl 的 !busy 丢掉。

                // ★★★ 2026-10-14 深夜【功能·开关3 切音频】：换到下一条音频

                if (sel_aud == SFX_NUM - 1) sel_aud <= {SEL_AUD_W{1'b0}};   // 最后一条 → 回到第 1 条

                else                        sel_aud <= sel_aud + {{(SEL_AUD_W-1){1'b0}}, 1'b1};

            end

            // ============================================================

            //  ★★★ 2026-10-21【D5 · S1 报警音】报警边沿 ⇒ 重装音频

            // ------------------------------------------------------------

            //   · `alert_rise`：立刻改成装第 5 条（`ALARM_SKIP`），循环播

            //   · `alert_fall`：再编回去装用户选的那条（`sel_aud`）

            //   和 SW3 那条用的是**同一套三件套**（清 loaded / 进 1 态 / 先 stop），

            //   所以"装载途中被改坏"的边界条件已被上面那套论证覆盖：

            //   本块只在 `aud_st != 2`（不在装载中）才受理边沿。

            //   ★ 报警边沿时若正在装载（`aud_st==2`），等它装完再说 ⇒ 用 pend 记住。

            // ============================================================

            alert_pend <= (alert_pend || aud_edge) && (aud_st != 2'd2);

            if ((alert_pend || aud_edge) && (aud_st != 2'd2) &&

                (aud_loaded || aud_fail)) begin

                aud_loaded   <= 1'b0;

                aud_fail     <= 1'b0;

                aud_st       <= 2'd1;

                aud_wait     <= 26'd0;

                aud_stop_req <= 1'b1;

                alert_pend   <= 1'b0;

            end

            aud_play_req <= 1'b0;          // 只由"装载完成"那一路置起



            case (aud_st)

            // ---- 0：等第一张图真的出来 ----

            2'd0: begin

                // ★★ 2026-10-06：AUDIO_OFF=1 时在这里就停住 —— 不进 1，也就

                //    不会装音效、不会播放 ⇒ 音频一个读都不发（见上面那个开关的说明）。

                if (AUDIO_OFF) begin

                    aud_st <= 2'd0;

                end

                // ★ 2026-10-24：字幕优先——字幕还欠着装就先别抢 SD（否则字幕要等音频 0.4 s）
                else if (load_done_latch && !aud_loaded && !aud_fail) begin

                    aud_wait <= 26'd0;

                    aud_st   <= 2'd1;

                end

            end

            // ---- 1：等 aud_wait_need（开机 1 s / 换音频 40 µs），再挑"上一首停了、没在换图"的时刻开装 ----

            2'd1: begin

                if (!load_done_latch) begin

                    aud_st <= 2'd0;

                end

                // ★★★ 2026-10-17【修 · 失真】多等一条 `!aud_busy_w`（= 上一首真的停了才动笔写）：

                //   音效区和播放读的是同一片 SDRAM，边写边放 ⇒ 旧指针读到新数据 = 串味。

                // ★★★ 2026-10-23【和字幕互斥】三根 start 是或在一起的
                //   （`a_start_use | aud_load_pulse | sub_load_pulse`），而 `a_sd_mode`
                //   的优先级是 图 > 字幕 > 音频。若音频和字幕同一拍发脉冲，A 会按
                //   "字幕"去装，音频 FSM 却以为自己在装 WAV ⇒ 等 a_wav_done 等到超时。
                //   ⇒ 音频这边也看一眼 `sub_pend_w` / `sub_load_pulse`
                //     （字幕那边本来就有 `!aud_load_pulse`），
                //     再加 `!a_start_use` 防"图像启动那一拍"被抢。
                else if (!img_hold && !tr_active && !a_busy && !req_pend_w && !aud_busy_w
                         && !sub_load_pulse && !a_start_use) begin

                    if (aud_wait >= aud_wait_need) begin   // ★ 换音频时不再白等 1 秒

                        aud_want       <= 1'b1;

                        aud_load_pulse <= 1'b1;

                        aud_st         <= 2'd2;

                    end

                    else aud_wait <= aud_wait + 26'd1;

                end

                // 忙（正在换图 / A 在装 / 有挂起的转场请求）就停着等，计时不推进

            end

            // ---- 2：等音效装完 ----

            2'd2: begin

                if (a_wav_done) begin

                    aud_loaded    <= 1'b1;

                    aud_first     <= 1'b0;     // ★ 装好过一条了 ⇒ 以后换音频不再等那 1 秒

                    // ★★★ 2026-10-15【音频溢出保护 · 播放侧】：播放长度【上限 = 音效区容量】

                    //   （120000 字 = 5.0 s @48 kHz）—— 超过 5 秒的部分不放。

                    //   不夹的话会一路播到音效区之外（区外紧挨着小槽区 / 字幕区）⇒ 读乱数据、沙沙。

                    //   ★ 三元夹取：a_wr_len ≤ 上限时结果就等于 a_wr_len ⇒ ≤5 s 的文件逐位不变。

                    //

                    // ★★★ 2026-10-17【修 · 自然放完那一声"啦"（碎音）】

                    //   上板判据：**自然放到底**有碎音，而**歌还在响时拨 SW3 打断**是干净的

                    //   —— 两条路唯一的差别是"最后一块"：

                    //     · SW3 打断走 `stop_sfx` → aud_blk_rd 直接 flush（arp<=wrp_bin、dout_v<=0），

                    //       根本不发短块；

                    //     · 自然放完的最后一块是**短块**（49641 = 775×64 + 41 ⇒ 最后只要 41 字），

                    //       而整首歌里其它块全是满 64 字 —— 短块这条路径平时从不走，

                    //       官方控制器 read_len 对非对齐长度的对齐/收尾就露在最后这 2 ms 上。

                    //   ⇒ 播放长度**向下取到 64 字整块**（BLK_WORDS，见 a_image\aud_blk_rd.v），

                    //     这样从头到尾每一块都是满块，短块路径彻底不用。

                    //     ★ 实测：最后一块还会**多交付 2 个字**（交付数 49602 = 49600 + 2），

                    //       所以上面 `aud_len_al` 先减 64 再取整，保证那 2 个字落在歌内真数据上。

                    //     ★ 代价：最多丢 127 字 = 5.3 ms 的尾巴，听不出来。

                    //     ★ 兜底：万一文件短到 64 字以下（取整成 0），就用原长度，

                    //       不能让 0 传下去 —— sfx_ctrl 里 0 的含义是"退回 SFX_STRIDE"。

                    aud_words_act <= (aud_len_al != 21'd0) ? aud_len_al : aud_len_raw;

                    aud_want     <= 1'b0;

                    aud_play_req <= 1'b1;

                    aud_st       <= 2'd3;

                end

                else if (a_fail) begin

                    aud_want <= 1'b0;

                    if (alert_on && alarm_audio_ok) begin

                        // ★ 卡上没有第 5 个 WAV ⇒ 放弃报警音，立刻装回用户那条（BGM 不能哑）

                        alarm_audio_ok <= 1'b0;

                        aud_fail       <= 1'b0;

                        aud_loaded     <= 1'b0;

                        aud_wait       <= 26'd0;

                        aud_st         <= 2'd1;

                    end

                    else begin

                        aud_fail     <= 1'b1;

                        aud_loaded   <= 1'b0;      // ★ 2026-10-25【缺配套不沿用】没有这首 ⇒ 静音，不让上一首继续响

                        aud_stop_req <= 1'b1;      // ★ 先停播（flush + fade），别沿用上一首

                        aud_st       <= 2'd3;

                    end

                end

            end

            // ---- 3：放完了 —— ★ D4：BGM 循环，重新起一遍（不重装） ----

            2'd3: begin

                if (aud_busy_w) begin

                    aud_ran <= 1'b1;            // 真的放过（读出过数据）

                    aud_gap <= 26'd0;

                end

                else if (aud_ran && BGM_LOOP && aud_loaded && !aud_fail) begin

                    // ★ 留 40 ms 静音让"放完那一下的指数衰减"走完，再重起

                    if (aud_gap >= BGM_GAP) begin

                        aud_ran      <= 1'b0;

                        aud_gap      <= 26'd0;

                        aud_play_req <= 1'b1;   // 数据仍在音效区 ⇒ 只重发"开始播"

                    end

                    else aud_gap <= aud_gap + 26'd1;

                end

            end

            default: ;

            endcase

        end

    end



    // ============================================================
    //  ★★★ 2026-10-23【字幕装载重做】
    // ------------------------------------------------------------
    //  原来的三个问题（上板现象：字幕上电出来慢 / 换图不跟着变 / 偶尔整个消失）：
    //    ① 状态 0 要等"音频先装完"（aud_loaded/aud_fail）才动 ⇒ 字幕排在音频后面，
    //       多等 1 s（音频启动延时）+ 一次音频装载（0.2~0.5 s）+ 0.5 s。
    //    ② 状态 1 里那 0.5 s 是音频时代的遗留；现在字幕优先，40 µs 足够。
    //    ③ 「跟图换字幕」那条 `sub_img_rise` 被写进了状态 2（等字幕写完），
    //       而 top_a 用 a_busy 把图/字幕串行化 ⇒ 图片装完不可能发生在状态 2
    //       ⇒ 那条分支永远不会命中，字幕永远停在开机第一条。
    //  现在：
    //    · 状态 0 只等"图已经出来过"（load_done_latch），不再等音频；
    //    · 状态 1 等 A 链空闲 + 40 µs 就发（字幕优先于音频/预装）；
    //    · 「跟图换字幕」移到状态 3（真正做完）里，触发源改成**换图请求被受理**
    //       （不用 a_load_done：预装也会拉它，会让字幕抢在图片前面变），
    //       且**不清 sub_loaded** ⇒ 装载期间旧字幕一直显示，装完（a_sub_done）才翻槽。
    // ============================================================
    //  ★ 2026-10-23【帧首锁存】帧首脉冲（clk_pix 单拍 → 翻转位 → clk 域取边沿）
    // ============================================================
    reg  fs_tog;
    reg  fs_t1, fs_t2, fs_t3;
    always @(posedge clk_pix or negedge sys_rst_n) begin
        if (!sys_rst_n) fs_tog <= 1'b0;
        else            fs_tog <= fs_tog ^ frame_start_pix;   // 一帧翻一次
    end
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin fs_t1 <= 1'b0; fs_t2 <= 1'b0; fs_t3 <= 1'b0; end
        else            begin fs_t1 <= fs_tog; fs_t2 <= fs_t1; fs_t3 <= fs_t2; end
    end
    wire fs_pulse = fs_t2 ^ fs_t3;      // 每帧一个 clk 宽脉冲

    // ★ 2026-10-24【帧差探针】图装完 → 字幕装完 差多少帧（直接量，不猜）
    reg  [15:0] frame_cnt;
    reg  [15:0] t_img, d_sub;
    reg  [15:0] sub_t0, sub_ft, sub_rt;
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin frame_cnt <= 16'd0; t_img <= 16'd0; d_sub <= 16'd0; end
        else begin
            if (fs_pulse) frame_cnt <= frame_cnt + 16'd1;
            if (img_done_rise) t_img <= frame_cnt;
            if (a_sub_done)   d_sub <= frame_cnt - t_img;
            if (sub_load_pulse) sub_t0 <= frame_cnt;
            if (a_sub_done)     sub_ft <= frame_cnt - sub_t0;
        end
    end

    //    ★ 双缓冲本身不变：写 sub_wr_base（非显示槽）、读 sub_rd_sel 那一槽。
    // ============================================================

    // ★ 2026-10-23【触发源：换图请求被受理，而不是"图片写进 SDRAM"】
    //   ★ 为什么不用 `a_load_done`：**预装**（prefetch）也会拉这个脉冲 ——
    //     后台槽偷偷装下一张时，图片还没换、字幕就先变了，图文对不上。
    //   ★ `req_accept_w` = "本次换图请求被受理"（上电自动 / 按键 / 轮播 / 报警
    //     共用这一拍）。它比转场结束**早**，所以字幕 FSM 从这一刻就进入状态 1，
    //     一直等 `!tr_active`（转场结束）才真正去装：
    //       · 预装        → 没有请求 ⇒ 不触发
    //       · 按键/轮播   → 请求 → 等转场结束 → 装（快路/慢路都对）
    //       · 上电第一张  → 状态 0 已经负责首装，pend 被这次装载清掉
    //   ★ 这还有个副作用（是好事）：`sub_pend_w` 从请求那一刻就压住预装，
    //     不会出现"转场刚结束、预装抢先开跑、字幕又被堵 1 秒"。
    //   ★ 用 pending 位锁住，防止请求那一拍正好落在状态 2/1 被漏掉。
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n)          sub_req_pend <= 1'b0;
        else if (req_accept_w)   sub_req_pend <= 1'b1;   // 欠一次字幕重装
        else if (sub_load_pulse) sub_req_pend <= 1'b0;   // 本次装载已经发出，欠账清掉
    end

    // ★ 装载前只等这么久（40 µs @50 MHz）。原来的 0.5 s 是"音频先做完"时代的
    //   保险；现在字幕排在音频/预装前面，A 链空闲下来就能开装。
    localparam [25:0] SUB_SETTLE_TICKS = 26'd2_500_000;   // 2026-10-23: 40us -> 50ms（装载起始可能与上一条链尾部抢，先等干净）

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            sub_st         <= 2'd0;

            sub_rd_sel     <= 1'b1;      // ★ 复位 = 1 ⇒ 第一次写槽 0（= 卡里第 1 条 .SUB）

        sub_swap_pend  <= 1'b0;
        sub_rd_sel_next <= sub_rd_sel;   // ★ 复位：下一帧显示的 = 当前显示的


            sub_load_pulse <= 1'b0;

            sub_loaded     <= 1'b0;

            sub_fail       <= 1'b0;

            sub_retry      <= 2'd0;

            sub_wait       <= 26'd0;

            sub_pulse_lat  <= 1'b0;

            sub_done_lat   <= 1'b0;

        end

        else begin

            sub_load_pulse <= 1'b0;

            case (sub_st)

            // ---- 0：等第一张图真的出来（不再等音频；音频排在字幕后面）----

            2'd0: begin

                if (load_done_latch && !img_hold) begin

                    sub_wait <= 26'd0;

                    sub_st   <= 2'd1;

                end

            end

            // ---- 1：挑一个"没在换图 / 没在装别的"的时刻，等 40 µs 再发 ----

            2'd1: begin

                // ★ 不能和图像/音频的 start 同拍：三根 start 是或在一起的，
                //   同拍时 a_sd_mode 会把这次传输判给字幕或音频，另一方会等不到自己的 done。
                if (!img_hold && !a_busy && !a_start_use
                    && !req_pend_w && !aud_load_pulse) begin

                    if (sub_wait >= SUB_SETTLE_TICKS) begin

                        sub_load_pulse <= 1'b1;

                        sub_pulse_lat  <= 1'b1;                // ★ 探针：脉冲发出去过

                        sub_wait       <= 26'd0;

                        sub_st         <= 2'd2;

                    end

                    else sub_wait <= sub_wait + 26'd1;

                end

                // ★ 2026-10-23：一旦不空闲（转场/别人在装/别家 start 那一拍）
                //   就把 40 µs 重新计 —— 避免"图像 start 的下一拍 a_busy 还没涨上来"
                //   这个 1 拍窗口里把字幕脉冲插进去（两条链会抢 sd_mode）。
                else sub_wait <= 26'd0;

            end

            // ---- 2：等这一条字幕写进 SDRAM；失败就保留旧字幕（不清 sub_loaded）----

            2'd2: begin

                if (a_sub_done) begin

                    sub_loaded <= 1'b1;

                    sub_done_lat <= 1'b1;                      // ★ 探针：A 报"装完了"

                    sub_rd_sel_next <= sub_wr_sel;          // ★ 2026-10-23：只登记，帧首才兑现
                    sub_retry   <= 2'd0;                    // 成功就清重试计数

                    sub_st     <= 2'd3;

                end

                // ★ 等 40 ms 之后再信 a_fail：`a_fail` 是三条链**合并**的出错口，

                //   之前的装载（比如卡里没 WAV）可能已经把它拉高过，不能立刻判死。

                else if (sub_wait < 26'd2_000_000) begin

                    sub_wait <= sub_wait + 26'd1;

                end

                // ★ 2026-10-23：a_fail 是三条链合并的**电平**，上一次失败会一直举着，不能拿电平早判死
                //   （实测一半字幕装载被误判失败 ⇒ 字幕不换）。电平判据已注释，改成**上升沿**。
                // ★ 2026-10-25【缺配套不沿用】这一趟 A 确实报错（卡上没有第 k 条字幕）⇒ 立刻撤字幕，
                //   别让上一张的字幕挂在新图上；等下一次 a_sub_done 再重新打开。
                else if (a_fail_rise) begin
                    sub_wait   <= 26'd0;
                    sub_retry  <= 2'd0;
                    sub_fail   <= 1'b1;
                    sub_loaded <= 1'b0;
                    sub_st     <= 2'd3;
                end

                // ★ 另一个兜底：A 已经闲下来了却迟迟没有 sub_done ⇒ 那条链没跑起来

                else if (!a_busy) begin

                    sub_wait <= sub_wait + 26'd1;

                    if (sub_wait >= 26'd30_000_000) begin      // 300 ms：一条字幕正常 ~135 ms
                        sub_wait <= 26'd0;
                        if (sub_retry < 2'd3) begin
                            // 2026-10-23：SD 前端偶发丢字节 ⇒ 头解析失败。
                            //   同一趟最多再试 2 次，不把整条字幕判死。
                            sub_retry <= sub_retry + 2'd1;
                            sub_st    <= 2'd1;
                        end
                        else begin
                            sub_fail  <= 1'b1;
                            // ★ 2026-10-25【缺配套不沿用】重试也装不上 ⇒ 撤掉旧字幕（屏上留空，不挂上一张的）
                            sub_loaded <= 1'b0;
                            sub_st    <= 2'd3;
                        end
                    end

                end

            end

            // ---- 3：做完 —— 报警边沿 / 换了一张图 ⇒ 回 1 态重装另一槽 ----
            //   ★ 这里**不碰 sub_loaded**：重装期间旧字幕继续显示；
            //     a_sub_done 那一拍才翻 sub_rd_sel，画面不会闪空。

            2'd3: begin

                if (alert_rise | alert_fall) begin

                    sub_fail   <= 1'b0;
                    sub_retry  <= 2'd0;

                    sub_wait   <= 26'd0;

                    sub_st     <= 2'd1;

                end

                else if (sub_req_pend) begin

                    sub_fail   <= 1'b0;
                    sub_retry  <= 2'd0;

                    sub_wait   <= 26'd0;

                    sub_st     <= 2'd1;

                end

            end

            default: ;

            endcase

            // ★ 2026-10-23【帧首锁存】只在帧起点翻字幕槽：与图像描述符同一帧边界生效。
            //   不再看 tr_active（转场不是帧边界；大图时它能高 4 s 多，字幕会被拖住）。
            if (fs_pulse) begin
                sub_rd_sel <= sub_rd_sel_next;
            end

        end

    end



    assign led[0] = pll0_locked & pll_sdr_locked;   // 两个 PLL 都锁了

    assign led[1] = a_sd_ready;                     // SD 卡初始化完成

    assign led[2] = load_done_latch;                // 至少装完过一张

    assign led[3] = fail_latch;                     // A 报错过（亮就是出问题，一直亮）



    // ============================================================

    //  ★ 2026-09-28 诊断位图：塞进串口的 drop_cnt 字段（read_report.ps1 会翻译）

    //    目的是把"蓝屏"这件事一次看清：到底谁把显示的读挡住了。

    // ============================================================

    reg a_started_lat;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) a_started_lat <= 1'b0;

        else if (a_start_use) a_started_lat <= 1'b1;

    end

    wire [15:0] dbg_flags = {

        cl2,                // bit15 ★★ 2026-10-04：读写同拍过吗（clash_lat 的同步副本）

        oh2,                // bit14 ★ 占用已满（occ>=512，见上面 occ_hi_m 那段）

        a_started_lat,      // bit13 ★ A 收到过启动脉冲吗

        st_busy,            // bit12 ★ 读口自测还占着读口吗

        ac2,                // bit11 ★ 2026-10-03 转场：正在转场中（transition_ctrl.active）

        ml2,                // bit10 ★ 转场说"屏上全米白，可以去写 SDRAM"（may_load）

        fs2,                // bit9  ★ 前台上的是哪个槽（0=槽0 1=槽1）

        a_load_done,        // bit8  ★ A 装完过一张吗（电平）

        hdmi_locked,        // bit7

        desc_valid[0],      // bit6  ★ A 的描述符有效吗

        rd_allowed,         // bit5  ★ 这一拍存储**愿意收**读请求吗

                            //   （LOAD_WITH_READS 打开时 = mem_rd_ok，

                            //    关掉时 = disp_rd_en_g，两种口径都是"能不能读"）

        disp_rd_en,         // bit4  ★ 显示想不想读

        1'b0,               // bit3  ★ 2026-10-15【逐步减重·第①步】：原接 stwr_busy

                            //   （"自测图写入器还在忙吗"）——该模块已删，且它原本恒 0

                            //   ⇒ 这一位读数与改前完全一致（帧格式/字段数一字未动）。

        a_busy,             // bit2

        sdr_ready,          // bit1

        a_sd_ready          // bit0

    };



    // ============================================================

    //  ★★ 2026-10-01 实验一：Sdr_busy / Sdr_init_ref_vld 到底动不动？

    // ------------------------------------------------------------

    //  要回答的问题（"每 1024 字漏写一个地址"那个已知瑕疵）：

    //    "写使能有效的时候，SDRAM 的忙/刷新标志是不是也高着？"

    //    如果从来没同时高过 → "没管 busy 所以丢字"这条猜测当场否掉。

    //

    //  为什么必须实测：APUG011 手册的表 3-1 把 `Sdr_busy` 标成"暂不使用"，

    //    原厂参考设计的 top 里它甚至是个没声明的隐式 wire（综合器报警告），

    //    原厂测试发生器 app_wrrd 的端口上根本没有这个信号；可手册 2.3 节

    //    和移植注意第 3 条又让你"读写前判断忙不忙"。到底该门控哪一个，

    //    文档自己说不清，只能上板量。

    //

    //  ★ 全部在 clk（50MHz）域数：先把三根线各同步两拍再数。

    //    采样分辨率 20ns，而这三根线的电平都远长于 20ns（刷新要几十拍），够用。

    //    ⇒ 报告里的"拍数"单位是 50MHz 拍，不是 125MHz 拍（差 2.5 倍），

    //      只影响绝对值，不影响"0 / 非 0"和数量级。

    //  ★ 计数器只增不减、饱和在 0xFFFF；串口一条帧 200ms，

    //    要看"速率"就在两次读数之间做差（_check_busy.py 会打印时间戳）。

    // ============================================================

    reg sb1, sb2, rv1, rv2, we1, we2;

    reg sb_d, rv_d;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            sb1 <= 1'b0; sb2 <= 1'b0; rv1 <= 1'b0; rv2 <= 1'b0;

            we1 <= 1'b0; we2 <= 1'b0; sb_d <= 1'b0; rv_d <= 1'b0;

        end

        else begin

            sb1 <= sdr_busy;          sb2 <= sb1;

            rv1 <= sdr_init_ref_vld;  rv2 <= rv1;

            we1 <= sdr_wr_en;         we2 <= we1;

            sb_d <= sb2;              rv_d <= rv2;

        end

    end

    wire sb_hi   = sb2;                 // Sdr_busy         （同步后）

    wire rv_hi   = rv2;                 // Sdr_init_ref_vld （同步后）

    wire we_hi   = we2;                 // 写使能（= App_wr_en）

    wire sb_rise = sb_hi & ~sb_d;       // Sdr_busy 的上升沿



    reg        we_ever, sb_ever, rv_ever, sb_col_ever, rv_col_ever;

    reg [15:0] sb_rise_cnt, sb_col_cnt, rv_col_cnt;

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            we_ever <= 1'b0; sb_ever <= 1'b0; rv_ever <= 1'b0;

            sb_col_ever <= 1'b0; rv_col_ever <= 1'b0;

            sb_rise_cnt <= 16'd0; sb_col_cnt <= 16'd0; rv_col_cnt <= 16'd0;

        end

        else begin

            if (we_hi)          we_ever     <= 1'b1;   // 量的是不是东西，自检

            if (sb_hi)          sb_ever     <= 1'b1;

            if (rv_hi)          rv_ever     <= 1'b1;

            if (we_hi && sb_hi) sb_col_ever <= 1'b1;   // ★ 撞车

            if (we_hi && rv_hi) rv_col_ever <= 1'b1;   // ★ 撞车



            if (sb_rise && sb_rise_cnt != 16'hFFFF)

                sb_rise_cnt <= sb_rise_cnt + 16'd1;

            if (we_hi && sb_hi && sb_col_cnt != 16'hFFFF)

                sb_col_cnt <= sb_col_cnt + 16'd1;

            if (we_hi && rv_hi && rv_col_cnt != 16'hFFFF)

                rv_col_cnt <= rv_col_cnt + 16'd1;

        end

    end



    // 位图：bit4 写使能曾有效 / bit3 busy 撞车 / bit2 刷新撞车

    //       / bit1 busy 曾高 / bit0 刷新标志曾高

    wire [15:0] dbg_busy_flags = {

        11'd0, we_ever, sb_col_ever, rv_col_ever, sb_ever, rv_ever

    };

    // ============================================================
    //  ★★★ 2026-10-24【D5_audback 定位】串口字段 31 临时改送【音频 FSM 卡住判据位图】
    //   现象：aud_st 卡在 1（在等装载时机）、aud_loaded=0 ⇒ 把 aud_st==1 分支那 8 个
    //         门信号的原始电平一次采回来，看是哪一根一直不落（或脉冲卡死）。
    //   引脚：bit0 img_hold / bit1 tr_active / bit2 a_busy / bit3 req_pend_w
    //         bit4 a_start_use / bit5 aud_busy_w / bit6 sub_load_pulse / bit8:7 sub_st
    //   判读：连读几帧，哪一位恒为 1 = 它把 aud_st==1 的门堵死。
    //   原来这里接的是字幕超时次数 sub_rt（字幕链路已定版，暂时让位；查完还原）。
    // ============================================================
    wire [15:0] aud_gate_dbg = {
        7'd0, sub_st, sub_load_pulse, aud_busy_w, a_start_use,
        req_pend_w, a_busy, tr_active, img_hold
    };



    // ============================================================

    //  7. 串口状态输出（黑屏时的"眼睛"，以它为准）

    // ============================================================

    wire [7:0] dbg_status = {

        hdmi_locked,        // bit7

        a_dbg_warn_odd,     // bit6

        a_dbg_overrun,      // bit5

        fail_latch,         // bit4 ★ 锁存过的，不是单拍脉冲

        load_done_latch,    // bit3

        a_busy,             // bit2

        a_sd_ready,         // bit1

        (pll0_locked & pll_sdr_locked)  // bit0

    };



    dbg_report #(

        // ★★★ 2026-10-11【调试临时改动】：PERIOD_MS 200 → 16（≈ 一帧一条），

        //   这样"字幕逐字倒出"的指针每加一次都能被采到一次（一个字不落）。

        //   查完改回 200。

        .CLK_HZ(50_000_000), .PERIOD_MS(200)      // ★ 发布前还原：诊断期的 16 ms 已改回 200

    ) u_dbg (

        .clk(clk), .rst_n(sys_rst_n),

        .val(sdr_wr_cnt),               // ★ W 改成"存储封装一共交接了多少字"

        .status(dbg_status),

        .frm(frame_id_w[7:0]),

        // ★ 第六轮：chk_bad 在真图模式下没有参考价值（它按地址图的期望值比），

        //   这两个字段改接【A 输出过多少个像素】（正常 307200 = 0x0004B000）

        .bad(a_dbg_px_cnt[23:0]),

        // ★★★ 2026-10-03：字段 6..9 改成【转场探针】（见上面那段）——

        //   M1 时代那组"整行扫描"已经不用了，字段 25..28 仍留着旧的那 4 个字。

        // ★ 2026-10-17【面积优化】：转场探针已删（见前面那段说明）⇒ 字段 6~9 恒 0

        // ★★★ 2026-10-17【修 bug · 注释与接线终于一致】：

        //   上一轮只把 `.row0..row3` 接了 0，`.row4..row7` 还接着 `px0..px3`

        //   （"最左列逐行扫描"探针），而 `dbg_report` 用 `reppar` 隔帧在两枝之间切

        //   ⇒ 字段 6~9 有一半的帧报的是那几个像素值，跟"恒 0"的注释不符。

        //   现在把产生逻辑（pass_i/dump_i/px0..px7）整段删了，八字一起接常数。

        .row0(16'd0), .row1(16'd0), .row2(16'd0), .row3(16'd0),

        .row4(16'd0), .row5(16'd0), .row6(16'd0), .row7(16'd0),

        // ★ 诊断位图（见上面 dbg_flags）+ 行缓冲被掐断次数

        // ★ 第六轮：字段11 改接【A 自己报的推字个数】低 16 位（正常 153600 → 0x5800）

        .drop_cnt(dbg_flags), .abort_cnt(a_dbg_wr_cnt[15:0]),

        // ★ 行缓冲探针：请求的行首地址 + 实际收到的头两个字

        // ★ 2026-10-17【面积优化·低风险】：行缓冲探针（字段 13~16）接常数 0

        //   —— 它们每 26 µs 变一次、只有遥测在看，现在不再需要；

        //   `dbg_report` 里对应的冻结寄存器会被综合自然裁掉（帧格式不变）。

        .lb_wbase(dbg_sd_word), .lb_rd0({8'd0, a_sub_dbg[23:16]}),

        .lb_rd1(a_sub_dbg[15:0]),      .lb_words(16'd0),

        // ★ 逐字对齐校验：第 1 个字偏几个 / 本趟几个字不对（0 = 逐字全对）

        //   ★★★ 2026-10-09【临时占用 · 查字幕指纹】：这两个口只在"地址图"模式下有意义

        //      （现在屏上是真照片 ⇒ 它们的读数本来就没意义），借来报字幕指纹：

        //        字段 19 = **片上字幕 RAM 1600 字求和**的低 16 位（对位序/极性敏感）

        //        字段 20 = {bit15 有效, bit10:0 **第一个非零字的下标**}（对行序/内容敏感）

        //      电脑上按同一套规则算 SUB1.SUB 的期望值，一比就知道"片上数据对不对"。

        //      查完字幕再换回 lb_off / lb_alignbad。

        .lb_off(sub_sum16), .lb_alignbad({4'd0, sub_nz_v, sub_nz}),

        // ★ 测试旋钮：当前在途上限档位 / key1 按了多少次

        // ★ M2：字段 29（原 cmp_sel）现在报【当前缩放档 0..5】；字段 30 是 KEY1 按了几次

        .cmp_sel({13'd0, zoom_lv}), .key_cnt({12'd0, key_cnt}),

        // ★★ 2026-09-28 第四轮：这四个字段改接"整行扫描组号 + 第一个错像素的位置/值"

        //    （A 那几个诊断数在自测图模式下本来就没有意义，出图版要的话改回来即可）

        // ★ 第六轮：边缘巡检 —— 字段 21..24 = 组号 / 趟号 / 奇偶 / 看的窗口行

        // ★★★ 2026-10-17【资源分配优化】：字段 21/22/25 的"字幕逐字倒出"探针整套删除

        //   （subtitle_ovl 端口 + dp 计数器 + 顶层连线），这三格改送**常量 0**。

        //   ★ dbg_report 的帧格式 / 字段数（NV=33、NB=134 字节）**一个字未动**；

        //     字段 19/20（字幕指纹：和 = C003 / 首个非零 = 0951）**原样保留**。

        //   ★ 为什么敢删：这两个数只在 2026-10-11~12 那次"字幕逐字倒出"里用过，

        //     结论已固化（0/1600 逐字全对）；现在是真图模式，字段 21/22/25 本来就无判读价值。

        .st_read_cnt(dbg_caro_word),              // 字段 21：轮播/菜单/缩放状态字（见 top_m2 的 dbg_caro_word）

        .st_bad(caro_dbg_cnt),                    // 字段 22：轮播换图请求计数（不换图就一直是 0）

        // ★ 第六轮：字段 23/24 改接【A 请求的长度 a_wr_len】—— "一帧最后 256 个字

        //   没写进 SDRAM"到底是 A 请求短了、还是引擎少写了一段，看

        //   字段 0/1（引擎实写字数）+ 字段 11（A 自己推的字数）+ 这两个数就能定死。

        .st_off(a_wr_len[15:0]),                 // 字段23：A 请求的长度低 16 位

        .st_first({11'd0, a_wr_len[20:16]}),     // 字段24：A 请求的长度高位

        // ★★★ 2026-10-17【资源分配优化】：字段 26 由"音频 FIFO 饿穿探针"

        //   （`aud_dbg_underrun`，2026-10-14 借用的）改成**常量 0** ——

        //   ① 该探针在 show-ahead 协议下永不成立（判据见 a_image\aud_blk_rd.v 端口表）；

        //   ② 真正的饿穿/掐断判据是块级仲裁器的 sticky（`aud_blk_stall`），

        //      走**字段 12 的 bit1**（bit1 = 块级读被掐断过）。

        //   ★ 未"还原成 wr_bursts"：wr_bursts 是 2026-10-04 实验的遗留（结论已固化），

        //     接回去只是把一笔已死的计数器搬回串口，读数上没有任何新信息。

        // ★★★ 2026-10-14 深夜【功能·开关切音频】**字段 27 = {15'd0, sel_aud} 保留** ✗

        //   —— 这是上板判读"SW3 拨到第几条音频"的唯一读数（01/02/03/04），

        //     属于本次明确要保留的字段，**一个字不动**。

        // ★★★ 2026-10-21【D2 · B3】字段 25 从常量 0 改成【兜底页状态】(0=OK 1=LOADING 2=BAD_IMG 3=NO_CARD)

        //   ★ 帧格式/字段数（NV=33）一个字未动；原来这一格就是恒 0，没有别的消费者。

        .st_w0({14'd0, fs_state_w}), .st_w1({12'd0, vol_lv}),

        .st_w2({{(16-SEL_AUD_W){1'b0}}, sel_aud}),

        // ★★ 2026-10-05：字段 28 从"固定 0"改成【音频链状态位图】

        //   高 8 位：bit7=fail bit6=loaded bit5=音频PLL锁 bit4=busy

        //            bit3=有音频数据流 bit2=play_tgl 在翻 bit1:0=状态机(0等图/1等待/2装载/3做完)

        .st_w3({aud_fail, aud_loaded, pll_aud_locked, aud_busy_w,

                aud_dbg_vld, aud_dbg_play_tgl, aud_st,

                // ★★★ 2026-10-09【字段 28 的低 8 位改成字幕状态】（高 8 位音频一字未动）

                //   bit7 sub_loaded(装好了) bit6 sub_fail(失败) bit5 脉冲发过

                //   bit4 a_sub_done 回来过 bit3 sub_overrun bit2 sub_short bit1:0 sub_st

                sub_loaded, sub_fail, sub_pulse_lat, sub_done_lat,

                a_dbg_sub_overrun, a_dbg_sub_short, sub_st}),

        // ★★ 2026-10-04：字段 25..28 从 M1 时代的扫描字 px4..px7 改成【写侧镜像】：

        //    25 = 引擎写字拍数(低16) / 26 = 突发次数 / 27 = 读写同拍拍数 / 28 = A 的段长度(低5)

        // ★★★ 2026-10-17：25/26 现为常量 0、27 为 sel_aud（见上面 ★★★ 那段）

        // ★★ 2026-10-01 实验一：SDRAM 忙 / 刷新 与写使能

        // ★★★ 2026-10-08【最小实验】：字段 29 从"10-01 那次 SDRAM 忙/刷新实验位图"

        //   改成 **显示读请求被推迟的最大拍数**（`rd_defer_max`）——

        //   那次实验的结论早就有了（那两根线的问题被否掉），现在这一格更有用。

        //   判读：0~10 拍 = 一切正常；几百拍 = 被写突发挡过（配合字段 30 的 bit9）。

        .sb_flags({10'd0, fail_src_lat}),          // ★ 诊断：fail 来源粘滞位

        // ★★ 2026-10-06：字段 12 的 bit1 从"tag 队列脱钩过"改成

        //   **音频块级读被看门狗掐断过**（tag 机制整条删掉了，这一位留给音频自检）。

        .tag_bad(aud_blk_stall),

        // ★★★ 2026-10-05（第 8 条）：字段 30/31/32 从"10-01 那次 SDRAM 忙/刷新实验"

        //     改成【音频数据自检】——那次实验的结论早就有了（那两根线的问题被否掉），

        //     现在这三格更有用：

        //       30 = 本次播放已从 SDRAM 收了多少个音频字

        //       31 = 这些字的 32 位累加和【低 16】

        //       32 = 这些字的 32 位累加和【高 16】

        //     ★ 拿它和电脑上按 WAV 算出的期望值比：对上了 = 读回来的音频数据逐字正确。

        // ★★★ 2026-10-06 诊断临时占用（音频现在 AUDIO_OFF=1，它的自检本来就闲着）：

        //   字段 30 = 官方控制器发过多少次 App_rd_en（0 ⇒ 一次读都没发）

        //   字段 31 = 仲裁器服务完几个块（read_fin 次数）

        //   字段 32 = 读 FIFO 的当前占用 + bit15 = "FIFO 曾经非空过"

        // ★★★ 2026-10-06【一个下载要能同时验两件事】：

        //   30 = 读通路整条链的 sticky 位图（显示用）—— 全 1 才算过

        //   31 = 本次播放音频从 SDRAM 收了多少个字（低 16 位；满 3 秒 = 0x1940）

        //   32 = 这些字的 32 位和的【低 16 位】（期望 0x4411，和 = 0xB7464411，

        //        见 sd_card_sfx\sfx_checksum.py 复算）

        //   ⇒ 这一版既有显示、又有音频，一次烧录就能同时判这两条。

        .sb_rise (aud_avg_dbg),    // ★★★ 2026-10-24 临时调试：音频数字平均幅度（原：字幕传输帧数 sub_ft）

        .sb_col  (aud_gate_dbg),   // ★★★ 2026-10-24 临时：音频 FSM 门信号位图（原：字幕超时 sub_rt）

        .rv_col  (aud_dbg_sum[15:0]),

        .uart_tx(uart_tx)

    );



    // 自测图写的时候不读：写完再让显示读

    // ★★ 2026-09-26 晚：把读和写【串行化】—— 这正是 M0 那份上板验过的写路径的做法：

    //    bw_measure 是"先猛写一串 → 显式歇一会儿等写缓冲排空 → 再读"，

    //    它**从来没有让读和写同时进行**。

    //    而我们这版是"显示的读一直不停 + 写穿插在里面"，实测后果是

    //    **写入握手全走完、数据却没真正落进 DRAM**（串口 A=000000/N=140 全对，

    //    但 D0/D1 读回来是未初始化的原始内容）。

    //   所以：B 自测图正在写的那段时间，把显示的读关掉；写完再恢复。

    //   ★ 被掐断的那一次搬运会由 line_buf 的看门狗放弃（65us），不会永久卡死。

    // ★★ 2026-09-27 补：SDRAM 初始化完成之前【绝对不能读写】（厂商文档原话）。

    //    原来只挡了"自测图正在写"那一段，没有挡"初始化还没完"那一段 ——

    //    初始化期间（预充电/刷新/写模式寄存器）被读请求打扰，SDRAM 可能就停在

    //    一个错误模式里，而且会一直错下去。所以这里把 sdr_ready 也加进来。

    // ★★ 2026-09-28：写和读【绝对不能同时进行】—— 原厂的 frame_read_write 就是

    //    用 App_rd_busy / O_wr_busy 把两边串起来的，它从来没有让读写在时间上重叠。

    //    我们这版以前只挡住"自测图在写"的那一段，A 从 SD 卡装载期间显示的读还在跑，

    //    后果就是"写入握手全走完、数据却没落进 DRAM"（2026-09-26 就记过一次）。

    //    现在：自测图在写、A 在装图、SDRAM 还没好 —— 三种情况都把显示的读关掉。

    //    （被掐断的搬运由 line_buf 的看门狗放弃，不会永久卡死；期间屏上是旧内容/杂点，

    //      装完之后自然恢复。）

    // ============================================================

    //  ★★★ 2026-10-03 第二版【读禁用】—— 回到 a_busy 门控，兜底放到 300 秒

    //

    //  历史教训（全是上板换来的）：

    //    · 2026-09-26：读写在时间上重叠 → 握手走完、数据没落进 DRAM

    //    · 2026-10-02：rd_mute 只管到"第一次装完"，从第二张起没禁读 →"越切越花"

    //    · 2026-10-03：兜底时间写错（28 位装不下 5 亿 → 实际只有 4.63 秒）。

    //      这张 1920x1200 的图装载要约 70 秒 → 65 秒里读写在打架，

    //      屏上是"一大片上一张图的残余"；把兜底改到 60 秒后重叠只剩 10 秒，

    //      残余退化成"稀疏花点" —— 坐实了病根是读写重叠。

    //      但 60 秒仍然不够（装载 70 秒），所以这里放到 **300 秒**：

    //      任何真实装载都顶不到，兜底只当"万一 A 卡死"的安全网。

    //

    //  ★ 为什么不用 a_wr_done 门控（试过，不可行）：

    //    按 sdr_arb 的注释，它应该是"引擎报 finish 置 1、下一笔 ack 清 0"的锁存电平，

    //    理论上 ~a_wr_done 是最干净的门控。**实测上板直接白屏**（闸门一直关着、

    //    屏上只剩桌面底色）→ 说明它在这套设计里并不按注释描述工作。

    //    所以回到 a_busy：它覆盖 A 的全部阶段（含 bmp2sdram 等 sdr_done 的 S_WAIT），

    //    是这条链上真正"从头到尾"的信号。

    //

    //  ★ 闸门关着不是黑屏：disp_rd_en_g=0 只是【不读 SDRAM】，合成器照常输出

    //    桌面底色（米白），HDMI 信号不断。装图期间看到底色、装完出图。

    // ============================================================

    reg        rd_load_seen;

    reg [33:0] rd_mute_cnt;      // 34 位：300 秒 @50MHz = 1.5e10 < 2^34

    assign     rd_mute = ~rd_load_seen && (rd_mute_cnt < 34'd15_000_000_000);

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            rd_load_seen <= 1'b0;

            rd_mute_cnt  <= 34'd0;

        end

        else begin

            if (a_load_done) rd_load_seen <= 1'b1;

            if (!rd_load_seen && (rd_mute_cnt < 34'd15_000_000_000))

                rd_mute_cnt <= rd_mute_cnt + 34'd1;

        end

    end



    reg [33:0] abusy_cnt;

    wire       abusy_block = a_busy && (abusy_cnt < 34'd15_000_000_000);

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n)                          abusy_cnt <= 34'd0;

        else if (!a_busy)                        abusy_cnt <= 34'd0;

        else if (abusy_cnt < 34'd15_000_000_000) abusy_cnt <= abusy_cnt + 34'd1;

    end



    // ★★★ 2026-10-08【最小实验】把 `abusy_block` 从这道闸门里去掉：

    //   以前"装载期间整段禁读"（屏上米白）。现在改成**不整段禁读**，

    //   由原厂的读写仲裁（App_rd_busy/App_wr_busy 互相接）去保证"块级交替、不重叠"。

    //   ★ 这条老闸门留在注释里：**回退就是把它加回来**。

    //   ★ stwr_busy（B 自测图写入）仍保留：那条路只在 bring-up 时用，别动它。

    assign disp_rd_en_g = (stwr_busy | ~sdr_ready | rd_mute) ? 1'b0 : disp_rd_en;



    // ============================================================

    //  ★★★ 2026-10-06：块级读通路的收尾（放在这里，所有声明都已就位）

    //    · 旧的"逐拍读请求" `disp_rd_en/disp_rd_addr` 已经没有驱动源了

    //      （line_buf 改成块级）⇒ 打桩成 0，免得 `aud_line_req`、串口 flags、

    //      `rd_idle_cnt` 那些老引用悬空。音频现在 AUDIO_OFF=1，本来也不需要它。

    //    · 块请求走同一个"装载期间禁读"闸门（§6.3-1 红线，条件与上一行完全一致）。

    // ============================================================

    assign disp_rd_en   = 1'b0;

    assign disp_rd_addr = 21'd0;

    // ★★★ 2026-10-08【最小实验】块请求的闸门也不再看 `abusy_block`（装载期间不再禁读）。

    //   ⇒ 装载时显示照常读**旧图**，读写由原厂仲裁做"块级交替"。

    //   回退：把 `| abusy_block` 加回来即可（= 老的"整段禁读"档）。

    assign disp_rd_gate = ~(stwr_busy | ~sdr_ready | rd_mute);

    assign d_blk_req    = d_blk_req_raw & disp_rd_gate;

    // ★ 音频的块请求走【同一道闸门】（装载期间一个读都不发，§6.3-1 红线）。

    assign aud_a_req_g  = aud_a_req & disp_rd_gate;



    // ============================================================

    //  8. 数码管：★ 2026-10-17【面积优化·低风险】整块删掉

    //  ------------------------------------------------------------

    //  原来这里用 6 个 `seg_decoder` + 一个 `seg_scan` 把 `a_dbg_wr_cnt`

    //  （A 轨写字数）显示在板上那 6 位数码管上。实测这块 ≈ 200 LUT，

    //  但**信息并不丢** —— 同一个计数器就在串口字段 11（`.abort_cnt(a_dbg_wr_cnt[15:0])`）

    //  和字段 0/1（`sdr_wr_cnt`）里，而判读一律以串口为准。

    //  ⇒ 为了给音频可视化腾 slice，整块删除，两个引脚输出常灭。

    //  回退：把 `seg_decoder`/`seg_scan` 的实例加回来即可（模块仍在 lib\util\）。

    assign seg_sel  = 6'd0;

    assign seg_data = 8'hFF;      // 段码低有效 ⇒ 全 1 = 全灭





    // ============================================================

    //  ★★★ 2026-10-21【报警换图】报警进入/解除各强制装一次对应的图

    //  ------------------------------------------------------------

    //   为什么不复用轮播：

    //     · 轮播走 stub_ctrl 的 a_skip 自增，skip 是"该类素材里的第几张"，

    //       报警集与正常集的序号是两套语义，混用会错位；

    //     · 这里只要"名字过滤 + skip=0"两件事，组合直通即可。

    //   时序纪律（和字幕/音频那条同一个道理）：必须等 A 闲、转场不在跑、

    //   没有挂起请求、上一首音频停了，才发这个脉冲；否则会把写突发切断。

    // ★★★ 2026-10-22【热插拔提速】卡插回的那一拍，立刻重装一张图
    //   原来只能等 3 s 轮播节拍（CARO_MS=3000）+ 0.5 s 保护窗口 ⇒ 插回后最长要
    //   4 秒多才出图，中间一直是 LOADING/兜底页（现场实测 4.3 s）。
    reg  a_sd_ready_d;
    wire sd_back = sd_ready_eff & ~a_sd_ready_d;   // 0 -> 1 的那一拍

    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) a_sd_ready_d <= 1'b0;
        else            a_sd_ready_d <= sd_ready_eff;
    end

    // ============================================================

    always @(posedge clk or negedge sys_rst_n) begin

        if (!sys_rst_n) begin

            img_load_pulse <= 1'b0;

            img_req_pend   <= 1'b0;

            img_wait       <= 26'd0;

            img_hold       <= 1'b0;

            img_now        <= 1'b0;

        end

        else begin

            img_load_pulse <= 1'b0;

            // ★ 2026-10-21：报警换图这笔独占 SD（脉冲起到 a_load_done/a_fail），压住音频/字幕抢同一个 start 口

            img_hold <= img_load_pulse | (img_hold & ~(a_load_done | a_fail));

            if (alert_rise | alert_fall | sd_back) begin
                img_req_pend <= 1'b1;
                img_now      <= sd_back;      // 卡插回 => 这次不空等 0.5 s
            end

            else if (img_load_pulse) begin
                img_req_pend <= 1'b0;
                img_now      <= 1'b0;
            end



            if (img_req_pend && !tr_active && !a_busy && !req_pend_w && (!aud_busy_w || img_now)) begin

                // 等 0.5 s：让转场先把上一张图收干净，也给串口一个可观测的窗口

                if (img_wait >= (img_now ? 26'd1_000_000 : 26'd25_000_000)) begin

                    img_wait       <= 26'd0;

                    img_load_pulse <= 1'b1;

                    img_req_pend   <= 1'b0;

                end

                else img_wait <= img_wait + 26'd1;

            end

            else img_wait <= 26'd0;

        end

    end



    // ============================================================
    //  2026-10-21 ALARM BUZZER: on-board buzzer spk = H11 (see m2_pin.adc back-up note).
    //    alert_on=1 -> 2 kHz square (works for both active and passive buzzers),
    //    gated 0.4 s on / 0.3 s off so it sounds like an alarm, not a continuous tone.
    //    Polarity not verified on board: if it beeps when NOT alarming, invert spk.
    //    The hardware "buzzer enable" switch on the board must be ON; FPGA cannot read it.
    // ============================================================
    reg [13:0] spk_div;
    reg        spk_tone;
    reg [24:0] spk_gate_cnt;
    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            spk_div      <= 14'd0;
            spk_tone     <= 1'b0;
            spk_gate_cnt <= 25'd0;
        end
        else begin
            if (spk_div >= 14'd12_499) begin spk_div <= 14'd0; spk_tone <= ~spk_tone; end
            else                             spk_div <= spk_div + 14'd1;
            if (spk_gate_cnt >= 25'd34_999_999) spk_gate_cnt <= 25'd0;
            else                                spk_gate_cnt <= spk_gate_cnt + 25'd1;
        end
    end
    wire spk_gate = (spk_gate_cnt < 25'd20_000_000);
    assign spk = alert_on & spk_gate & spk_tone;

    // ============================================================
    //  ★★★ 2026-10-25【MULTI BOOT · SW3 切显示分辨率】
    // ------------------------------------------------------------
    //  · FLASH 里放两套位流（W25Q16，16 Mbit = 2 MB）：
    //        0x000000：800×600 版（Primary）
    //        0x0A0000：1024×768 版（Second）
    //    每套 643 KB ≈ 10 个 64 KB 扇区，0x0A0000 之后正好放得下第二套。
    //  · 拨 SW3 = 登记一次「切到另一套」的请求；**当前这张图不切**，
    //    等轮播下一次请求换图（`adv_req_w`）时才把 `rebootn` 拉低 ⇒ FPGA 从
    //    另一套位流的起始地址重新配置（黑屏约 0.2~0.4 s），随后换分辨率启动。
    //  · 两套代码唯一的差别就是下面 `RES_JUMP_ADDR`：
    //        800×600 版（烧 0x000000）填 8'h0A  → 跳到 1024×768
    //        1024×768 版（烧 0x0A0000）填 8'h00 → 跳回 800×600
    //    （`dynamic_addr` 是跳转地址的高 8 位：8'h0A = 0x0A0000，8'h00 = 0x000000。）
    //  · 注意：加了 EG_LOGIC_MBOOT 之后，FLASH 必须用 `download -mode program_spi
    //    -start_addr 0x…`（MULTI BOOT 模式）烧写，不能再走普通 JTAG 烧写。
    // ============================================================
    localparam [7:0] RES_JUMP_ADDR = 8'h00;   // ★ 本镜像 = 1024×768（烧 0x0A0000）

    reg res_switch_pend;   // SW3 已拨过：等「下一张图」再切
    reg mboot_reboot_n;    // EG_LOGIC_MBOOT 的 rebootn（低有效 = 从 FLASH 另一地址重载）

    // ---- ★★★ 2026-10-25【不黑屏】白闪：重配置黑屏用「白闪 + 新图」代替 ----
    //  原来：下一张图请求 → 立刻重配置 → 电视黑屏 0.2~0.4 s → 新分辨率首图（还要 1.5 s）→ 很突兀。
    //  现在：①开机（含重配置后的新镜像）先整屏白 ~1.6 s，盖住 SD 装首图那段；
    //        ②切换时先把当前画面整屏白闪 50 ms，再拉低 rebootn 重配置；
    //        ③新镜像启动又是白屏 → 装好首图直接出画面。
    //  观感 =「白闪一下 → 新图」，黑屏被白闪吃掉了。
    reg        wb_switch_white;      // 切换白闪中
    reg [22:0] wb_dly;               // 白闪计时
    reg [26:0] wb_boot_cnt;          // 开机计数（白屏时长）
    localparam [26:0] WB_BOOT_TICKS = 27'd80_000_000;  // 1.6 s @ 50 MHz
    localparam [22:0] WB_DLY_TICKS  = 23'd2_500_000;   // 50 ms @ 50 MHz
    wire wb_boot_white = (wb_boot_cnt < WB_BOOT_TICKS);

    always @(posedge clk or negedge sys_rst_n) begin
        if (!sys_rst_n) begin
            res_switch_pend <= 1'b0;
            mboot_reboot_n  <= 1'b1;
            wb_switch_white <= 1'b0;
            wb_dly          <= 23'd0;
            wb_boot_cnt     <= 27'd0;
        end
        else begin
            // 开机白屏计时
            if (wb_boot_cnt < WB_BOOT_TICKS)
                wb_boot_cnt <= wb_boot_cnt + 1'b1;

            // ① SW3 只登记，这一张图**不动**
            if (sw3_change)
                res_switch_pend <= 1'b1;

            // ② 「下一张图」的请求来了 → 先白闪，不马上切
            if (res_switch_pend && adv_req_w && !wb_switch_white) begin
                res_switch_pend <= 1'b0;
                wb_switch_white <= 1'b1;
                wb_dly          <= 23'd0;
            end

            // ③ 白闪满 50 ms → 才拉低 rebootn 重配置（此刻屏幕已经是白的）
            if (wb_switch_white) begin
                if (wb_dly >= WB_DLY_TICKS) begin
                    wb_switch_white <= 1'b0;
                    mboot_reboot_n  <= 1'b0;
                end
                else
                    wb_dly <= wb_dly + 1'b1;
            end
        end
    end

    assign wb_white = wb_boot_white | wb_switch_white;

    EG_LOGIC_MBOOT #(
        .ADDR_SOURCE_SEL ("DYNAMIC"),
        .STATIC_ADDR     (8'b00000000)
    ) u_mboot (
        .rebootn      (mboot_reboot_n),
        .dynamic_addr (RES_JUMP_ADDR)
    );

endmodule
